  'Jobsence is not affiliated with this department / company. Apply only on the official website and beware of anyone asking for money for a job. The Jobs Pass fee is not a government fee.' => 'Jobsence ਇਸ ਵਿਭਾਗ / ਕੰਪਨੀ ਨਾਲ ਸੰਬੰਧਿਤ ਨਹੀਂ ਹੈ। ਸਿਰਫ਼ ਅਧਿਕਾਰਤ ਵੈੱਬਸਾਈਟ \'ਤੇ ਹੀ ਅਪਲਾਈ ਕਰੋ ਅਤੇ ਨੌਕਰੀ ਦੇ ਬਦਲੇ ਪੈਸੇ ਮੰਗਣ ਵਾਲੇ ਕਿਸੇ ਵੀ ਵਿਅਕਤੀ ਤੋਂ ਸਾਵਧਾਨ ਰਹੋ। Jobs Pass ਫ਼ੀਸ ਕੋਈ ਸਰਕਾਰੀ ਫ਼ੀਸ ਨਹੀਂ ਹੈ।',
