  'See all →' => 'ਸਾਰੇ ਵੇਖੋ →',
  'Jobsence is a platform, not a recruiting agent. ECR passport holders must emigrate only through agents registered on eMigrate (emigrate.gov.in). Never pay anyone for a job or visa.' => 'Jobsence ਇੱਕ ਪਲੇਟਫ਼ਾਰਮ ਹੈ, ਭਰਤੀ ਏਜੰਟ ਨਹੀਂ। ECR ਪਾਸਪੋਰਟ ਧਾਰਕਾਂ ਨੂੰ ਸਿਰਫ਼ eMigrate (emigrate.gov.in) \'ਤੇ ਰਜਿਸਟਰਡ ਏਜੰਟਾਂ ਰਾਹੀਂ ਹੀ ਵਿਦੇਸ਼ ਜਾਣਾ ਚਾਹੀਦਾ ਹੈ। ਨੌਕਰੀ ਜਾਂ ਵੀਜ਼ੇ ਲਈ ਕਦੇ ਵੀ ਕਿਸੇ ਨੂੰ ਪੈਸੇ ਨਾ ਦਿਓ।',
  'Companies hiring abroad' => 'ਵਿਦੇਸ਼ ਵਿੱਚ ਭਰਤੀ ਕਰਨ ਵਾਲੀਆਂ ਕੰਪਨੀਆਂ',
  'Hiring for jobs abroad? Register free' => 'ਵਿਦੇਸ਼ੀ ਨੌਕਰੀਆਂ ਲਈ ਭਰਤੀ ਕਰਦੇ ਹੋ? ਮੁਫ਼ਤ ਰਜਿਸਟਰ ਕਰੋ',
  'Paid internships (₹8,000 to ₹5,00,000 a month stipend) and unpaid – both.' => 'ਪੇਡ ਇੰਟਰਨਸ਼ਿਪ (₹8,000 ਤੋਂ ₹5,00,000 ਪ੍ਰਤੀ ਮਹੀਨਾ ਵਜ਼ੀਫ਼ਾ) ਅਤੇ ਬਿਨਾਂ ਭੁਗਤਾਨ ਵਾਲੀਆਂ – ਦੋਵੇਂ।',
  '3000+ domains: IT, marketing, accounts, HR, design, healthcare and more.' => '3000+ ਡੋਮੇਨ: IT, ਮਾਰਕੀਟਿੰਗ, ਅਕਾਊਂਟਸ, HR, ਡਿਜ਼ਾਈਨ, ਹੈਲਥਕੇਅਰ ਅਤੇ ਹੋਰ।',
  'Choose up to 5 of 3000+ skills – you are trained only in those.' => '3000+ ਹੁਨਰਾਂ ਵਿੱਚੋਂ ਵੱਧ ਤੋਂ ਵੱਧ 5 ਚੁਣੋ – ਤੁਹਾਨੂੰ ਸਿਰਫ਼ ਉਨ੍ਹਾਂ ਵਿੱਚ ਹੀ ਸਿਖਲਾਈ ਮਿਲੇਗੀ।',
  'Email as soon as a mentor accepts; registration is valid for 3 months.' => 'ਜਿਵੇਂ ਹੀ ਮੈਂਟਰ ਸਵੀਕਾਰ ਕਰੇ, ਈਮੇਲ ਆਵੇਗੀ; ਰਜਿਸਟ੍ਰੇਸ਼ਨ 3 ਮਹੀਨਿਆਂ ਲਈ ਵੈਧ ਹੈ।',
  'Providers register free; the ₹155 plan opens 3 profiles a day for 10 days, up to 20.' => 'ਪ੍ਰਦਾਤਾ ਮੁਫ਼ਤ ਰਜਿਸਟਰ ਕਰਦੇ ਹਨ; ₹155 ਪਲਾਨ ਨਾਲ 10 ਦਿਨਾਂ ਲਈ ਰੋਜ਼ਾਨਾ 3 ਪ੍ਰੋਫ਼ਾਈਲਾਂ ਖੁੱਲ੍ਹਦੀਆਂ ਹਨ, ਵੱਧ ਤੋਂ ਵੱਧ 20।',
  'Phone and email only after the tripartite agreement.' => 'ਫ਼ੋਨ ਅਤੇ ਈਮੇਲ ਸਿਰਫ਼ ਤ੍ਰਿਪੱਖੀ ਸਮਝੌਤੇ ਤੋਂ ਬਾਅਦ।',
  'Companies register free; the ₹155 plan opens 3 full candidate profiles with resume a day.' => 'ਕੰਪਨੀਆਂ ਮੁਫ਼ਤ ਰਜਿਸਟਰ ਕਰਦੀਆਂ ਹਨ; ₹155 ਪਲਾਨ ਨਾਲ ਰੋਜ਼ਾਨਾ ਰਿਜ਼ਿਊਮ ਸਮੇਤ 3 ਉਮੀਦਵਾਰਾਂ ਦੀਆਂ ਪੂਰੀਆਂ ਪ੍ਰੋਫ਼ਾਈਲਾਂ ਖੁੱਲ੍ਹਦੀਆਂ ਹਨ।',
  'Search by your current location, or type your area / PIN code.' => 'ਆਪਣੀ ਮੌਜੂਦਾ ਲੋਕੇਸ਼ਨ ਨਾਲ ਖੋਜੋ, ਜਾਂ ਆਪਣਾ ਇਲਾਕਾ / PIN ਕੋਡ ਲਿਖੋ।',
  'Every provider is photo and live-selfie verified; number after the agreement.' => 'ਹਰ ਪ੍ਰਦਾਤਾ ਫ਼ੋਟੋ ਅਤੇ ਲਾਈਵ ਸੈਲਫ਼ੀ ਨਾਲ ਤਸਦੀਕਸ਼ੁਦਾ ਹੈ; ਨੰਬਰ ਸਮਝੌਤੇ ਤੋਂ ਬਾਅਦ।',
  'Mentors and institutes register free; learners fill the ₹155 form.' => 'ਮੈਂਟਰ ਅਤੇ ਸੰਸਥਾਵਾਂ ਮੁਫ਼ਤ ਰਜਿਸਟਰ ਕਰਦੇ ਹਨ; ਸਿੱਖਣ ਵਾਲੇ ₹155 ਵਾਲਾ ਫ਼ਾਰਮ ਭਰਦੇ ਹਨ।',
  'Phone and email only after the tripartite agreement (candidate + mentor + Jobsence).' => 'ਫ਼ੋਨ ਅਤੇ ਈਮੇਲ ਸਿਰਫ਼ ਤ੍ਰਿਪੱਖੀ ਸਮਝੌਤੇ (ਉਮੀਦਵਾਰ + ਮੈਂਟਰ + Jobsence) ਤੋਂ ਬਾਅਦ।',
  'Govt, PSU, railway, police and top company jobs in one place.' => 'ਸਰਕਾਰੀ, PSU, ਰੇਲਵੇ, ਪੁਲਿਸ ਅਤੇ ਵੱਡੀਆਂ ਕੰਪਨੀਆਂ ਦੀਆਂ ਨੌਕਰੀਆਂ ਇੱਕ ਥਾਂ \'ਤੇ।',
  '30,000+ job categories – register once, get a call / email on a match.' => '30,000+ ਨੌਕਰੀ ਸ਼੍ਰੇਣੀਆਂ – ਇੱਕ ਵਾਰ ਰਜਿਸਟਰ ਕਰੋ, ਮੇਲ ਹੋਣ \'ਤੇ ਕਾਲ / ਈਮੇਲ ਪ੍ਰਾਪਤ ਕਰੋ।',
  'incl. GST, one-time' => 'GST ਸਮੇਤ, ਇੱਕ ਵਾਰ',
  'Find a mentor – apply' => 'ਮੈਂਟਰ ਲੱਭੋ – ਅਪਲਾਈ ਕਰੋ',
  'Want an internship – apply' => 'ਇੰਟਰਨਸ਼ਿਪ ਚਾਹੀਦੀ ਹੈ – ਅਪਲਾਈ ਕਰੋ',
  'Want a job – apply' => 'ਨੌਕਰੀ ਚਾਹੀਦੀ ਹੈ – ਅਪਲਾਈ ਕਰੋ',
  'Need a service – Near Me pass' => 'ਸੇਵਾ ਚਾਹੀਦੀ ਹੈ – Near Me ਪਾਸ',
  'Provide a service? Enrol' => 'ਸੇਵਾ ਦਿੰਦੇ ਹੋ? ਨਾਮ ਦਰਜ ਕਰਾਓ',
  'Registration free · unlock ' => 'ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਮੁਫ਼ਤ · ਅਨਲੌਕ ',
  'See all' => 'ਸਾਰੇ ਵੇਖੋ',
  'Other countries' => 'ਹੋਰ ਦੇਸ਼',
  'Frequently asked questions' => 'ਅਕਸਰ ਪੁੱਛੇ ਜਾਣ ਵਾਲੇ ਸਵਾਲ',
  'What is the registration fee?' => 'ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਫ਼ੀਸ ਕਿੰਨੀ ਹੈ?',
  '₹155 (including GST), one-time, non-refundable.' => '₹155 (GST ਸਮੇਤ), ਇੱਕ ਵਾਰ, ਵਾਪਸੀਯੋਗ ਨਹੀਂ।',
  'Is a job or placement guaranteed?' => 'ਕੀ ਨੌਕਰੀ ਜਾਂ ਪਲੇਸਮੈਂਟ ਦੀ ਗਾਰੰਟੀ ਹੈ?',
  'No. Jobsence tries to share your profile with suitable companies and mentors.' => 'ਨਹੀਂ। Jobsence ਤੁਹਾਡੀ ਪ੍ਰੋਫ਼ਾਈਲ ਢੁਕਵੀਆਂ ਕੰਪਨੀਆਂ ਅਤੇ ਮੈਂਟਰਾਂ ਨਾਲ ਸਾਂਝੀ ਕਰਨ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰਦਾ ਹੈ।',
  'Is this a Government scheme?' => 'ਕੀ ਇਹ ਸਰਕਾਰੀ ਸਕੀਮ ਹੈ?',
  'No. This is Jobsence’s initiative to make India skilled – not a Government of India scheme.' => 'ਨਹੀਂ। ਇਹ ਭਾਰਤ ਨੂੰ ਹੁਨਰਮੰਦ ਬਣਾਉਣ ਲਈ Jobsence ਦੀ ਪਹਿਲ ਹੈ – ਭਾਰਤ ਸਰਕਾਰ ਦੀ ਸਕੀਮ ਨਹੀਂ।',
  'This agreement was not found. Open the link from your email again.' => 'ਇਹ ਸਮਝੌਤਾ ਨਹੀਂ ਮਿਲਿਆ। ਆਪਣੀ ਈਮੇਲ ਵਾਲਾ ਲਿੰਕ ਦੁਬਾਰਾ ਖੋਲ੍ਹੋ।',
  'Dashboard' => 'ਡੈਸ਼ਬੋਰਡ',
  'Awaiting signatures' => 'ਦਸਤਖ਼ਤਾਂ ਦੀ ਉਡੀਕ',
  'Complete – signed by all three' => 'ਪੂਰਾ – ਤਿੰਨਾਂ ਵੱਲੋਂ ਦਸਤਖ਼ਤ ਕੀਤੇ ਗਏ',
