  'Terms' => 'ਸ਼ਰਤਾਂ',
  'version' => 'ਸੰਸਕਰਣ',
  'Signatures' => 'ਦਸਤਖ਼ਤ',
  'Provider' => 'ਪ੍ਰਦਾਤਾ',
  'Pending' => 'ਬਾਕੀ',
  'Contact' => 'ਸੰਪਰਕ',
