  'Use these details only for this purpose.' => 'ਇਹ ਵੇਰਵੇ ਸਿਰਫ਼ ਇਸੇ ਮਕਸਦ ਲਈ ਵਰਤੋ।',
  'Print / save as PDF' => 'ਪ੍ਰਿੰਟ ਕਰੋ / PDF ਵਜੋਂ ਸੇਵ ਕਰੋ',
  'Reject my mentor / provider' => 'ਮੇਰੇ ਮੈਂਟਰ / ਪ੍ਰਦਾਤਾ ਨੂੰ ਅਸਵੀਕਾਰ ਕਰੋ',
  'End this agreement' => 'ਇਹ ਸਮਝੌਤਾ ਖ਼ਤਮ ਕਰੋ',
  'Note: if you reject, your registration closes and a new form fee is needed for a new mentor / internship.' => 'ਨੋਟ: ਜੇ ਤੁਸੀਂ ਅਸਵੀਕਾਰ ਕਰਦੇ ਹੋ, ਤਾਂ ਤੁਹਾਡੀ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਬੰਦ ਹੋ ਜਾਵੇਗੀ ਅਤੇ ਨਵੇਂ ਮੈਂਟਰ / ਇੰਟਰਨਸ਼ਿਪ ਲਈ ਨਵੀਂ ਫ਼ਾਰਮ ਫ਼ੀਸ ਦੇਣੀ ਪਵੇਗੀ।',
  'I understand and want to end it' => 'ਮੈਂ ਸਮਝਦਾ/ਸਮਝਦੀ ਹਾਂ ਅਤੇ ਇਸ ਨੂੰ ਖ਼ਤਮ ਕਰਨਾ ਚਾਹੁੰਦਾ/ਚਾਹੁੰਦੀ ਹਾਂ',
  'End agreement' => 'ਸਮਝੌਤਾ ਖਤਮ ਕਰੋ',
  'You have signed. Waiting for the other party – you will get an email once it is complete.' => 'ਤੁਸੀਂ ਦਸਤਖਤ ਕਰ ਦਿੱਤੇ ਹਨ। ਦੂਜੀ ਧਿਰ ਦੀ ਉਡੀਕ ਹੈ – ਪੂਰਾ ਹੁੰਦੇ ਹੀ ਤੁਹਾਨੂੰ ਈਮੇਲ ਮਿਲੇਗੀ।',
  'Choose a hiring plan – then sign here' => 'ਭਰਤੀ ਪਲਾਨ ਚੁਣੋ – ਫਿਰ ਇੱਥੇ ਦਸਤਖਤ ਕਰੋ',
  'Sign with an email OTP' => 'ਈਮੇਲ OTP ਨਾਲ ਦਸਤਖਤ ਕਰੋ',
  'Resend OTP' => 'OTP ਦੁਬਾਰਾ ਭੇਜੋ',
  '1. Send OTP to my email' => '1. ਮੇਰੀ ਈਮੇਲ \'ਤੇ OTP ਭੇਜੋ',
  'I have read and accept all the terms above.' => 'ਮੈਂ ਉੱਪਰ ਦਿੱਤੀਆਂ ਸਾਰੀਆਂ ਸ਼ਰਤਾਂ ਪੜ੍ਹ ਲਈਆਂ ਹਨ ਅਤੇ ਸਵੀਕਾਰ ਕਰਦਾ/ਕਰਦੀ ਹਾਂ।',
  '2. Sign agreement' => '2. ਸਮਝੌਤੇ \'ਤੇ ਦਸਤਖਤ ਕਰੋ',
  'Decline this request' => 'ਇਹ ਬੇਨਤੀ ਅਸਵੀਕਾਰ ਕਰੋ',
  'Declining before signing costs nothing.' => 'ਦਸਤਖਤ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਅਸਵੀਕਾਰ ਕਰਨ \'ਤੇ ਕੋਈ ਖਰਚਾ ਨਹੀਂ।',
  'Agreement signed' => 'ਸਮਝੌਤੇ \'ਤੇ ਦਸਤਖਤ ਹੋ ਗਏ',
  'Cancelled' => 'ਰੱਦ',
  'My Mentoring Dashboard' => 'ਮੇਰਾ ਮੈਂਟਰਿੰਗ ਡੈਸ਼ਬੋਰਡ',
  'Skill and internship seekers fill the ₹155 form. Mentors, institutes, group mentors and internship companies register free. Phone and email only after both have paid and signed the tripartite agreement.' => 'ਹੁਨਰ ਅਤੇ ਇੰਟਰਨਸ਼ਿਪ ਚਾਹੁਣ ਵਾਲੇ ₹155 ਦਾ ਫਾਰਮ ਭਰਦੇ ਹਨ। ਮੈਂਟਰ, ਸੰਸਥਾਵਾਂ, ਗਰੁੱਪ ਮੈਂਟਰ ਅਤੇ ਇੰਟਰਨਸ਼ਿਪ ਕੰਪਨੀਆਂ ਮੁਫ਼ਤ ਰਜਿਸਟਰ ਕਰਦੀਆਂ ਹਨ। ਫ਼ੋਨ ਅਤੇ ਈਮੇਲ ਸਿਰਫ਼ ਉਦੋਂ, ਜਦੋਂ ਦੋਵਾਂ ਨੇ ਭੁਗਤਾਨ ਕਰ ਦਿੱਤਾ ਹੋਵੇ ਅਤੇ ਤਿੰਨ-ਧਿਰੀ ਸਮਝੌਤੇ \'ਤੇ ਦਸਤਖਤ ਕਰ ਦਿੱਤੇ ਹੋਣ।',
  'Apply – ₹155' => 'ਅਰਜ਼ੀ ਦਿਓ – ₹155',
  'See ' => 'ਵੇਖੋ ',
  'Already registered? Open the “My mentoring dashboard” link in your receipt or email.' => 'ਪਹਿਲਾਂ ਹੀ ਰਜਿਸਟਰ ਹੋ? ਆਪਣੀ ਰਸੀਦ ਜਾਂ ਈਮੇਲ ਵਿੱਚ “ਮੇਰਾ ਮੈਂਟਰਿੰਗ ਡੈਸ਼ਬੋਰਡ” ਲਿੰਕ ਖੋਲ੍ਹੋ।',
  'My countries' => 'ਮੇਰੇ ਦੇਸ਼',
  'Each country one-time ₹1,180 (₹1,000 + GST) or USD 10 – employers in that country can see you.' => 'ਹਰ ਦੇਸ਼ ਲਈ ਇੱਕ ਵਾਰ ₹1,180 (₹1,000 + GST) ਜਾਂ USD 10 – ਉਸ ਦੇਸ਼ ਦੇ ਰੁਜ਼ਗਾਰਦਾਤਾ ਤੁਹਾਨੂੰ ਵੇਖ ਸਕਣਗੇ।',
  'pay' => 'ਭੁਗਤਾਨ ਕਰੋ',
  'No country unlocked yet – add one below.' => 'ਅਜੇ ਕੋਈ ਦੇਸ਼ ਅਨਲੌਕ ਨਹੀਂ – ਹੇਠਾਂ ਜੋੜੋ।',
  'Unlock – ₹1,180' => 'ਅਨਲੌਕ ਕਰੋ – ₹1,180',
  'Unlock – USD 10' => 'ਅਨਲੌਕ ਕਰੋ – USD 10',
  'Your Near Me pass is active till ' => 'ਤੁਹਾਡਾ Near Me ਪਾਸ ਇਸ ਤਾਰੀਖ ਤੱਕ ਸਰਗਰਮ ਹੈ: ',
  'Your registration is active – valid until you are matched.' => 'ਤੁਹਾਡੀ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਸਰਗਰਮ ਹੈ – ਮੇਲ ਹੋਣ ਤੱਕ ਵੈਧ।',
  'See & choose ' => 'ਵੇਖੋ ਅਤੇ ਚੁਣੋ ',
  'You are matched – open the agreement below for contact details.' => 'ਤੁਹਾਡਾ ਮੇਲ ਹੋ ਗਿਆ ਹੈ – ਸੰਪਰਕ ਵੇਰਵਿਆਂ ਲਈ ਹੇਠਾਂ ਸਮਝੌਤਾ ਖੋਲ੍ਹੋ।',
  'Your registration is closed. Fill a new form.' => 'ਤੁਹਾਡੀ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਬੰਦ ਹੈ। ਨਵਾਂ ਫਾਰਮ ਭਰੋ।',
  'Fill a new form' => 'ਨਵਾਂ ਫਾਰਮ ਭਰੋ',
  'Jobsence verified' => 'Jobsence ਦੁਆਰਾ ਤਸਦੀਕਸ਼ੁਦਾ',
  'Verification pending – after that you are listed and can sign' => 'ਤਸਦੀਕ ਬਾਕੀ ਹੈ – ਉਸ ਤੋਂ ਬਾਅਦ ਤੁਸੀਂ ਸੂਚੀ ਵਿੱਚ ਦਿਖੋਗੇ ਅਤੇ ਦਸਤਖਤ ਕਰ ਸਕੋਗੇ',
  'Your Near Me listing is active till ' => 'ਤੁਹਾਡੀ Near Me ਲਿਸਟਿੰਗ ਇਸ ਤਾਰੀਖ ਤੱਕ ਸਰਗਰਮ ਹੈ: ',
  'Your listing has expired.' => 'ਤੁਹਾਡੀ ਲਿਸਟਿੰਗ ਦੀ ਮਿਆਦ ਖਤਮ ਹੋ ਗਈ ਹੈ।',
