  'Schedule' => 'ਸਮਾਂ-ਸਾਰਣੀ',
  '2 hours/day, 3 days a week, including practical training.' => 'ਰੋਜ਼ 2 ਘੰਟੇ, ਹਫ਼ਤੇ ਵਿੱਚ 3 ਦਿਨ, ਪ੍ਰੈਕਟੀਕਲ ਸਿਖਲਾਈ ਸਮੇਤ।',
  'Online Video Classes – Pan-India' => 'ਔਨਲਾਈਨ ਵੀਡੀਓ ਕਲਾਸਾਂ – ਪੂਰੇ ਭਾਰਤ ਵਿੱਚ',
  'Learn from anywhere on your mobile or computer.' => 'ਆਪਣੇ ਮੋਬਾਈਲ ਜਾਂ ਕੰਪਿਊਟਰ \'ਤੇ ਕਿਤੋਂ ਵੀ ਸਿੱਖੋ।',
  'Offline Classes – Delhi-NCR only' => 'ਔਫਲਾਈਨ ਕਲਾਸਾਂ – ਸਿਰਫ਼ ਦਿੱਲੀ-NCR',
  'Classroom learning with hands-on practical training.' => 'ਹੱਥੀਂ ਪ੍ਰੈਕਟੀਕਲ ਸਿਖਲਾਈ ਦੇ ਨਾਲ ਕਲਾਸਰੂਮ ਵਿੱਚ ਪੜ੍ਹਾਈ।',
  'Hindi, English or local/regional language – depending on mentor availability.' => 'ਹਿੰਦੀ, ਅੰਗਰੇਜ਼ੀ ਜਾਂ ਸਥਾਨਕ/ਖੇਤਰੀ ਭਾਸ਼ਾ – ਮੈਂਟਰ ਦੀ ਉਪਲਬਧਤਾ ਅਨੁਸਾਰ।',
  '2000+ skills – a few examples' => '2000+ ਹੁਨਰ – ਕੁਝ ਉਦਾਹਰਣਾਂ',
  'Training is delivered by the Jobsence Mentor Team and third-party skill development partners.' => 'ਸਿਖਲਾਈ Jobsence ਮੈਂਟਰ ਟੀਮ ਅਤੇ ਤੀਜੀ-ਧਿਰ ਸਕਿੱਲ ਡਿਵੈਲਪਮੈਂਟ ਭਾਈਵਾਲਾਂ ਵੱਲੋਂ ਦਿੱਤੀ ਜਾਂਦੀ ਹੈ।',
  'Fee Structure' => 'ਫੀਸ ਢਾਂਚਾ',
  'One-time processing fee (including GST)' => 'ਇੱਕ ਵਾਰ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਫੀਸ (GST ਸਮੇਤ)',
  'Total course fee after selection' => 'ਚੋਣ ਤੋਂ ਬਾਅਦ ਕੁੱਲ ਕੋਰਸ ਫੀਸ',
