  'Jobsence is building its own Team of Mentors to give skills to unemployed youth of India. If you are good at any skill, enrol yourself.' => 'Jobsence ਭਾਰਤ ਦੇ ਬੇਰੁਜ਼ਗਾਰ ਨੌਜਵਾਨਾਂ ਨੂੰ ਹੁਨਰ ਦੇਣ ਲਈ ਆਪਣੀ ਮੈਂਟਰ ਟੀਮ ਬਣਾ ਰਿਹਾ ਹੈ। ਜੇ ਤੁਸੀਂ ਕਿਸੇ ਵੀ ਹੁਨਰ ਵਿੱਚ ਚੰਗੇ ਹੋ, ਤਾਂ ਆਪਣਾ ਨਾਮ ਦਰਜ ਕਰਵਾਓ।',
  'Fixed Emolument' => 'ਨਿਸ਼ਚਿਤ ਮਾਣ-ਭੱਤਾ',
  'Fixed payment per candidate – for video / online and offline (Delhi-NCR) classes, paid after training is completed.' => 'ਪ੍ਰਤੀ ਉਮੀਦਵਾਰ ਨਿਸ਼ਚਿਤ ਭੁਗਤਾਨ – ਵੀਡੀਓ / ਔਨਲਾਈਨ ਅਤੇ ਔਫਲਾਈਨ (ਦਿੱਲੀ-NCR) ਕਲਾਸਾਂ ਲਈ, ਸਿਖਲਾਈ ਪੂਰੀ ਹੋਣ ਤੋਂ ਬਾਅਦ ਭੁਗਤਾਨ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।',
  'Demo Video' => 'ਡੈਮੋ ਵੀਡੀਓ',
  'Send your details with a demo video that mentions “This video is for Jobsence Skill Development”.' => 'ਆਪਣੇ ਵੇਰਵੇ ਇੱਕ ਡੈਮੋ ਵੀਡੀਓ ਨਾਲ ਭੇਜੋ ਜਿਸ ਵਿੱਚ ਕਿਹਾ ਗਿਆ ਹੋਵੇ “This video is for Jobsence Skill Development”।',
  'Conditions' => 'ਸ਼ਰਤਾਂ',
  'Fill Mentor Enrolment Form' => 'ਮੈਂਟਰ ਦਾਖਲਾ ਫਾਰਮ ਭਰੋ',
  'Declaration & Disclaimer' => 'ਘੋਸ਼ਣਾ ਅਤੇ ਬੇਦਾਅਵਾ',
  'Jobsence does not guarantee any job or placement.' => 'Jobsence ਕਿਸੇ ਵੀ ਨੌਕਰੀ ਜਾਂ ਪਲੇਸਮੈਂਟ ਦੀ ਗਰੰਟੀ ਨਹੀਂ ਦਿੰਦਾ।',
  'We only try to push your resume to companies, make you job-ready, or guide you towards self-employment.' => 'ਅਸੀਂ ਸਿਰਫ਼ ਤੁਹਾਡਾ ਰਿਜ਼ਿਊਮ ਕੰਪਨੀਆਂ ਤੱਕ ਪਹੁੰਚਾਉਣ, ਤੁਹਾਨੂੰ ਨੌਕਰੀ ਲਈ ਤਿਆਰ ਕਰਨ, ਜਾਂ ਸਵੈ-ਰੁਜ਼ਗਾਰ ਵੱਲ ਮਾਰਗਦਰਸ਼ਨ ਕਰਨ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰਦੇ ਹਾਂ।',
  'This is Jobsence’s initiative to make India skilled – not a Government of India scheme.' => 'ਇਹ ਭਾਰਤ ਨੂੰ ਹੁਨਰਮੰਦ ਬਣਾਉਣ ਲਈ Jobsence ਦੀ ਪਹਿਲਕਦਮੀ ਹੈ – ਭਾਰਤ ਸਰਕਾਰ ਦੀ ਯੋਜਨਾ ਨਹੀਂ।',
  'Frequently Asked Questions' => 'ਅਕਸਰ ਪੁੱਛੇ ਜਾਣ ਵਾਲੇ ਸਵਾਲ',
  'Internship / Job forms' => 'ਇੰਟਰਨਸ਼ਿਪ / ਨੌਕਰੀ ਫਾਰਮ',
  'Skill Development by State / UT' => 'ਰਾਜ / ਕੇਂਦਰ ਸ਼ਾਸਿਤ ਪ੍ਰਦੇਸ਼ ਅਨੁਸਾਰ ਸਕਿੱਲ ਡਿਵੈਲਪਮੈਂਟ',
  'Skills, Mentors & Training' => 'ਹੁਨਰ, ਮੈਂਟਰ ਅਤੇ ਸਿਖਲਾਈ',
  'See which skills we offer training in right now (online or offline in Delhi-NCR) and which skills we are looking for mentors in. Learners can choose up to 5 skills.' => 'ਵੇਖੋ ਕਿ ਅਸੀਂ ਇਸ ਵੇਲੇ ਕਿਹੜੇ ਹੁਨਰਾਂ ਵਿੱਚ ਸਿਖਲਾਈ ਦਿੰਦੇ ਹਾਂ (ਔਨਲਾਈਨ ਜਾਂ ਦਿੱਲੀ-NCR ਵਿੱਚ ਔਫਲਾਈਨ) ਅਤੇ ਕਿਹੜੇ ਹੁਨਰਾਂ ਲਈ ਅਸੀਂ ਮੈਂਟਰ ਲੱਭ ਰਹੇ ਹਾਂ। ਸਿੱਖਣ ਵਾਲੇ ਵੱਧ ਤੋਂ ਵੱਧ 5 ਹੁਨਰ ਚੁਣ ਸਕਦੇ ਹਨ।',
  'Apply to Learn – ₹155' => 'ਸਿੱਖਣ ਲਈ ਅਰਜ਼ੀ ਦਿਓ – ₹155',
