  'Get matched with a mentor' => 'ਮੈਂਟਰ ਨਾਲ ਮੇਲ ਕਰਵਾਓ',
  'Once selected, we send a request to the best-matching mentor.' => 'ਚੋਣ ਹੋਣ \'ਤੇ, ਅਸੀਂ ਸਭ ਤੋਂ ਢੁਕਵੇਂ ਮੈਂਟਰ ਨੂੰ ਬੇਨਤੀ ਭੇਜਦੇ ਹਾਂ।',
  'Online or offline' => 'ਔਨਲਾਈਨ ਜਾਂ ਔਫਲਾਈਨ',
  'If a mentor is not available, you can choose from the list of online and offline mentors yourself.' => 'ਜੇ ਮੈਂਟਰ ਉਪਲਬਧ ਨਹੀਂ ਹੈ, ਤਾਂ ਤੁਸੀਂ ਔਨਲਾਈਨ ਅਤੇ ਔਫਲਾਈਨ ਮੈਂਟਰਾਂ ਦੀ ਸੂਚੀ ਵਿੱਚੋਂ ਖੁਦ ਚੁਣ ਸਕਦੇ ਹੋ।',
  'Skills We Teach & Mentors We Are Looking For' => 'ਹੁਨਰ ਜੋ ਅਸੀਂ ਸਿਖਾਉਂਦੇ ਹਾਂ ਅਤੇ ਮੈਂਟਰ ਜਿਨ੍ਹਾਂ ਦੀ ਸਾਨੂੰ ਲੋੜ ਹੈ',
