  'Training Available' => 'ਸਿਖਲਾਈ ਉਪਲਬਧ',
  'Offline Delhi-NCR' => 'ਔਫਲਾਈਨ ਦਿੱਲੀ-NCR',
  'Our mentor team is forming – be one of the first mentors!' => 'ਸਾਡੀ ਮੈਂਟਰ ਟੀਮ ਬਣ ਰਹੀ ਹੈ – ਪਹਿਲੇ ਮੈਂਟਰਾਂ ਵਿੱਚੋਂ ਇੱਕ ਬਣੋ!',
  'Apply to learn' => 'ਸਿੱਖਣ ਲਈ ਅਰਜ਼ੀ ਦਿਓ',
  'Mentors Wanted For' => 'ਇਨ੍ਹਾਂ ਲਈ ਮੈਂਟਰ ਚਾਹੀਦੇ ਹਨ',
