  'Become a mentor' => 'ਮੈਂਟਰ ਬਣੋ',
  'See all skills' => 'ਸਾਰੇ ਹੁਨਰ ਵੇਖੋ',
  'Find Doctors & Hospital Staff' => 'ਡਾਕਟਰ ਅਤੇ ਹਸਪਤਾਲ ਸਟਾਫ਼ ਲੱਭੋ',
  'Keywords from your requirement are matched with candidates’ briefs and resumes. The pass lasts 15 days – name, mobile, email and resume.' => 'ਤੁਹਾਡੀ ਲੋੜ ਦੇ ਕੀਵਰਡ ਉਮੀਦਵਾਰਾਂ ਦੇ ਸੰਖੇਪ ਵੇਰਵਿਆਂ ਅਤੇ ਰਿਜ਼ਿਊਮਾਂ ਨਾਲ ਮਿਲਾਏ ਜਾਂਦੇ ਹਨ। ਪਾਸ 15 ਦਿਨ ਚੱਲਦਾ ਹੈ – ਨਾਮ, ਮੋਬਾਈਲ, ਈਮੇਲ ਅਤੇ ਰਿਜ਼ਿਊਮ।',
  'Talent Search – Hire Part-time People' => 'ਟੈਲੇਂਟ ਸਰਚ – ਪਾਰਟ-ਟਾਈਮ ਲੋਕ ਰੱਖੋ',
  'Exhibition staff, promoters, models, bouncers, drivers and 30,000+ roles – with resume keywords, city, hours and daily pay.' => 'ਪ੍ਰਦਰਸ਼ਨੀ ਸਟਾਫ਼, ਪ੍ਰਮੋਟਰ, ਮਾਡਲ, ਬਾਊਂਸਰ, ਡਰਾਈਵਰ ਅਤੇ 30,000+ ਭੂਮਿਕਾਵਾਂ – ਰਿਜ਼ਿਊਮ ਕੀਵਰਡ, ਸ਼ਹਿਰ, ਘੰਟਿਆਂ ਅਤੇ ਰੋਜ਼ਾਨਾ ਮਿਹਨਤਾਨੇ ਨਾਲ।',
  'Your pass is active till ' => 'ਤੁਹਾਡਾ ਪਾਸ ਇਸ ਤਾਰੀਖ ਤੱਕ ਸਰਗਰਮ ਹੈ: ',
  'Role: ' => 'ਭੂਮਿਕਾ: ',
  'Total ' => 'ਕੁੱਲ ',
  'Register to see names, numbers, emails and resumes' => 'ਨਾਮ, ਨੰਬਰ, ਈਮੇਲਾਂ ਅਤੇ ਰਿਜ਼ਿਊਮ ਵੇਖਣ ਲਈ ਰਜਿਸਟਰ ਕਰੋ',
  'Get the Talent Pass to see names, numbers and resumes' => 'ਨਾਮ, ਨੰਬਰ ਅਤੇ ਰਿਜ਼ਿਊਮ ਵੇਖਣ ਲਈ ਟੈਲੇਂਟ ਪਾਸ ਲਓ',
  'One-time fee by role, valid 15 days' => 'ਭੂਮਿਕਾ ਅਨੁਸਾਰ ਇੱਕ ਵਾਰ ਦੀ ਫੀਸ, 15 ਦਿਨਾਂ ਲਈ ਵੈਧ',
  'Register now' => 'ਹੁਣੇ ਰਜਿਸਟਰ ਕਰੋ',
  'Keywords (skill, post, department)' => 'ਕੀਵਰਡ (ਹੁਨਰ, ਅਹੁਦਾ, ਵਿਭਾਗ)',
  'City / State' => 'ਸ਼ਹਿਰ / ਰਾਜ',
  'Candidates matching your requirement: ' => 'ਤੁਹਾਡੀ ਲੋੜ ਨਾਲ ਮੇਲ ਖਾਂਦੇ ਉਮੀਦਵਾਰ: ',
  'No matching candidate yet. Try other keywords or a city.' => 'ਅਜੇ ਕੋਈ ਮੇਲ ਖਾਂਦਾ ਉਮੀਦਵਾਰ ਨਹੀਂ। ਹੋਰ ਕੀਵਰਡ ਜਾਂ ਕੋਈ ਸ਼ਹਿਰ ਅਜ਼ਮਾਓ।',
