  'First become skilled – online video classes (Pan-India) or offline (Delhi-NCR).' => 'ਪਹਿਲਾਂ ਹੁਨਰਮੰਦ ਬਣੋ – ਔਨਲਾਈਨ ਵੀਡੀਓ ਕਲਾਸਾਂ (ਪੂਰੇ ਭਾਰਤ ਵਿੱਚ) ਜਾਂ ਔਫਲਾਈਨ (ਦਿੱਲੀ-NCR)।',
  'Your skill choices – up to 5, in order of preference (search 3000+ list)' => 'ਤੁਹਾਡੀਆਂ ਹੁਨਰ ਚੋਣਾਂ – ਵੱਧ ਤੋਂ ਵੱਧ 5, ਪਸੰਦ ਦੇ ਕ੍ਰਮ ਵਿੱਚ (3000+ ਦੀ ਸੂਚੀ ਵਿੱਚ ਖੋਜੋ)',
