  'Online / Video classes (Pan-India)' => 'ਔਨਲਾਈਨ / ਵੀਡੀਓ ਕਲਾਸਾਂ (ਪੂਰੇ ਭਾਰਤ ਵਿੱਚ)',
  'Offline classes – Delhi-NCR only' => 'ਔਫਲਾਈਨ ਕਲਾਸਾਂ – ਸਿਰਫ਼ ਦਿੱਲੀ-NCR',
