  'Preferred city / location (for offline)' => 'ਪਸੰਦੀਦਾ ਸ਼ਹਿਰ / ਸਥਾਨ (ਔਫਲਾਈਨ ਲਈ)',
  'Any other skill you want to learn' => 'ਕੋਈ ਹੋਰ ਹੁਨਰ ਜੋ ਤੁਸੀਂ ਸਿੱਖਣਾ ਚਾਹੁੰਦੇ ਹੋ',
  'Brief description about yourself (education, work, goals)' => 'ਆਪਣੇ ਬਾਰੇ ਸੰਖੇਪ ਜਾਣਕਾਰੀ (ਪੜ੍ਹਾਈ, ਕੰਮ, ਟੀਚੇ)',
  'Upload resume if any (PDF/DOC, max 5MB)' => 'ਰਿਜ਼ਿਊਮ ਅੱਪਲੋਡ ਕਰੋ, ਜੇ ਹੋਵੇ (PDF/DOC, ਵੱਧ ਤੋਂ ਵੱਧ 5MB)',
  'The information provided by me is true and correct.' => 'ਮੇਰੇ ਵੱਲੋਂ ਦਿੱਤੀ ਗਈ ਜਾਣਕਾਰੀ ਸੱਚੀ ਅਤੇ ਸਹੀ ਹੈ।',
  'The one-time processing fee of ₹155 (including GST) is non-refundable.' => '₹155 (GST ਸਮੇਤ) ਦੀ ਇੱਕ ਵਾਰ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਫੀਸ ਨਾ-ਵਾਪਸੀਯੋਗ ਹੈ।',
  'I will be trained only in the skills I chose (up to 5).' => 'ਮੈਨੂੰ ਸਿਰਫ਼ ਮੇਰੇ ਵੱਲੋਂ ਚੁਣੇ ਗਏ ਹੁਨਰਾਂ (ਵੱਧ ਤੋਂ ਵੱਧ 5) ਵਿੱਚ ਹੀ ਸਿਖਲਾਈ ਦਿੱਤੀ ਜਾਵੇਗੀ।',
  'After selection, the total course fee of ₹12,000 + 18% GST is also non-refundable.' => 'ਚੋਣ ਤੋਂ ਬਾਅਦ, ₹12,000 + 18% GST ਦੀ ਕੁੱਲ ਕੋਰਸ ਫੀਸ ਵੀ ਨਾ-ਵਾਪਸੀਯੋਗ ਹੈ।',
  'Classes will be 2 hours per day, 3 days a week, including practical training.' => 'ਕਲਾਸਾਂ ਰੋਜ਼ਾਨਾ 2 ਘੰਟੇ, ਹਫ਼ਤੇ ਵਿੱਚ 3 ਦਿਨ, ਪ੍ਰੈਕਟੀਕਲ ਸਿਖਲਾਈ ਸਮੇਤ ਹੋਣਗੀਆਂ।',
  'Minimum 3 to 6 months is required for scrutiny of forms and resumes.' => 'ਫਾਰਮਾਂ ਅਤੇ ਰਿਜ਼ਿਊਮਾਂ ਦੀ ਜਾਂਚ ਲਈ ਘੱਟੋ-ਘੱਟ 3 ਤੋਂ 6 ਮਹੀਨੇ ਲੋੜੀਂਦੇ ਹਨ।',
  'Jobsence will try to push my resume to interested companies, make me job-ready, or guide me towards self-employment.' => 'Jobsence ਮੇਰਾ ਰਿਜ਼ਿਊਮ ਦਿਲਚਸਪੀ ਰੱਖਣ ਵਾਲੀਆਂ ਕੰਪਨੀਆਂ ਤੱਕ ਪਹੁੰਚਾਉਣ, ਮੈਨੂੰ ਨੌਕਰੀ ਲਈ ਤਿਆਰ ਕਰਨ, ਜਾਂ ਸਵੈ-ਰੁਜ਼ਗਾਰ ਵੱਲ ਮਾਰਗਦਰਸ਼ਨ ਕਰਨ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰੇਗਾ।',
  'Jobsence does not take any responsibility or guarantee of job / placement.' => 'Jobsence ਨੌਕਰੀ / ਪਲੇਸਮੈਂਟ ਦੀ ਕੋਈ ਜ਼ਿੰਮੇਵਾਰੀ ਜਾਂ ਗਾਰੰਟੀ ਨਹੀਂ ਲੈਂਦਾ।',
  'Training will be conducted through third-party skill development partners, in local language / Hindi / English depending on mentor availability.' => 'ਸਿਖਲਾਈ ਥਰਡ-ਪਾਰਟੀ ਸਕਿੱਲ ਡਿਵੈਲਪਮੈਂਟ ਭਾਈਵਾਲਾਂ ਰਾਹੀਂ, ਮੈਂਟਰ ਦੀ ਉਪਲਬਧਤਾ ਅਨੁਸਾਰ ਸਥਾਨਕ ਭਾਸ਼ਾ / ਹਿੰਦੀ / ਅੰਗਰੇਜ਼ੀ ਵਿੱਚ ਕਰਵਾਈ ਜਾਵੇਗੀ।',
  'Scrutiny of forms takes minimum 3 to 6 months.' => 'ਫਾਰਮਾਂ ਦੀ ਜਾਂਚ ਵਿੱਚ ਘੱਟੋ-ਘੱਟ 3 ਤੋਂ 6 ਮਹੀਨੇ ਲੱਗਦੇ ਹਨ।',
  'After selection, you will be informed about the course fee of ₹12,000 + 18% GST (non-refundable).' => 'ਚੋਣ ਤੋਂ ਬਾਅਦ, ਤੁਹਾਨੂੰ ₹12,000 + 18% GST ਦੀ ਕੋਰਸ ਫੀਸ (ਨਾ-ਵਾਪਸੀਯੋਗ) ਬਾਰੇ ਸੂਚਿਤ ਕੀਤਾ ਜਾਵੇਗਾ।',
  'Classes will be 2 hours per day, 3 days a week, with practical training.' => 'ਕਲਾਸਾਂ ਰੋਜ਼ਾਨਾ 2 ਘੰਟੇ, ਹਫ਼ਤੇ ਵਿੱਚ 3 ਦਿਨ, ਪ੍ਰੈਕਟੀਕਲ ਸਿਖਲਾਈ ਦੇ ਨਾਲ ਹੋਣਗੀਆਂ।',
  'Internship Registration' => 'ਇੰਟਰਨਸ਼ਿਪ ਰਜਿਸਟ੍ਰੇਸ਼ਨ',
