  'Part-time work you want – minimum 2, maximum 5 options (search 30,000+ list)' => 'ਤੁਸੀਂ ਕਿਹੜਾ ਪਾਰਟ-ਟਾਈਮ ਕੰਮ ਚਾਹੁੰਦੇ ਹੋ – ਘੱਟੋ-ਘੱਟ 2, ਵੱਧ ਤੋਂ ਵੱਧ 5 ਵਿਕਲਪ (30,000+ ਦੀ ਸੂਚੀ ਵਿੱਚ ਖੋਜੋ)',
  'Preferred job category (search 30,000+ categories)' => 'ਪਸੰਦੀਦਾ ਨੌਕਰੀ ਸ਼੍ਰੇਣੀ (30,000+ ਸ਼੍ਰੇਣੀਆਂ ਵਿੱਚ ਖੋਜੋ)',
