  'Choose 2 to 5 kinds of work, with your minimum expected pay per day, hours, dates and timings.' => '2 ਤੋਂ 5 ਕਿਸਮਾਂ ਦਾ ਕੰਮ ਚੁਣੋ, ਨਾਲ ਹੀ ਪ੍ਰਤੀ ਦਿਨ ਆਪਣਾ ਘੱਟੋ-ਘੱਟ ਅਨੁਮਾਨਿਤ ਭੁਗਤਾਨ, ਘੰਟੇ, ਤਰੀਕਾਂ ਅਤੇ ਸਮਾਂ ਦੱਸੋ।',
