  'My registration is valid for 3 months from the date of payment.' => 'ਮੇਰੀ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਭੁਗਤਾਨ ਦੀ ਮਿਤੀ ਤੋਂ 3 ਮਹੀਨਿਆਂ ਲਈ ਵੈਧ ਹੈ।',
  'Jobs in India Pass (1 month)' => 'Jobs in India ਪਾਸ (1 ਮਹੀਨਾ)',
  'See all Govt, PSU & top company jobs' => 'ਸਾਰੀਆਂ ਸਰਕਾਰੀ, PSU ਅਤੇ ਵੱਡੀਆਂ ਕੰਪਨੀਆਂ ਦੀਆਂ ਨੌਕਰੀਆਂ ਦੇਖੋ',
  'Railways, Army, Police, State Govts, PSUs (GAIL, BHEL…) and top company jobs in one place. ₹150 + GST (₹177) unlocks full details and official apply links for 1 month.' => 'ਰੇਲਵੇ, ਫੌਜ, ਪੁਲਿਸ, ਰਾਜ ਸਰਕਾਰਾਂ, PSU (GAIL, BHEL…) ਅਤੇ ਵੱਡੀਆਂ ਕੰਪਨੀਆਂ ਦੀਆਂ ਨੌਕਰੀਆਂ ਇੱਕੋ ਥਾਂ। ₹150 + GST (₹177) ਨਾਲ 1 ਮਹੀਨੇ ਲਈ ਪੂਰੇ ਵੇਰਵੇ ਅਤੇ ਅਧਿਕਾਰਤ ਅਪਲਾਈ ਲਿੰਕ ਖੁੱਲ੍ਹ ਜਾਂਦੇ ਹਨ।',
  'One pass = one email + one mobile number, for 1 month. Email OTP verification is required.' => 'ਇੱਕ ਪਾਸ = ਇੱਕ ਈਮੇਲ + ਇੱਕ ਮੋਬਾਈਲ ਨੰਬਰ, 1 ਮਹੀਨੇ ਲਈ। ਈਮੇਲ OTP ਰਾਹੀਂ ਤਸਦੀਕ ਲਾਜ਼ਮੀ ਹੈ।',
  'This fee is for Jobsence’s job-listing service – it is NOT a government fee. Always apply for government jobs on the official website only.' => 'ਇਹ ਫੀਸ Jobsence ਦੀ ਨੌਕਰੀ-ਸੂਚੀ ਸੇਵਾ ਲਈ ਹੈ – ਇਹ ਕੋਈ ਸਰਕਾਰੀ ਫੀਸ ਨਹੀਂ ਹੈ। ਸਰਕਾਰੀ ਨੌਕਰੀਆਂ ਲਈ ਹਮੇਸ਼ਾ ਸਿਰਫ਼ ਅਧਿਕਾਰਤ ਵੈੱਬਸਾਈਟ \'ਤੇ ਹੀ ਅਪਲਾਈ ਕਰੋ।',
  'Jobsence is not affiliated with these departments / companies; every job links to its official source.' => 'Jobsence ਇਨ੍ਹਾਂ ਵਿਭਾਗਾਂ / ਕੰਪਨੀਆਂ ਨਾਲ ਸੰਬੰਧਿਤ ਨਹੀਂ ਹੈ; ਹਰ ਨੌਕਰੀ ਆਪਣੇ ਅਧਿਕਾਰਤ ਸਰੋਤ ਨਾਲ ਲਿੰਕ ਕੀਤੀ ਗਈ ਹੈ।',
