  'The fee of ₹177 (₹150 + GST) is non-refundable and the pass is valid for 1 month from payment.' => '₹177 (₹150 + GST) ਦੀ ਫੀਸ ਨਾ-ਵਾਪਸੀਯੋਗ ਹੈ ਅਤੇ ਪਾਸ ਭੁਗਤਾਨ ਤੋਂ 1 ਮਹੀਨੇ ਲਈ ਵੈਧ ਹੈ।',
  'The pass is only for my email and mobile; I will not share it with anyone.' => 'ਪਾਸ ਸਿਰਫ਼ ਮੇਰੀ ਈਮੇਲ ਅਤੇ ਮੋਬਾਈਲ ਲਈ ਹੈ; ਮੈਂ ਇਸਨੂੰ ਕਿਸੇ ਨਾਲ ਸਾਂਝਾ ਨਹੀਂ ਕਰਾਂਗਾ/ਕਰਾਂਗੀ।',
  'This is not a government fee. Jobsence does not guarantee any job and is not affiliated with the hiring departments / companies.' => 'ਇਹ ਕੋਈ ਸਰਕਾਰੀ ਫੀਸ ਨਹੀਂ ਹੈ। Jobsence ਕਿਸੇ ਵੀ ਨੌਕਰੀ ਦੀ ਗਾਰੰਟੀ ਨਹੀਂ ਦਿੰਦਾ ਅਤੇ ਭਰਤੀ ਕਰਨ ਵਾਲੇ ਵਿਭਾਗਾਂ / ਕੰਪਨੀਆਂ ਨਾਲ ਸੰਬੰਧਿਤ ਨਹੀਂ ਹੈ।',
  'Now open the “See Jobs in India” page to see full details and official apply links of all jobs.' => 'ਹੁਣ ਸਾਰੀਆਂ ਨੌਕਰੀਆਂ ਦੇ ਪੂਰੇ ਵੇਰਵੇ ਅਤੇ ਅਧਿਕਾਰਤ ਅਪਲਾਈ ਲਿੰਕ ਦੇਖਣ ਲਈ “See Jobs in India” ਪੰਨਾ ਖੋਲ੍ਹੋ।',
  'Always apply on the official website. Beware of anyone asking for money in exchange for a job.' => 'ਹਮੇਸ਼ਾ ਅਧਿਕਾਰਤ ਵੈੱਬਸਾਈਟ \'ਤੇ ਹੀ ਅਪਲਾਈ ਕਰੋ। ਨੌਕਰੀ ਦੇ ਬਦਲੇ ਪੈਸੇ ਮੰਗਣ ਵਾਲੇ ਕਿਸੇ ਵੀ ਵਿਅਕਤੀ ਤੋਂ ਸਾਵਧਾਨ ਰਹੋ।',
