  'Reach customers near you. ₹150 + GST (₹177) for 3 months. Photo and a live selfie are mandatory for identity verification.' => 'ਆਪਣੇ ਨੇੜੇ ਦੇ ਗਾਹਕਾਂ ਤੱਕ ਪਹੁੰਚੋ। 3 ਮਹੀਨਿਆਂ ਲਈ ₹150 + GST (₹177)। ਪਛਾਣ ਦੀ ਤਸਦੀਕ ਲਈ ਫੋਟੋ ਅਤੇ ਲਾਈਵ ਸੈਲਫੀ ਲਾਜ਼ਮੀ ਹਨ।',
  'Other services (optional) – up to 5, from a 47,000+ list' => 'ਹੋਰ ਸੇਵਾਵਾਂ (ਵਿਕਲਪਿਕ) – ਵੱਧ ਤੋਂ ਵੱਧ 5, 47,000+ ਦੀ ਸੂਚੀ ਵਿੱਚੋਂ',
  'Fee ₹150 + 18% GST = ₹177, valid for 3 months from payment.' => 'ਫੀਸ ₹150 + 18% GST = ₹177, ਭੁਗਤਾਨ ਤੋਂ 3 ਮਹੀਨਿਆਂ ਲਈ ਵੈਧ।',
  'Your name / shop name, mobile number and address will be shown to paying customers.' => 'ਤੁਹਾਡਾ ਨਾਮ / ਦੁਕਾਨ ਦਾ ਨਾਮ, ਮੋਬਾਈਲ ਨੰਬਰ ਅਤੇ ਪਤਾ ਭੁਗਤਾਨ ਕਰਨ ਵਾਲੇ ਗਾਹਕਾਂ ਨੂੰ ਦਿਖਾਇਆ ਜਾਵੇਗਾ।',
  'A clear photo and a live selfie are mandatory – the Jobsence team verifies your identity.' => 'ਸਾਫ਼ ਫੋਟੋ ਅਤੇ ਲਾਈਵ ਸੈਲਫੀ ਲਾਜ਼ਮੀ ਹਨ – Jobsence ਟੀਮ ਤੁਹਾਡੀ ਪਛਾਣ ਦੀ ਤਸਦੀਕ ਕਰਦੀ ਹੈ।',
