  'If other, write your profession' => 'ਜੇ ਹੋਰ ਹੈ, ਤਾਂ ਆਪਣਾ ਕਿੱਤਾ ਲਿਖੋ',
  'You are' => 'ਤੁਸੀਂ ਹੋ',
