  'Shop / Salon / Organisation Name (if any)' => 'ਦੁਕਾਨ / ਸੈਲੂਨ / ਸੰਸਥਾ ਦਾ ਨਾਮ (ਜੇ ਕੋਈ ਹੋਵੇ)',
  'Mobile Number (shown to customers)' => 'ਮੋਬਾਈਲ ਨੰਬਰ (ਗਾਹਕਾਂ ਨੂੰ ਦਿਖਾਇਆ ਜਾਵੇਗਾ)',
