  'For your safety we store only the last 4 digits.' => 'ਤੁਹਾਡੀ ਸੁਰੱਖਿਆ ਲਈ ਅਸੀਂ ਸਿਰਫ਼ ਆਖਰੀ 4 ਅੰਕ ਹੀ ਸੰਭਾਲਦੇ ਹਾਂ।',
