  'Your clear photo / shop photo (JPG/PNG, max 5MB)' => 'ਤੁਹਾਡੀ ਸਾਫ਼ ਫੋਟੋ / ਦੁਕਾਨ ਦੀ ਫੋਟੋ (JPG/PNG, ਵੱਧ ਤੋਂ ਵੱਧ 5MB)',
  'This photo is shown to customers.' => 'ਇਹ ਫੋਟੋ ਗਾਹਕਾਂ ਨੂੰ ਦਿਖਾਈ ਜਾਂਦੀ ਹੈ।',
  'Take a live selfie' => 'ਲਾਈਵ ਸੈਲਫੀ ਲਓ',
  'The selfie is seen only by the Jobsence team for verification – never shown to customers.' => 'ਸੈਲਫੀ ਸਿਰਫ਼ Jobsence ਟੀਮ ਵੱਲੋਂ ਤਸਦੀਕ ਲਈ ਦੇਖੀ ਜਾਂਦੀ ਹੈ – ਗਾਹਕਾਂ ਨੂੰ ਕਦੇ ਨਹੀਂ ਦਿਖਾਈ ਜਾਂਦੀ।',
  'Service Details' => 'ਸੇਵਾ ਦੇ ਵੇਰਵੇ',
  'Minimum visit / service charge (₹)' => 'ਘੱਟੋ-ਘੱਟ ਵਿਜ਼ਿਟ / ਸਰਵਿਸ ਚਾਰਜ (₹)',
  'How far do you travel for work' => 'ਤੁਸੀਂ ਕੰਮ ਲਈ ਕਿੰਨੀ ਦੂਰ ਤੱਕ ਜਾਂਦੇ ਹੋ',
