  'Working hours (e.g. 9am – 7pm)' => 'ਕੰਮ ਦੇ ਘੰਟੇ (ਜਿਵੇਂ ਸਵੇਰੇ 9 ਵਜੇ – ਸ਼ਾਮ 7 ਵਜੇ)',
  'About your service (optional)' => 'ਤੁਹਾਡੀ ਸੇਵਾ ਬਾਰੇ (ਵਿਕਲਪਿਕ)',
  'Your Address & PIN Code' => 'ਤੁਹਾਡਾ ਪਤਾ ਅਤੇ PIN ਕੋਡ',
  'The information, photo and selfie provided are true and my own.' => 'ਦਿੱਤੀ ਗਈ ਜਾਣਕਾਰੀ, ਫੋਟੋ ਅਤੇ ਸੈਲਫੀ ਸੱਚੀ ਹੈ ਅਤੇ ਮੇਰੀ ਆਪਣੀ ਹੈ।',
  'The fee of ₹177 (₹150 + GST) is non-refundable; registration is valid for 3 months from payment.' => '₹177 (₹150 + GST) ਦੀ ਫੀਸ ਨਾ-ਵਾਪਸੀਯੋਗ ਹੈ; ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਭੁਗਤਾਨ ਤੋਂ 3 ਮਹੀਨਿਆਂ ਲਈ ਵੈਧ ਹੈ।',
  'I agree that my name, mobile number and address are shown to paying customers.' => 'ਮੈਂ ਸਹਿਮਤ ਹਾਂ ਕਿ ਮੇਰਾ ਨਾਮ, ਮੋਬਾਈਲ ਨੰਬਰ ਅਤੇ ਪਤਾ ਭੁਗਤਾਨ ਕਰਨ ਵਾਲੇ ਗਾਹਕਾਂ ਨੂੰ ਦਿਖਾਇਆ ਜਾਵੇ।',
  'I will charge customers fairly and behave properly.' => 'ਮੈਂ ਗਾਹਕਾਂ ਤੋਂ ਵਾਜਬ ਪੈਸੇ ਲਵਾਂਗਾ/ਲਵਾਂਗੀ ਅਤੇ ਚੰਗਾ ਵਿਹਾਰ ਕਰਾਂਗਾ/ਕਰਾਂਗੀ।',
  'The Jobsence team will verify your identity from your photo and selfie; after verification your profile shows “Verified”.' => 'Jobsence ਟੀਮ ਤੁਹਾਡੀ ਫੋਟੋ ਅਤੇ ਸੈਲਫੀ ਤੋਂ ਤੁਹਾਡੀ ਪਛਾਣ ਦੀ ਤਸਦੀਕ ਕਰੇਗੀ; ਤਸਦੀਕ ਤੋਂ ਬਾਅਦ ਤੁਹਾਡੀ ਪ੍ਰੋਫਾਈਲ \'ਤੇ “Verified” ਦਿਖਾਈ ਦੇਵੇਗਾ।',
  'Customers looking for your service in your PIN code area will call / WhatsApp you directly.' => 'ਤੁਹਾਡੇ PIN ਕੋਡ ਖੇਤਰ ਵਿੱਚ ਤੁਹਾਡੀ ਸੇਵਾ ਲੱਭ ਰਹੇ ਗਾਹਕ ਤੁਹਾਨੂੰ ਸਿੱਧਾ ਕਾਲ / WhatsApp ਕਰਨਗੇ।',
  'Near Me – Find a Service Provider' => 'Near Me – ਸੇਵਾ ਪ੍ਰਦਾਤਾ ਲੱਭੋ',
  'Find a plumber, electrician, carpenter or salon near you' => 'ਆਪਣੇ ਨੇੜੇ ਪਲੰਬਰ, ਇਲੈਕਟ੍ਰੀਸ਼ੀਅਨ, ਤਰਖਾਣ ਜਾਂ ਸੈਲੂਨ ਲੱਭੋ',
  'Pay a platform fee of ₹150 + GST (₹177) and choose verified service providers near your PIN code for 3 months; their mobile number and address appear once both of you sign the agreement.' => '₹150 + GST (₹177) ਦੀ ਪਲੇਟਫਾਰਮ ਫੀਸ ਦਿਓ ਅਤੇ 3 ਮਹੀਨਿਆਂ ਲਈ ਆਪਣੇ PIN ਕੋਡ ਦੇ ਨੇੜੇ ਤਸਦੀਕਸ਼ੁਦਾ ਸੇਵਾ ਪ੍ਰਦਾਤਾ ਚੁਣੋ; ਤੁਹਾਡੇ ਦੋਵਾਂ ਵੱਲੋਂ ਸਮਝੌਤੇ \'ਤੇ ਦਸਤਖਤ ਕਰਨ ਤੋਂ ਬਾਅਦ ਉਨ੍ਹਾਂ ਦਾ ਮੋਬਾਈਲ ਨੰਬਰ ਅਤੇ ਪਤਾ ਦਿਖਾਈ ਦਿੰਦਾ ਹੈ।',
  'Services you need – up to 5' => 'ਤੁਹਾਨੂੰ ਲੋੜੀਂਦੀਆਂ ਸੇਵਾਵਾਂ – ਵੱਧ ਤੋਂ ਵੱਧ 5',
  'Platform fee ₹150 + 18% GST = ₹177, valid for 3 months from payment.' => 'ਪਲੇਟਫਾਰਮ ਫੀਸ ₹150 + 18% GST = ₹177, ਭੁਗਤਾਨ ਤੋਂ 3 ਮਹੀਨਿਆਂ ਲਈ ਵੈਧ।',
  'You pay the service provider directly for the work – Jobsence only connects you.' => 'ਕੰਮ ਦਾ ਭੁਗਤਾਨ ਤੁਸੀਂ ਸਿੱਧਾ ਸੇਵਾ ਪ੍ਰਦਾਤਾ ਨੂੰ ਕਰਦੇ ਹੋ – Jobsence ਸਿਰਫ਼ ਤੁਹਾਨੂੰ ਜੋੜਦਾ ਹੈ।',
  'Your OTP and access link will be sent here.' => 'ਤੁਹਾਡਾ OTP ਅਤੇ ਐਕਸੈਸ ਲਿੰਕ ਇੱਥੇ ਭੇਜਿਆ ਜਾਵੇਗਾ।',
  'What You Need' => 'ਤੁਹਾਨੂੰ ਕੀ ਚਾਹੀਦਾ ਹੈ',
  'When do you need it' => 'ਤੁਹਾਨੂੰ ਇਹ ਕਦੋਂ ਚਾਹੀਦਾ ਹੈ',
  'Today / urgent' => 'ਅੱਜ / ਜ਼ਰੂਰੀ',
  'This week' => 'ਇਸ ਹਫ਼ਤੇ',
  'Flexible' => 'ਕਦੇ ਵੀ (ਲਚਕਦਾਰ)',
  'Briefly describe the work (optional)' => 'ਕੰਮ ਬਾਰੇ ਸੰਖੇਪ ਵਿੱਚ ਦੱਸੋ (ਵਿਕਲਪਿਕ)',
  'The platform fee of ₹177 (₹150 + GST) is non-refundable; access is valid for 3 months from payment.' => '₹177 (₹150 + GST) ਦੀ ਪਲੇਟਫਾਰਮ ਫੀਸ ਨਾ-ਵਾਪਸੀਯੋਗ ਹੈ; ਐਕਸੈਸ ਭੁਗਤਾਨ ਤੋਂ 3 ਮਹੀਨਿਆਂ ਲਈ ਵੈਧ ਹੈ।',
  'I will use service providers’ details only for my own work and will not share or sell them.' => 'ਮੈਂ ਸੇਵਾ ਪ੍ਰਦਾਤਾਵਾਂ ਦੇ ਵੇਰਵੇ ਸਿਰਫ਼ ਆਪਣੇ ਕੰਮ ਲਈ ਵਰਤਾਂਗਾ/ਵਰਤਾਂਗੀ ਅਤੇ ਉਨ੍ਹਾਂ ਨੂੰ ਸਾਂਝਾ ਜਾਂ ਵੇਚਾਂਗਾ/ਵੇਚਾਂਗੀ ਨਹੀਂ।',
  'Enter your PIN code on the “Near Me” page, choose a provider and sign the agreement with an email OTP – the number appears as soon as the provider signs.' => '“Near Me” ਪੰਨੇ \'ਤੇ ਆਪਣਾ PIN ਕੋਡ ਦਰਜ ਕਰੋ, ਪ੍ਰਦਾਤਾ ਚੁਣੋ ਅਤੇ ਈਮੇਲ OTP ਨਾਲ ਸਮਝੌਤੇ \'ਤੇ ਦਸਤਖਤ ਕਰੋ – ਪ੍ਰਦਾਤਾ ਦੇ ਦਸਤਖਤ ਕਰਦੇ ਹੀ ਨੰਬਰ ਦਿਖਾਈ ਦਿੰਦਾ ਹੈ।',
  'Agree on the price and check identity before work starts.' => 'ਕੰਮ ਸ਼ੁਰੂ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਕੀਮਤ ਤੈਅ ਕਰੋ ਅਤੇ ਪਛਾਣ ਦੀ ਜਾਂਚ ਕਰੋ।',
  'Restaurant & Chef Jobs Registration' => 'ਰੈਸਟੋਰੈਂਟ ਅਤੇ ਸ਼ੈੱਫ ਨੌਕਰੀਆਂ ਦੀ ਰਜਿਸਟ੍ਰੇਸ਼ਨ',
  'Restaurant, hotel & chef jobs – near you, in another city or abroad' => 'ਰੈਸਟੋਰੈਂਟ, ਹੋਟਲ ਅਤੇ ਸ਼ੈੱਫ ਦੀਆਂ ਨੌਕਰੀਆਂ – ਤੁਹਾਡੇ ਨੇੜੇ, ਕਿਸੇ ਹੋਰ ਸ਼ਹਿਰ ਵਿੱਚ ਜਾਂ ਵਿਦੇਸ਼ ਵਿੱਚ',
  'Chef, cook, tandoor, waiter, captain, bartender, steward – enrol first for jobs near you, in another city or abroad. ₹250 + 18% GST (₹295) for 3 months.' => 'ਸ਼ੈੱਫ, ਕੁੱਕ, ਤੰਦੂਰ, ਵੇਟਰ, ਕੈਪਟਨ, ਬਾਰਟੈਂਡਰ, ਸਟੂਅਰਡ – ਆਪਣੇ ਨੇੜੇ, ਕਿਸੇ ਹੋਰ ਸ਼ਹਿਰ ਵਿੱਚ ਜਾਂ ਵਿਦੇਸ਼ ਵਿੱਚ ਨੌਕਰੀ ਲਈ ਪਹਿਲਾਂ ਰਜਿਸਟਰ ਕਰੋ। ₹250 + 18% GST (₹295), 3 ਮਹੀਨਿਆਂ ਲਈ।',
  'Roles you want – up to 5 (e.g. Tandoor Chef, Commis Chef, Waiter)' => 'ਤੁਸੀਂ ਕਿਹੜਾ ਕੰਮ ਚਾਹੁੰਦੇ ਹੋ – ਵੱਧ ਤੋਂ ਵੱਧ 5 (ਜਿਵੇਂ Tandoor Chef, Commis Chef, Waiter)',
  'One-time fee ₹250 + 18% GST = ₹295 – valid for 3 months from payment.' => 'ਇੱਕ ਵਾਰ ਦੀ ਫ਼ੀਸ ₹250 + 18% GST = ₹295 – ਭੁਗਤਾਨ ਤੋਂ 3 ਮਹੀਨਿਆਂ ਤੱਕ ਵੈਧ।',
  'For jobs abroad, go only through recruiting agents registered on the Government of India eMigrate portal; never pay anyone in cash.' => 'ਵਿਦੇਸ਼ ਦੀ ਨੌਕਰੀ ਲਈ ਸਿਰਫ਼ ਭਾਰਤ ਸਰਕਾਰ ਦੇ eMigrate ਪੋਰਟਲ \'ਤੇ ਰਜਿਸਟਰਡ ਰਿਕਰੂਟਿੰਗ ਏਜੰਟਾਂ ਰਾਹੀਂ ਹੀ ਜਾਓ; ਕਦੇ ਵੀ ਕਿਸੇ ਨੂੰ ਨਕਦ ਭੁਗਤਾਨ ਨਾ ਕਰੋ।',
