  'Sweeper / Housekeeping' => 'ਸਵੀਪਰ / ਹਾਊਸਕੀਪਿੰਗ',
  'Other hospital staff (nurse, technician, pharmacist, ward boy…)' => 'ਹੋਰ ਹਸਪਤਾਲ ਸਟਾਫ਼ (ਨਰਸ, ਟੈਕਨੀਸ਼ੀਅਨ, ਫਾਰਮਾਸਿਸਟ, ਵਾਰਡ ਬੁਆਏ…)',
  'Doctor & Hospital Staff Job Registration' => 'ਡਾਕਟਰ ਅਤੇ ਹਸਪਤਾਲ ਸਟਾਫ਼ ਨੌਕਰੀ ਰਜਿਸਟ੍ਰੇਸ਼ਨ',
  'Doctors, nurses, front desk & hospital staff – register for jobs' => 'ਡਾਕਟਰ, ਨਰਸਾਂ, ਫਰੰਟ ਡੈਸਕ ਅਤੇ ਹਸਪਤਾਲ ਸਟਾਫ਼ – ਨੌਕਰੀ ਲਈ ਰਜਿਸਟਰ ਕਰੋ',
  'Jobs in hospitals, clinics and nursing homes. Keywords from your brief and resume are matched with what hospitals need. Registration is valid for 1 month.' => 'ਹਸਪਤਾਲਾਂ, ਕਲੀਨਿਕਾਂ ਅਤੇ ਨਰਸਿੰਗ ਹੋਮਾਂ ਵਿੱਚ ਨੌਕਰੀਆਂ। ਤੁਹਾਡੇ ਸੰਖੇਪ ਵੇਰਵੇ ਅਤੇ ਰਿਜ਼ਿਊਮੇ ਦੇ ਕੀਵਰਡ ਹਸਪਤਾਲਾਂ ਦੀ ਲੋੜ ਨਾਲ ਮਿਲਾਏ ਜਾਂਦੇ ਹਨ। ਰਜਿਸਟ੍ਰੇਸ਼ਨ 1 ਮਹੀਨੇ ਲਈ ਵੈਧ ਹੈ।',
  'Specialisation / post – up to 5 (e.g. MD Medicine, Staff Nurse, Lab Technician)' => 'ਮੁਹਾਰਤ / ਅਹੁਦਾ – ਵੱਧ ਤੋਂ ਵੱਧ 5 (ਜਿਵੇਂ MD Medicine, Staff Nurse, Lab Technician)',
  'Fees (by role, 1 month)' => 'ਫ਼ੀਸ (ਭੂਮਿਕਾ ਅਨੁਸਾਰ, 1 ਮਹੀਨਾ)',
  'Doctor: ₹4,500 + GST = ₹5,310' => 'ਡਾਕਟਰ: ₹4,500 + GST = ₹5,310',
  'Front desk / Sales & marketing: ₹1,500 + GST = ₹1,770' => 'ਫਰੰਟ ਡੈਸਕ / ਸੇਲਜ਼ ਅਤੇ ਮਾਰਕੀਟਿੰਗ: ₹1,500 + GST = ₹1,770',
  'Sweeper / Housekeeping: ₹500 + GST = ₹590 (one-time)' => 'ਸਵੀਪਰ / ਹਾਊਸਕੀਪਿੰਗ: ₹500 + GST = ₹590 (ਇੱਕ ਵਾਰ)',
  'Other hospital staff: ₹600 + GST = ₹708' => 'ਹੋਰ ਹਸਪਤਾਲ ਸਟਾਫ਼: ₹600 + GST = ₹708',
  'Your Role' => 'ਤੁਹਾਡੀ ਭੂਮਿਕਾ',
  'Role you are registering for' => 'ਤੁਸੀਂ ਕਿਸ ਭੂਮਿਕਾ ਲਈ ਰਜਿਸਟਰ ਕਰ ਰਹੇ ਹੋ',
  'Medical / Nursing Council registration no. (for doctors / nurses)' => 'ਮੈਡੀਕਲ / ਨਰਸਿੰਗ ਕੌਂਸਲ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਨੰ. (ਡਾਕਟਰਾਂ / ਨਰਸਾਂ ਲਈ)',
  'Brief – your skills, departments, shifts (these keywords are matched)' => 'ਸੰਖੇਪ ਵੇਰਵਾ – ਤੁਹਾਡੇ ਹੁਨਰ, ਵਿਭਾਗ, ਸ਼ਿਫ਼ਟਾਂ (ਇਹੀ ਕੀਵਰਡ ਮਿਲਾਏ ਜਾਂਦੇ ਹਨ)',
  'Resume (PDF/DOC, max 5MB) – its keywords are matched too' => 'ਰਿਜ਼ਿਊਮੇ (PDF/DOC, ਵੱਧ ਤੋਂ ਵੱਧ 5MB) – ਇਸਦੇ ਕੀਵਰਡ ਵੀ ਮਿਲਾਏ ਜਾਂਦੇ ਹਨ',
  'The fee is non-refundable and the registration is valid for 1 month from payment.' => 'ਫ਼ੀਸ ਵਾਪਸ ਨਹੀਂ ਹੋਵੇਗੀ ਅਤੇ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਭੁਗਤਾਨ ਤੋਂ 1 ਮਹੀਨੇ ਤੱਕ ਵੈਧ ਹੈ।',
  'I agree that paying hospitals / clinics can see my profile, resume and contact details.' => 'ਮੈਂ ਸਹਿਮਤ ਹਾਂ ਕਿ ਭੁਗਤਾਨ ਕਰਨ ਵਾਲੇ ਹਸਪਤਾਲ / ਕਲੀਨਿਕ ਮੇਰੀ ਪ੍ਰੋਫਾਈਲ, ਰਿਜ਼ਿਊਮੇ ਅਤੇ ਸੰਪਰਕ ਵੇਰਵੇ ਦੇਖ ਸਕਦੇ ਹਨ।',
  'For 1 month your profile is shown to hospitals whose needs match your keywords.' => '1 ਮਹੀਨੇ ਲਈ ਤੁਹਾਡੀ ਪ੍ਰੋਫਾਈਲ ਉਹਨਾਂ ਹਸਪਤਾਲਾਂ ਨੂੰ ਦਿਖਾਈ ਜਾਂਦੀ ਹੈ ਜਿਨ੍ਹਾਂ ਦੀ ਲੋੜ ਤੁਹਾਡੇ ਕੀਵਰਡਾਂ ਨਾਲ ਮਿਲਦੀ ਹੈ।',
  'Hospitals will contact you directly by call / email.' => 'ਹਸਪਤਾਲ ਤੁਹਾਡੇ ਨਾਲ ਸਿੱਧਾ ਕਾਲ / ਈਮੇਲ ਰਾਹੀਂ ਸੰਪਰਕ ਕਰਨਗੇ।',
  'Hospital / Clinic – Hire Doctors & Staff' => 'ਹਸਪਤਾਲ / ਕਲੀਨਿਕ – ਡਾਕਟਰ ਅਤੇ ਸਟਾਫ਼ ਭਰਤੀ ਕਰੋ',
  'Need doctors or hospital staff? Register here' => 'ਡਾਕਟਰ ਜਾਂ ਹਸਪਤਾਲ ਸਟਾਫ਼ ਚਾਹੀਦਾ ਹੈ? ਇੱਥੇ ਰਜਿਸਟਰ ਕਰੋ',
  'Describe your need – we match your keywords with candidates’ briefs and resumes. One-time fee; see names, numbers, emails and resumes for 15 days.' => 'ਆਪਣੀ ਲੋੜ ਲਿਖੋ – ਅਸੀਂ ਤੁਹਾਡੇ ਕੀਵਰਡਾਂ ਨੂੰ ਉਮੀਦਵਾਰਾਂ ਦੇ ਵੇਰਵਿਆਂ ਅਤੇ ਰਿਜ਼ਿਊਮਿਆਂ ਨਾਲ ਮਿਲਾਉਂਦੇ ਹਾਂ। ਇੱਕ ਵਾਰ ਦੀ ਫ਼ੀਸ; 15 ਦਿਨਾਂ ਤੱਕ ਨਾਮ, ਨੰਬਰ, ਈਮੇਲ ਅਤੇ ਰਿਜ਼ਿਊਮੇ ਦੇਖੋ।',
  'Specialisation / post needed – up to 5' => 'ਲੋੜੀਂਦੀ ਮੁਹਾਰਤ / ਅਹੁਦਾ – ਵੱਧ ਤੋਂ ਵੱਧ 5',
  'Fees (one-time, valid 15 days)' => 'ਫ਼ੀਸ (ਇੱਕ ਵਾਰ, 15 ਦਿਨਾਂ ਲਈ ਵੈਧ)',
