  'The fee is non-refundable; access is valid for 15 days from payment.' => 'ਫ਼ੀਸ ਵਾਪਸ ਨਹੀਂ ਹੋਵੇਗੀ; ਐਕਸੈੱਸ ਭੁਗਤਾਨ ਤੋਂ 15 ਦਿਨਾਂ ਤੱਕ ਵੈਧ ਹੈ।',
  'Candidates’ details will be used only for hiring and never shared or sold.' => 'ਉਮੀਦਵਾਰਾਂ ਦੇ ਵੇਰਵੇ ਸਿਰਫ਼ ਭਰਤੀ ਲਈ ਵਰਤੇ ਜਾਣਗੇ ਅਤੇ ਕਦੇ ਵੀ ਸਾਂਝੇ ਜਾਂ ਵੇਚੇ ਨਹੀਂ ਜਾਣਗੇ।',
  'See matching candidates now – with name, mobile, email and resume (15 days).' => 'ਮੇਲ ਖਾਂਦੇ ਉਮੀਦਵਾਰ ਹੁਣੇ ਦੇਖੋ – ਨਾਮ, ਮੋਬਾਈਲ, ਈਮੇਲ ਅਤੇ ਰਿਜ਼ਿਊਮੇ ਦੇ ਨਾਲ (15 ਦਿਨ)।',
  'Hire Part-time People – Talent Pass (2 days)' => 'ਪਾਰਟ-ਟਾਈਮ ਲੋਕ ਭਰਤੀ ਕਰੋ – ਟੈਲੇਂਟ ਪਾਸ (2 ਦਿਨ)',
  'Need exhibition staff, models, bouncers, drivers? 2-day pass' => 'ਪ੍ਰਦਰਸ਼ਨੀ ਸਟਾਫ਼, ਮਾਡਲ, ਬਾਊਂਸਰ, ਡਰਾਈਵਰ ਚਾਹੀਦੇ ਹਨ? 2 ਦਿਨਾਂ ਦਾ ਪਾਸ',
  'For ₹5,000 + 18% GST (₹5,900), search part-time candidates by resume keywords for 2 days and contact them directly.' => '₹5,000 + 18% GST (₹5,900) ਵਿੱਚ 2 ਦਿਨਾਂ ਤੱਕ ਰਿਜ਼ਿਊਮੇ ਕੀਵਰਡਾਂ ਨਾਲ ਪਾਰਟ-ਟਾਈਮ ਉਮੀਦਵਾਰ ਖੋਜੋ ਅਤੇ ਉਹਨਾਂ ਨਾਲ ਸਿੱਧਾ ਸੰਪਰਕ ਕਰੋ।',
  'Work you are hiring for – up to 5' => 'ਤੁਸੀਂ ਕਿਸ ਕੰਮ ਲਈ ਭਰਤੀ ਕਰ ਰਹੇ ਹੋ – ਵੱਧ ਤੋਂ ਵੱਧ 5',
  '₹5,000 + 18% GST = ₹5,900, valid for 2 days (48 hours) from payment.' => '₹5,000 + 18% GST = ₹5,900, ਭੁਗਤਾਨ ਤੋਂ 2 ਦਿਨ (48 ਘੰਟੇ) ਤੱਕ ਵੈਧ।',
  'Search by work, city / PIN, hours, days and resume keywords.' => 'ਕੰਮ, ਸ਼ਹਿਰ / ਪਿੰਨ, ਘੰਟਿਆਂ, ਦਿਨਾਂ ਅਤੇ ਰਿਜ਼ਿਊਮੇ ਕੀਵਰਡਾਂ ਨਾਲ ਖੋਜੋ।',
  'Individual' => 'ਵਿਅਕਤੀ',
  'Institution' => 'ਸੰਸਥਾ',
  'Event / exhibition agency' => 'ਇਵੈਂਟ / ਪ੍ਰਦਰਸ਼ਨੀ ਏਜੰਸੀ',
  'Company / institution name (if any)' => 'ਕੰਪਨੀ / ਸੰਸਥਾ ਦਾ ਨਾਮ (ਜੇ ਕੋਈ ਹੋਵੇ)',
  'Your Name' => 'ਤੁਹਾਡਾ ਨਾਮ',
  'PIN Code' => 'ਪਿੰਨ ਕੋਡ',
