  'Brief – dates, hours, venue, how many people' => 'ਸੰਖੇਪ ਵੇਰਵਾ – ਤਾਰੀਖ਼ਾਂ, ਘੰਟੇ, ਥਾਂ, ਕਿੰਨੇ ਲੋਕ',
  '₹5,900 (₹5,000 + GST) is non-refundable; access lasts 2 days from payment.' => '₹5,900 (₹5,000 + GST) ਵਾਪਸ ਨਹੀਂ ਹੋਵੇਗੀ; ਐਕਸੈੱਸ ਭੁਗਤਾਨ ਤੋਂ 2 ਦਿਨਾਂ ਤੱਕ ਰਹਿੰਦਾ ਹੈ।',
  'Open “Talent Search” now and find candidates by keyword (2 days).' => 'ਹੁਣੇ “Talent Search” ਖੋਲ੍ਹੋ ਅਤੇ ਕੀਵਰਡ ਨਾਲ ਉਮੀਦਵਾਰ ਲੱਭੋ (2 ਦਿਨ)।',
  'Indian Railways' => 'ਭਾਰਤੀ ਰੇਲਵੇ',
