  'Police / Paramilitary' => 'ਪੁਲਿਸ / ਨੀਮ ਫ਼ੌਜੀ ਬਲ',
  'Central Govt (UPSC, SSC…)' => 'ਕੇਂਦਰ ਸਰਕਾਰ (UPSC, SSC…)',
  'State Govts' => 'ਰਾਜ ਸਰਕਾਰਾਂ',
