  'Prominent Person 1 (President / Secretary / Director)' => 'ਪ੍ਰਮੁੱਖ ਵਿਅਕਤੀ 1 (ਪ੍ਰਧਾਨ / ਸਕੱਤਰ / ਡਾਇਰੈਕਟਰ)',
  'NGO / Social Organisation Registration' => 'NGO / ਸਮਾਜਿਕ ਸੰਸਥਾ ਰਜਿਸਟ੍ਰੇਸ਼ਨ',
  'For NGOs looking for Social Service People – Register Here' => 'ਸਮਾਜ ਸੇਵਾ ਲਈ ਲੋਕ ਲੱਭ ਰਹੀਆਂ NGOs ਲਈ – ਇੱਥੇ ਰਜਿਸਟਰ ਕਰੋ',
  'Organisations looking for social service people register once for ₹155. After payment our team verifies your details. Social service applicants pay nothing.' => 'ਸਮਾਜ ਸੇਵਾ ਲਈ ਲੋਕ ਲੱਭ ਰਹੀਆਂ ਸੰਸਥਾਵਾਂ ਇੱਕ ਵਾਰ ₹155 ਦੇ ਕੇ ਰਜਿਸਟਰ ਕਰਦੀਆਂ ਹਨ। ਭੁਗਤਾਨ ਤੋਂ ਬਾਅਦ ਸਾਡੀ ਟੀਮ ਤੁਹਾਡੇ ਵੇਰਵਿਆਂ ਦੀ ਪੁਸ਼ਟੀ ਕਰਦੀ ਹੈ। ਸਮਾਜ ਸੇਵਾ ਦੇ ਬਿਨੈਕਾਰਾਂ ਤੋਂ ਕੋਈ ਫ਼ੀਸ ਨਹੀਂ ਲਈ ਜਾਂਦੀ।',
  'Social service job applicants never pay any fee.' => 'ਸਮਾਜ ਸੇਵਾ ਨੌਕਰੀਆਂ ਲਈ ਅਰਜ਼ੀ ਦੇਣ ਵਾਲੇ ਕਦੇ ਵੀ ਕੋਈ ਫ਼ੀਸ ਨਹੀਂ ਦਿੰਦੇ।',
  'One organisation = one email + one mobile + one registration / GST number.' => 'ਇੱਕ ਸੰਸਥਾ = ਇੱਕ ਈਮੇਲ + ਇੱਕ ਮੋਬਾਈਲ + ਇੱਕ ਰਜਿਸਟ੍ਰੇਸ਼ਨ / GST ਨੰਬਰ।',
  'After payment the Jobsence team verifies your organisation’s details and documents; your profile shows “Verified” only after verification.' => 'ਭੁਗਤਾਨ ਤੋਂ ਬਾਅਦ Jobsence ਟੀਮ ਤੁਹਾਡੀ ਸੰਸਥਾ ਦੇ ਵੇਰਵਿਆਂ ਅਤੇ ਦਸਤਾਵੇਜ਼ਾਂ ਦੀ ਪੁਸ਼ਟੀ ਕਰਦੀ ਹੈ; ਪੁਸ਼ਟੀ ਤੋਂ ਬਾਅਦ ਹੀ ਤੁਹਾਡੀ ਪ੍ਰੋਫਾਈਲ \'ਤੇ “Verified” ਦਿਖਾਈ ਦਿੰਦਾ ਹੈ।',
  'Social service roles you need people for (search the list)' => 'ਸਮਾਜ ਸੇਵਾ ਦੇ ਕਿਹੜੇ ਕੰਮਾਂ ਲਈ ਤੁਹਾਨੂੰ ਲੋਕ ਚਾਹੀਦੇ ਹਨ (ਸੂਚੀ ਵਿੱਚ ਖੋਜੋ)',
  'Organisation Details' => 'ਸੰਸਥਾ ਦੇ ਵੇਰਵੇ',
  'Organisation Name (as registered)' => 'ਸੰਸਥਾ ਦਾ ਨਾਮ (ਜਿਵੇਂ ਰਜਿਸਟਰਡ ਹੈ)',
  'Type of Organisation' => 'ਸੰਸਥਾ ਦੀ ਕਿਸਮ',
