  'Registration Number (Trust / Society / CIN)' => 'ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਨੰਬਰ (ਟਰੱਸਟ / ਸੋਸਾਇਟੀ / CIN)',
  'NGO Darpan ID (if any)' => 'NGO Darpan ID (ਜੇ ਕੋਈ ਹੋਵੇ)',
  'GST Number' => 'GST ਨੰਬਰ',
  'Organisation PAN (if any)' => 'ਸੰਸਥਾ ਦਾ PAN (ਜੇ ਕੋਈ ਹੋਵੇ)',
