  'Website / Social media (if any)' => 'ਵੈੱਬਸਾਈਟ / ਸੋਸ਼ਲ ਮੀਡੀਆ (ਜੇ ਕੋਈ ਹੋਵੇ)',
  'About the organisation (work, reach, beneficiaries)' => 'ਸੰਸਥਾ ਬਾਰੇ (ਕੰਮ, ਪਹੁੰਚ, ਲਾਭਪਾਤਰੀ)',
  'Contact (OTP will be sent to email)' => 'ਸੰਪਰਕ (OTP ਈਮੇਲ \'ਤੇ ਭੇਜਿਆ ਜਾਵੇਗਾ)',
  'Mobile Number (WhatsApp)' => 'ਮੋਬਾਈਲ ਨੰਬਰ (WhatsApp)',
  'Organisation Email' => 'ਸੰਸਥਾ ਦੀ ਈਮੇਲ',
  'Prominent Persons' => 'ਪ੍ਰਮੁੱਖ ਵਿਅਕਤੀ',
  'People You Are Looking For' => 'ਤੁਸੀਂ ਕਿਹੋ ਜਿਹੇ ਲੋਕ ਲੱਭ ਰਹੇ ਹੋ',
  'Where the work is (cities / districts)' => 'ਕੰਮ ਕਿੱਥੇ ਹੈ (ਸ਼ਹਿਰ / ਜ਼ਿਲ੍ਹੇ)',
  'All organisation details are true and I am authorised to register on behalf of the organisation.' => 'ਸੰਸਥਾ ਦੇ ਸਾਰੇ ਵੇਰਵੇ ਸਹੀ ਹਨ ਅਤੇ ਮੈਂ ਸੰਸਥਾ ਵੱਲੋਂ ਰਜਿਸਟਰ ਕਰਨ ਲਈ ਅਧਿਕਾਰਤ ਹਾਂ।',
  'The one-time registration fee of ₹155 (including GST) is non-refundable.' => '₹155 (GST ਸਮੇਤ) ਦੀ ਇੱਕ ਵਾਰ ਦੀ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਫ਼ੀਸ ਵਾਪਸ ਨਹੀਂ ਹੋਵੇਗੀ।',
  'After payment Jobsence will verify the documents; registrations with false information may be cancelled.' => 'ਭੁਗਤਾਨ ਤੋਂ ਬਾਅਦ Jobsence ਦਸਤਾਵੇਜ਼ਾਂ ਦੀ ਪੁਸ਼ਟੀ ਕਰੇਗਾ; ਗਲਤ ਜਾਣਕਾਰੀ ਵਾਲੀਆਂ ਰਜਿਸਟ੍ਰੇਸ਼ਨਾਂ ਰੱਦ ਕੀਤੀਆਂ ਜਾ ਸਕਦੀਆਂ ਹਨ।',
  'We will not charge social service applicants any fee.' => 'ਅਸੀਂ ਸਮਾਜ ਸੇਵਾ ਦੇ ਬਿਨੈਕਾਰਾਂ ਤੋਂ ਕੋਈ ਫ਼ੀਸ ਨਹੀਂ ਲਵਾਂਗੇ।',
  'The Jobsence team will verify your organisation’s details and documents.' => 'Jobsence ਟੀਮ ਤੁਹਾਡੀ ਸੰਸਥਾ ਦੇ ਵੇਰਵਿਆਂ ਅਤੇ ਦਸਤਾਵੇਜ਼ਾਂ ਦੀ ਪੁਸ਼ਟੀ ਕਰੇਗੀ।',
  'Once verified you will receive an email and can start connecting with social service people.' => 'ਪੁਸ਼ਟੀ ਹੋਣ \'ਤੇ ਤੁਹਾਨੂੰ ਈਮੇਲ ਮਿਲੇਗੀ ਅਤੇ ਤੁਸੀਂ ਸਮਾਜ ਸੇਵਾ ਵਾਲੇ ਲੋਕਾਂ ਨਾਲ ਜੁੜਨਾ ਸ਼ੁਰੂ ਕਰ ਸਕੋਗੇ।',
  'Full Name / Contact Person' => 'ਪੂਰਾ ਨਾਮ / ਸੰਪਰਕ ਵਿਅਕਤੀ',
  'Aadhaar Number (individual mentor / contact person)' => 'ਆਧਾਰ ਨੰਬਰ (ਵਿਅਕਤੀਗਤ ਮੈਂਟਰ / ਸੰਪਰਕ ਵਿਅਕਤੀ)',
  'Mandatory only for an individual mentor / trainer; optional for groups, institutes, PSUs and Govt bodies. We store only the last 4 digits.' => 'ਸਿਰਫ਼ ਵਿਅਕਤੀਗਤ ਮੈਂਟਰ / ਟ੍ਰੇਨਰ ਲਈ ਲਾਜ਼ਮੀ; ਗਰੁੱਪਾਂ, ਸੰਸਥਾਨਾਂ, PSUs ਅਤੇ ਸਰਕਾਰੀ ਅਦਾਰਿਆਂ ਲਈ ਵਿਕਲਪਿਕ। ਅਸੀਂ ਸਿਰਫ਼ ਆਖ਼ਰੀ 4 ਅੰਕ ਸੰਭਾਲਦੇ ਹਾਂ।',
  'Mentor Enrolment Form – Jobsence Skill Development Team' => 'ਮੈਂਟਰ ਦਾਖ਼ਲਾ ਫਾਰਮ – Jobsence ਸਕਿੱਲ ਡਿਵੈਲਪਮੈਂਟ ਟੀਮ',
  'For Skill Providers / Mentors / Training Institutes – Register Here' => 'ਸਕਿੱਲ ਪ੍ਰੋਵਾਈਡਰਾਂ / ਮੈਂਟਰਾਂ / ਟ੍ਰੇਨਿੰਗ ਸੰਸਥਾਨਾਂ ਲਈ – ਇੱਥੇ ਰਜਿਸਟਰ ਕਰੋ',
  'What You Will Get & Important Conditions' => 'ਤੁਹਾਨੂੰ ਕੀ ਮਿਲੇਗਾ ਅਤੇ ਮਹੱਤਵਪੂਰਨ ਸ਼ਰਤਾਂ',
  'Fixed emolument (fixed payment) per candidate – for video / online classes and for offline classes (Delhi-NCR).' => 'ਪ੍ਰਤੀ ਉਮੀਦਵਾਰ ਨਿਸ਼ਚਿਤ ਮਾਣ-ਭੱਤਾ (ਫਿਕਸਡ ਭੁਗਤਾਨ) – ਵੀਡੀਓ / ਔਨਲਾਈਨ ਕਲਾਸਾਂ ਅਤੇ ਔਫਲਾਈਨ ਕਲਾਸਾਂ (ਦਿੱਲੀ-NCR) ਲਈ।',
  'Payment is given only after successful completion of the candidate’s training.' => 'ਭੁਗਤਾਨ ਸਿਰਫ਼ ਉਮੀਦਵਾਰ ਦੀ ਟ੍ਰੇਨਿੰਗ ਸਫਲਤਾਪੂਰਵਕ ਪੂਰੀ ਹੋਣ ਤੋਂ ਬਾਅਦ ਹੀ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ।',
  'You must send your details with a demo video. The video must clearly mention: “This video is for Jobsence Skill Development”.' => 'ਤੁਹਾਨੂੰ ਆਪਣੇ ਵੇਰਵੇ ਇੱਕ ਡੈਮੋ ਵੀਡੀਓ ਦੇ ਨਾਲ ਭੇਜਣੇ ਲਾਜ਼ਮੀ ਹਨ। ਵੀਡੀਓ ਵਿੱਚ ਸਾਫ਼ ਦੱਸਿਆ ਹੋਣਾ ਚਾਹੀਦਾ ਹੈ: “This video is for Jobsence Skill Development”।',
  'All videos will be the property of Jobsence – you cannot use them anywhere else.' => 'ਸਾਰੀਆਂ ਵੀਡੀਓਜ਼ Jobsence ਦੀ ਸੰਪਤੀ ਹੋਣਗੀਆਂ – ਤੁਸੀਂ ਇਹਨਾਂ ਨੂੰ ਹੋਰ ਕਿਤੇ ਨਹੀਂ ਵਰਤ ਸਕਦੇ।',
  'You must follow Jobsence rules & guidelines.' => 'ਤੁਹਾਨੂੰ Jobsence ਦੇ ਨਿਯਮਾਂ ਅਤੇ ਦਿਸ਼ਾ-ਨਿਰਦੇਸ਼ਾਂ ਦੀ ਪਾਲਣਾ ਕਰਨੀ ਲਾਜ਼ਮੀ ਹੈ।',
  '20% of what Jobsence receives from candidates goes to skill development agencies / mentors; the rest (after company operating expenses) is used to build Jobsence’s own skill development centre.' => 'Jobsence ਨੂੰ ਉਮੀਦਵਾਰਾਂ ਤੋਂ ਮਿਲਣ ਵਾਲੀ ਰਕਮ ਦਾ 20% ਸਕਿੱਲ ਡਿਵੈਲਪਮੈਂਟ ਏਜੰਸੀਆਂ / ਮੈਂਟਰਾਂ ਨੂੰ ਜਾਂਦਾ ਹੈ; ਬਾਕੀ (ਕੰਪਨੀ ਦੇ ਸੰਚਾਲਨ ਖ਼ਰਚਿਆਂ ਤੋਂ ਬਾਅਦ) Jobsence ਦਾ ਆਪਣਾ ਸਕਿੱਲ ਡਿਵੈਲਪਮੈਂਟ ਸੈਂਟਰ ਬਣਾਉਣ ਲਈ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ।',
  'Training institutes, PSUs and government bodies can also offer skill development.' => 'ਟ੍ਰੇਨਿੰਗ ਸੰਸਥਾਨ, PSUs ਅਤੇ ਸਰਕਾਰੀ ਅਦਾਰੇ ਵੀ ਸਕਿੱਲ ਡਿਵੈਲਪਮੈਂਟ ਦੀ ਪੇਸ਼ਕਸ਼ ਕਰ ਸਕਦੇ ਹਨ।',
  'Skills you can teach (search 3000+ list, select multiple)' => 'ਹੁਨਰ ਜੋ ਤੁਸੀਂ ਸਿਖਾ ਸਕਦੇ ਹੋ (3000+ ਦੀ ਸੂਚੀ ਵਿੱਚ ਖੋਜੋ, ਇੱਕ ਤੋਂ ਵੱਧ ਚੁਣੋ)',
  'Who Are You' => 'ਤੁਸੀਂ ਕੌਣ ਹੋ',
  'Registering As' => 'ਕਿਸ ਵਜੋਂ ਰਜਿਸਟਰ ਕਰ ਰਹੇ ਹੋ',
  'Individual Mentor / Trainer' => 'ਵਿਅਕਤੀਗਤ ਮੈਂਟਰ / ਟ੍ਰੇਨਰ',
  'Group Mentoring' => 'ਗਰੁੱਪ ਮੈਂਟਰਿੰਗ',
  'Training Institute / Skill Provider' => 'ਟ੍ਰੇਨਿੰਗ ਸੰਸਥਾਨ / ਸਕਿੱਲ ਪ੍ਰੋਵਾਈਡਰ',
  'PSU (Public Sector Undertaking)' => 'PSU (ਜਨਤਕ ਖੇਤਰ ਦਾ ਅਦਾਰਾ)',
  'Government Department / Body' => 'ਸਰਕਾਰੀ ਵਿਭਾਗ / ਅਦਾਰਾ',
  'Institute / PSU / Department name (not for individual mentors)' => 'ਸੰਸਥਾਨ / PSU / ਵਿਭਾਗ ਦਾ ਨਾਮ (ਵਿਅਕਤੀਗਤ ਮੈਂਟਰਾਂ ਲਈ ਨਹੀਂ)',
  'GST is not mandatory for an individual mentor / trainer or group mentoring.' => 'ਵਿਅਕਤੀਗਤ ਮੈਂਟਰ / ਟ੍ਰੇਨਰ ਜਾਂ ਗਰੁੱਪ ਮੈਂਟਰਿੰਗ ਲਈ GST ਲਾਜ਼ਮੀ ਨਹੀਂ ਹੈ।',
  'What You Can Teach' => 'ਤੁਸੀਂ ਕੀ ਸਿਖਾ ਸਕਦੇ ਹੋ',
  'Mode You Prefer' => 'ਤੁਹਾਡਾ ਪਸੰਦੀਦਾ ਤਰੀਕਾ',
  'Only Online / Video' => 'ਸਿਰਫ਼ ਔਨਲਾਈਨ / ਵੀਡੀਓ',
  'Only Offline (Delhi-NCR)' => 'ਸਿਰਫ਼ ਔਫਲਾਈਨ (ਦਿੱਲੀ-NCR)',
  'Both' => 'ਦੋਵੇਂ',
  'Experience in Teaching / Working (Years)' => 'ਪੜ੍ਹਾਉਣ / ਕੰਮ ਦਾ ਤਜਰਬਾ (ਸਾਲ)',
  'Languages You Can Teach' => 'ਭਾਸ਼ਾਵਾਂ ਜਿਨ੍ਹਾਂ ਵਿੱਚ ਤੁਸੀਂ ਪੜ੍ਹਾ ਸਕਦੇ ਹੋ',
  'Brief education & experience (qualification, where you worked / taught)' => 'ਸਿੱਖਿਆ ਅਤੇ ਤਜਰਬਾ ਸੰਖੇਪ ਵਿੱਚ (ਯੋਗਤਾ, ਤੁਸੀਂ ਕਿੱਥੇ ਕੰਮ ਕੀਤਾ / ਪੜ੍ਹਾਇਆ)',
  'Certifications / Licences (if any)' => 'ਸਰਟੀਫਿਕੇਟ / ਲਾਇਸੈਂਸ (ਜੇ ਕੋਈ ਹੋਵੇ)',
  'Upload documents / certificates (PDF/JPG/PNG/DOC, max 5MB)' => 'ਦਸਤਾਵੇਜ਼ / ਸਰਟੀਫਿਕੇਟ ਅੱਪਲੋਡ ਕਰੋ (PDF/JPG/PNG/DOC, ਵੱਧ ਤੋਂ ਵੱਧ 5MB)',
  'Expected Emolument per candidate ₹ (optional)' => 'ਪ੍ਰਤੀ ਉਮੀਦਵਾਰ ਉਮੀਦ ਕੀਤਾ ਮਾਣ-ਭੱਤਾ ₹ (ਵਿਕਲਪਿਕ)',
  'Upload Demo Video (mandatory – MP4/MOV/WEBM, max 200MB)' => 'ਡੈਮੋ ਵੀਡੀਓ ਅੱਪਲੋਡ ਕਰੋ (ਲਾਜ਼ਮੀ – MP4/MOV/WEBM, ਵੱਧ ਤੋਂ ਵੱਧ 200MB)',
  'The video must show / say “This video is for Jobsence”. If the file is too large, give a Google Drive / YouTube (Unlisted) link below.' => 'ਵੀਡੀਓ ਵਿੱਚ “This video is for Jobsence” ਦਿਖਾਇਆ / ਬੋਲਿਆ ਜਾਣਾ ਲਾਜ਼ਮੀ ਹੈ। ਜੇ ਫ਼ਾਈਲ ਬਹੁਤ ਵੱਡੀ ਹੈ, ਤਾਂ ਹੇਠਾਂ Google Drive / YouTube (Unlisted) ਲਿੰਕ ਦਿਓ।',
  'Or video link (Google Drive / YouTube Unlisted)' => 'ਜਾਂ ਵੀਡੀਓ ਲਿੰਕ (Google Drive / YouTube Unlisted)',
  'Bank Details (for payment)' => 'ਬੈਂਕ ਵੇਰਵੇ (ਭੁਗਤਾਨ ਲਈ)',
  'Account Holder Name' => 'ਖਾਤਾਧਾਰਕ ਦਾ ਨਾਮ',
  'Bank Account Number (outside India: account number / IBAN)' => 'ਬੈਂਕ ਖਾਤਾ ਨੰਬਰ (ਭਾਰਤ ਤੋਂ ਬਾਹਰ: ਖਾਤਾ ਨੰਬਰ / IBAN)',
  'Your account number is stored encrypted.' => 'ਤੁਹਾਡਾ ਖਾਤਾ ਨੰਬਰ ਇਨਕ੍ਰਿਪਟ ਕਰਕੇ ਸੰਭਾਲਿਆ ਜਾਂਦਾ ਹੈ।',
  'IFSC Code (outside India: SWIFT / BIC code)' => 'IFSC ਕੋਡ (ਭਾਰਤ ਤੋਂ ਬਾਹਰ: SWIFT / BIC ਕੋਡ)',
  'I agree that all videos submitted by me will be the sole property of Jobsence.' => 'ਮੈਂ ਸਹਿਮਤ ਹਾਂ ਕਿ ਮੇਰੇ ਵੱਲੋਂ ਜਮ੍ਹਾਂ ਕੀਤੀਆਂ ਸਾਰੀਆਂ ਵੀਡੀਓਜ਼ ਸਿਰਫ਼ Jobsence ਦੀ ਸੰਪਤੀ ਹੋਣਗੀਆਂ।',
  'I will not use these videos anywhere else.' => 'ਮੈਂ ਇਹਨਾਂ ਵੀਡੀਓਜ਼ ਨੂੰ ਹੋਰ ਕਿਤੇ ਨਹੀਂ ਵਰਤਾਂਗਾ/ਵਰਤਾਂਗੀ।',
  'I will follow all rules of Jobsence.' => 'ਮੈਂ Jobsence ਦੇ ਸਾਰੇ ਨਿਯਮਾਂ ਦੀ ਪਾਲਣਾ ਕਰਾਂਗਾ/ਕਰਾਂਗੀ।',
  'I understand that emolument will be paid per candidate only after successful training.' => 'ਮੈਂ ਸਮਝਦਾ/ਸਮਝਦੀ ਹਾਂ ਕਿ ਮਾਣ-ਭੱਤਾ ਪ੍ਰਤੀ ਉਮੀਦਵਾਰ ਸਿਰਫ਼ ਸਫਲ ਟ੍ਰੇਨਿੰਗ ਤੋਂ ਬਾਅਦ ਹੀ ਦਿੱਤਾ ਜਾਵੇਗਾ।',
  'Registration is free. To connect with candidates (full profile, agreement, contact) a paid plan of ₹155 (incl. GST) is needed – 30 days, 3 profiles a day; USD 5 for mentors living outside India.' => 'ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਮੁਫ਼ਤ ਹੈ। ਉਮੀਦਵਾਰਾਂ ਨਾਲ ਜੁੜਨ (ਪੂਰੀ ਪ੍ਰੋਫਾਈਲ, ਸਮਝੌਤਾ, ਸੰਪਰਕ) ਲਈ ₹155 (GST ਸਮੇਤ) ਦਾ ਪੇਡ ਪਲਾਨ ਲੋੜੀਂਦਾ ਹੈ – 30 ਦਿਨ, ਰੋਜ਼ਾਨਾ 3 ਪ੍ਰੋਫਾਈਲਾਂ; ਭਾਰਤ ਤੋਂ ਬਾਹਰ ਰਹਿਣ ਵਾਲੇ ਮੈਂਟਰਾਂ ਲਈ USD 5।',
  'There is no guarantee of selection; work will be given as per requirement.' => 'ਚੋਣ ਦੀ ਕੋਈ ਗਾਰੰਟੀ ਨਹੀਂ ਹੈ; ਕੰਮ ਲੋੜ ਅਨੁਸਾਰ ਦਿੱਤਾ ਜਾਵੇਗਾ।',
  'The Jobsence team will review your form and video – after verification candidates can see you.' => 'Jobsence ਟੀਮ ਤੁਹਾਡੇ ਫਾਰਮ ਅਤੇ ਵੀਡੀਓ ਦੀ ਸਮੀਖਿਆ ਕਰੇਗੀ – ਪੁਸ਼ਟੀ ਤੋਂ ਬਾਅਦ ਉਮੀਦਵਾਰ ਤੁਹਾਨੂੰ ਦੇਖ ਸਕਣਗੇ।',
  'Open “My mentoring dashboard” now: see who wants to learn which skill and get the ₹155 plan (USD 5 outside India).' => 'ਹੁਣੇ “ਮੇਰਾ ਮੈਂਟਰਿੰਗ ਡੈਸ਼ਬੋਰਡ” ਖੋਲ੍ਹੋ: ਦੇਖੋ ਕੌਣ ਕਿਹੜਾ ਹੁਨਰ ਸਿੱਖਣਾ ਚਾਹੁੰਦਾ ਹੈ ਅਤੇ ₹155 ਦਾ ਪਲਾਨ ਲਓ (ਭਾਰਤ ਤੋਂ ਬਾਹਰ USD 5)।',
  'If selected, you will be added to the Jobsence Mentor Team; work will be given as per requirement.' => 'ਚੋਣ ਹੋਣ \'ਤੇ ਤੁਹਾਨੂੰ Jobsence ਮੈਂਟਰ ਟੀਮ ਵਿੱਚ ਸ਼ਾਮਲ ਕੀਤਾ ਜਾਵੇਗਾ; ਕੰਮ ਲੋੜ ਅਨੁਸਾਰ ਦਿੱਤਾ ਜਾਵੇਗਾ।',
  'Payment will be released per candidate after training completion.' => 'ਭੁਗਤਾਨ ਪ੍ਰਤੀ ਉਮੀਦਵਾਰ, ਟ੍ਰੇਨਿੰਗ ਪੂਰੀ ਹੋਣ ਤੋਂ ਬਾਅਦ ਜਾਰੀ ਕੀਤਾ ਜਾਵੇਗਾ।',
  'Morning' => 'ਸਵੇਰ',
  'Afternoon' => 'ਦੁਪਹਿਰ',
  'Evening' => 'ਸ਼ਾਮ',
  'Weekends only' => 'ਸਿਰਫ਼ ਹਫ਼ਤੇ ਦੇ ਅੰਤ (ਸ਼ਨੀਵਾਰ-ਐਤਵਾਰ)',
  '3 days – ₹216 (₹183 + GST)' => '3 ਦਿਨ – ₹216 (₹183 + GST)',
  '7 days – ₹504 (₹427 + GST)' => '7 ਦਿਨ – ₹504 (₹427 + GST)',
  '15 days – ₹1,080 (₹915 + GST)' => '15 ਦਿਨ – ₹1,080 (₹915 + GST)',
  '1 month – ₹2,158 (₹1,829 + GST)' => '1 ਮਹੀਨਾ – ₹2,158 (₹1,829 + GST)',
  '6 months (half-yearly) – ₹10,791 (₹9,145 + GST)' => '6 ਮਹੀਨੇ (ਛਿਮਾਹੀ) – ₹10,791 (₹9,145 + GST)',
  '1 year – ₹19,424 (₹16,461 + GST)' => '1 ਸਾਲ – ₹19,424 (₹16,461 + GST)',
  '1 day – USD 12' => '1 ਦਿਨ – USD 12',
  '3 days – USD 30' => '3 ਦਿਨ – USD 30',
  '7 days – USD 60' => '7 ਦਿਨ – USD 60',
  '15 days – USD 110' => '15 ਦਿਨ – USD 110',
  '1 month – USD 200' => '1 ਮਹੀਨਾ – USD 200',
  '6 months (half-yearly) – USD 1,000' => '6 ਮਹੀਨੇ (ਛਿਮਾਹੀ) – USD 1,000',
  '1 year – USD 1,800' => '1 ਸਾਲ – USD 1,800',
  'My registration stays valid until I get a suitable mentor / internship provider.' => 'ਮੇਰੀ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਉਦੋਂ ਤੱਕ ਵੈਧ ਰਹੇਗੀ ਜਦੋਂ ਤੱਕ ਮੈਨੂੰ ਢੁਕਵਾਂ ਮੈਂਟਰ / ਇੰਟਰਨਸ਼ਿਪ ਪ੍ਰਦਾਤਾ ਨਹੀਂ ਮਿਲ ਜਾਂਦਾ।',
  'If I reject my mentor / provider after the agreement is signed, I must pay the form fee again for a new registration.' => 'ਜੇ ਸਮਝੌਤੇ \'ਤੇ ਦਸਤਖ਼ਤ ਹੋਣ ਤੋਂ ਬਾਅਦ ਮੈਂ ਆਪਣੇ ਮੈਂਟਰ / ਪ੍ਰਦਾਤਾ ਨੂੰ ਨਾਮਨਜ਼ੂਰ ਕਰਦਾ/ਕਰਦੀ ਹਾਂ, ਤਾਂ ਨਵੀਂ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਲਈ ਮੈਨੂੰ ਫਾਰਮ ਫ਼ੀਸ ਦੁਬਾਰਾ ਦੇਣੀ ਪਵੇਗੀ।',
  'Phone numbers and emails are shown only after a tripartite agreement between candidate, provider and Jobsence (signed with email OTP).' => 'ਫ਼ੋਨ ਨੰਬਰ ਅਤੇ ਈਮੇਲਾਂ ਸਿਰਫ਼ ਉਮੀਦਵਾਰ, ਪ੍ਰਦਾਤਾ ਅਤੇ Jobsence ਵਿਚਕਾਰ ਤ੍ਰੈ-ਪੱਖੀ ਸਮਝੌਤੇ (ਈਮੇਲ OTP ਨਾਲ ਦਸਤਖ਼ਤ ਕੀਤੇ) ਤੋਂ ਬਾਅਦ ਹੀ ਦਿਖਾਈਆਂ ਜਾਂਦੀਆਂ ਹਨ।',
  'Internship Provider Registration (free)' => 'ਇੰਟਰਨਸ਼ਿਪ ਪ੍ਰਦਾਤਾ ਰਜਿਸਟ੍ਰੇਸ਼ਨ (ਮੁਫ਼ਤ)',
  'Companies offering Internship – Register free' => 'ਇੰਟਰਨਸ਼ਿਪ ਦੇਣ ਵਾਲੀਆਂ ਕੰਪਨੀਆਂ – ਮੁਫ਼ਤ ਰਜਿਸਟਰ ਕਰੋ',
  'Register free and see who wants an internship in which domain. To connect: ₹155 plan (USD 5 outside India) – 10 days, 3 profiles a day, up to 20 candidates.' => 'ਮੁਫ਼ਤ ਰਜਿਸਟਰ ਕਰੋ ਅਤੇ ਦੇਖੋ ਕੌਣ ਕਿਸ ਖੇਤਰ ਵਿੱਚ ਇੰਟਰਨਸ਼ਿਪ ਚਾਹੁੰਦਾ ਹੈ। ਜੁੜਨ ਲਈ: ₹155 ਦਾ ਪਲਾਨ (ਭਾਰਤ ਤੋਂ ਬਾਹਰ USD 5) – 10 ਦਿਨ, ਰੋਜ਼ਾਨਾ 3 ਪ੍ਰੋਫਾਈਲਾਂ, ਵੱਧ ਤੋਂ ਵੱਧ 20 ਉਮੀਦਵਾਰ।',
  'Internship domains you offer (search the list)' => 'ਇੰਟਰਨਸ਼ਿਪ ਖੇਤਰ ਜੋ ਤੁਸੀਂ ਪੇਸ਼ ਕਰਦੇ ਹੋ (ਸੂਚੀ ਵਿੱਚ ਖੋਜੋ)',
  'Organisation' => 'ਸੰਸਥਾ',
  'Institute' => 'ਸੰਸਥਾਨ',
  'Individual / Professional' => 'ਵਿਅਕਤੀ / ਪ੍ਰੋਫੈਸ਼ਨਲ',
  'Company / Organisation name' => 'ਕੰਪਨੀ / ਸੰਸਥਾ ਦਾ ਨਾਮ',
  'Website (if any)' => 'ਵੈੱਬਸਾਈਟ (ਜੇ ਕੋਈ ਹੋਵੇ)',
  'Internships' => 'ਇੰਟਰਨਸ਼ਿਪਾਂ',
  'Where' => 'ਕਿੱਥੇ',
  'Paid or unpaid' => 'ਪੇਡ ਜਾਂ ਅਨਪੇਡ',
  'Paid' => 'ਪੇਡ',
  'Stipend (₹ per month) – ₹8,000 to ₹5,00,000 for paid' => 'ਵਜ਼ੀਫ਼ਾ (₹ ਪ੍ਰਤੀ ਮਹੀਨਾ) – ਪੇਡ ਲਈ ₹8,000 ਤੋਂ ₹5,00,000',
  'Number of interns' => 'ਇੰਟਰਨਾਂ ਦੀ ਗਿਣਤੀ',
  'About the internship (work, skills needed, duration)' => 'ਇੰਟਰਨਸ਼ਿਪ ਬਾਰੇ (ਕੰਮ, ਲੋੜੀਂਦੇ ਹੁਨਰ, ਮਿਆਦ)',
  'Paid internships will pay a stipend of ₹8,000 to ₹5,00,000 per month.' => 'ਪੇਡ ਇੰਟਰਨਸ਼ਿਪਾਂ ਵਿੱਚ ₹8,000 ਤੋਂ ₹5,00,000 ਪ੍ਰਤੀ ਮਹੀਨਾ ਵਜ਼ੀਫ਼ਾ ਦਿੱਤਾ ਜਾਵੇਗਾ।',
  'Candidates’ details will be used only for the internship and never shared or sold.' => 'ਉਮੀਦਵਾਰਾਂ ਦੇ ਵੇਰਵੇ ਸਿਰਫ਼ ਇੰਟਰਨਸ਼ਿਪ ਲਈ ਵਰਤੇ ਜਾਣਗੇ ਅਤੇ ਕਦੇ ਵੀ ਸਾਂਝੇ ਜਾਂ ਵੇਚੇ ਨਹੀਂ ਜਾਣਗੇ।',
  'The Jobsence team will verify your details – after that candidates can see you.' => 'Jobsence ਟੀਮ ਤੁਹਾਡੇ ਵੇਰਵਿਆਂ ਦੀ ਪੁਸ਼ਟੀ ਕਰੇਗੀ – ਉਸ ਤੋਂ ਬਾਅਦ ਉਮੀਦਵਾਰ ਤੁਹਾਨੂੰ ਦੇਖ ਸਕਣਗੇ।',
  'Open “My mentoring dashboard” now and get the ₹155 plan (USD 5 outside India; 10 days, 3 profiles a day, up to 20).' => 'ਹੁਣੇ “ਮੇਰਾ ਮੈਂਟਰਿੰਗ ਡੈਸ਼ਬੋਰਡ” ਖੋਲ੍ਹੋ ਅਤੇ ₹155 ਦਾ ਪਲਾਨ ਲਓ (ਭਾਰਤ ਤੋਂ ਬਾਹਰ USD 5; 10 ਦਿਨ, ਰੋਜ਼ਾਨਾ 3 ਪ੍ਰੋਫਾਈਲਾਂ, ਵੱਧ ਤੋਂ ਵੱਧ 20)।',
  'Companies Hiring – Free Registration' => 'ਭਰਤੀ ਕਰਨ ਵਾਲੀਆਂ ਕੰਪਨੀਆਂ – ਮੁਫ਼ਤ ਰਜਿਸਟ੍ਰੇਸ਼ਨ',
  'Companies & shops offering jobs – Register free' => 'ਨੌਕਰੀਆਂ ਦੇਣ ਵਾਲੀਆਂ ਕੰਪਨੀਆਂ ਅਤੇ ਦੁਕਾਨਾਂ – ਮੁਫ਼ਤ ਰਜਿਸਟਰ ਕਰੋ',
  'Register free and see who is ready for which job. To connect, a hiring plan: from ₹216 (3 days) to ₹19,424 (1 year) – 3, 7, 15 days, 1 month, 6 months or 1 year; outside India from USD 12 (1 day) – 3 full profiles with resume a day.' => 'ਮੁਫ਼ਤ ਰਜਿਸਟਰ ਕਰੋ ਅਤੇ ਦੇਖੋ ਕੌਣ ਕਿਹੜੀ ਨੌਕਰੀ ਲਈ ਤਿਆਰ ਹੈ। ਜੁੜਨ ਲਈ ਭਰਤੀ ਪਲਾਨ: ₹216 (3 ਦਿਨ) ਤੋਂ ₹19,424 (1 ਸਾਲ) ਤੱਕ – 3, 7, 15 ਦਿਨ, 1 ਮਹੀਨਾ, 6 ਮਹੀਨੇ ਜਾਂ 1 ਸਾਲ; ਭਾਰਤ ਤੋਂ ਬਾਹਰ USD 12 (1 ਦਿਨ) ਤੋਂ – ਰੋਜ਼ਾਨਾ ਰਿਜ਼ਿਊਮੇ ਸਮੇਤ 3 ਪੂਰੀਆਂ ਪ੍ਰੋਫਾਈਲਾਂ।',
  'Roles you hire for (search the list)' => 'ਅਹੁਦੇ ਜਿਨ੍ਹਾਂ ਲਈ ਤੁਸੀਂ ਭਰਤੀ ਕਰਦੇ ਹੋ (ਸੂਚੀ ਵਿੱਚ ਖੋਜੋ)',
  'Shop / MSME / Factory' => 'ਦੁਕਾਨ / MSME / ਫੈਕਟਰੀ',
  'School / College / Institute' => 'ਸਕੂਲ / ਕਾਲਜ / ਸੰਸਥਾਨ',
  'Individual / Household' => 'ਵਿਅਕਤੀ / ਘਰੇਲੂ',
  'Company / shop / organisation name' => 'ਕੰਪਨੀ / ਦੁਕਾਨ / ਸੰਸਥਾ ਦਾ ਨਾਮ',
  'Where are these jobs located' => 'ਇਹ ਨੌਕਰੀਆਂ ਕਿੱਥੇ ਹਨ',
  'In India (fees in ₹)' => 'ਭਾਰਤ ਵਿੱਚ (ਫ਼ੀਸ ₹ ਵਿੱਚ)',
  'Outside India (fees in USD – payable in ₹ too)' => 'ਭਾਰਤ ਤੋਂ ਬਾਹਰ (ਫ਼ੀਸ USD ਵਿੱਚ – ₹ ਵਿੱਚ ਵੀ ਭੁਗਤਾਨ ਯੋਗ)',
  'Country of the jobs (for jobs outside India)' => 'ਨੌਕਰੀਆਂ ਦਾ ਦੇਸ਼ (ਭਾਰਤ ਤੋਂ ਬਾਹਰ ਦੀਆਂ ਨੌਕਰੀਆਂ ਲਈ)',
  'Company / workplace address' => 'ਕੰਪਨੀ / ਕੰਮ ਵਾਲੀ ਥਾਂ ਦਾ ਪਤਾ',
  'Jobs' => 'ਨੌਕਰੀਆਂ',
  'Job types' => 'ਨੌਕਰੀ ਦੀਆਂ ਕਿਸਮਾਂ',
  'Full-time' => 'ਫੁੱਲ-ਟਾਈਮ',
  'Part-time' => 'ਪਾਰਟ-ਟਾਈਮ',
  'One-time work' => 'ਇੱਕ ਵਾਰ ਦਾ ਕੰਮ',
  'Number of people needed' => 'ਕਿੰਨੇ ਲੋਕ ਚਾਹੀਦੇ ਹਨ',
  'Salary (₹ per month / per day)' => 'ਤਨਖ਼ਾਹ (₹ ਪ੍ਰਤੀ ਮਹੀਨਾ / ਪ੍ਰਤੀ ਦਿਨ)',
  'About the jobs (work, timings, skills needed)' => 'ਨੌਕਰੀਆਂ ਬਾਰੇ (ਕੰਮ, ਸਮਾਂ, ਲੋੜੀਂਦੇ ਹੁਨਰ)',
  'I will not take any money from candidates in return for a job.' => 'ਮੈਂ ਨੌਕਰੀ ਦੇ ਬਦਲੇ ਉਮੀਦਵਾਰਾਂ ਤੋਂ ਕੋਈ ਪੈਸਾ ਨਹੀਂ ਲਵਾਂਗਾ/ਲਵਾਂਗੀ।',
  'The Jobsence team will verify your details – after that job seekers can see you.' => 'Jobsence ਟੀਮ ਤੁਹਾਡੇ ਵੇਰਵਿਆਂ ਦੀ ਪੁਸ਼ਟੀ ਕਰੇਗੀ – ਉਸ ਤੋਂ ਬਾਅਦ ਨੌਕਰੀ ਲੱਭਣ ਵਾਲੇ ਤੁਹਾਨੂੰ ਦੇਖ ਸਕਣਗੇ।',
  'Your details have been sent to Jobsence (gm@jobsence.com); companies outside India can write to this email with any questions.' => 'ਤੁਹਾਡੇ ਵੇਰਵੇ Jobsence (gm@jobsence.com) ਨੂੰ ਭੇਜ ਦਿੱਤੇ ਗਏ ਹਨ; ਭਾਰਤ ਤੋਂ ਬਾਹਰ ਦੀਆਂ ਕੰਪਨੀਆਂ ਕਿਸੇ ਵੀ ਸਵਾਲ ਲਈ ਇਸ ਈਮੇਲ \'ਤੇ ਲਿਖ ਸਕਦੀਆਂ ਹਨ।',
  'Open “My dashboard” now and get a hiring plan – from ₹216 (3 days) to ₹19,424 (1 year) – 3, 7, 15 days, 1 month, 6 months or 1 year; outside India from USD 12 (1 day).' => 'ਹੁਣੇ “ਮੇਰਾ ਡੈਸ਼ਬੋਰਡ” ਖੋਲ੍ਹੋ ਅਤੇ ਭਰਤੀ ਪਲਾਨ ਲਓ – ₹216 (3 ਦਿਨ) ਤੋਂ ₹19,424 (1 ਸਾਲ) ਤੱਕ – 3, 7, 15 ਦਿਨ, 1 ਮਹੀਨਾ, 6 ਮਹੀਨੇ ਜਾਂ 1 ਸਾਲ; ਭਾਰਤ ਤੋਂ ਬਾਹਰ USD 12 (1 ਦਿਨ) ਤੋਂ।',
  'Knowledge cannot be stolen by a thief, seized by a king or divided among brothers, and it is no burden. The more you give it, the more it grows – the wealth of knowledge is the greatest of all wealth.' => 'ਵਿੱਦਿਆ ਨੂੰ ਨਾ ਚੋਰ ਚੁਰਾ ਸਕਦਾ ਹੈ, ਨਾ ਰਾਜਾ ਖੋਹ ਸਕਦਾ ਹੈ, ਨਾ ਭਰਾ ਵੰਡ ਸਕਦੇ ਹਨ, ਅਤੇ ਇਹ ਕੋਈ ਬੋਝ ਨਹੀਂ ਹੈ। ਜਿੰਨਾ ਇਸਨੂੰ ਵੰਡੋ, ਓਨੀ ਹੀ ਇਹ ਵਧਦੀ ਹੈ – ਵਿੱਦਿਆ ਦਾ ਧਨ ਸਾਰੇ ਧਨਾਂ ਵਿੱਚੋਂ ਸਭ ਤੋਂ ਉੱਤਮ ਹੈ।',
  'Sanskrit Subhashita (traditional verse)' => 'ਸੰਸਕ੍ਰਿਤ ਸੁਭਾਸ਼ਿਤ (ਰਵਾਇਤੀ ਸ਼ਲੋਕ)',
  'Of all gifts, the gift of knowledge is the highest.' => 'ਸਾਰੇ ਦਾਨਾਂ ਵਿੱਚੋਂ ਗਿਆਨ ਦਾ ਦਾਨ ਸਭ ਤੋਂ ਉੱਤਮ ਹੈ।',
  'Manusmriti 4.233' => 'ਮਨੂਸਮ੍ਰਿਤੀ 4.233',
  'In this world there is nothing as purifying as knowledge.' => 'ਇਸ ਸੰਸਾਰ ਵਿੱਚ ਗਿਆਨ ਜਿੰਨਾ ਪਵਿੱਤਰ ਕਰਨ ਵਾਲਾ ਹੋਰ ਕੁਝ ਨਹੀਂ ਹੈ।',
  'Bhagavad Gita 4.38' => 'ਸ਼੍ਰੀਮਦ ਭਗਵਦ ਗੀਤਾ 4.38',
  'Were the whole earth paper, every forest a pen and the seven seas ink, the virtues of a teacher still could not be written.' => 'ਜੇ ਸਾਰੀ ਧਰਤੀ ਕਾਗ਼ਜ਼ ਹੋਵੇ, ਸਾਰੇ ਜੰਗਲ ਕਲਮ ਅਤੇ ਸੱਤੇ ਸਮੁੰਦਰ ਸਿਆਹੀ, ਤਾਂ ਵੀ ਗੁਰੂ ਦੇ ਗੁਣ ਲਿਖੇ ਨਹੀਂ ਜਾ ਸਕਦੇ।',
  'Sant Kabir, Sakhi (Gurudev ko Ang)' => 'ਸੰਤ ਕਬੀਰ, ਸਾਖੀ (ਗੁਰੂਦੇਵ ਕੋ ਅੰਗ)',
  'True giving blesses both the one who gives and the one who receives.' => 'ਸੱਚਾ ਦਾਨ ਦੇਣ ਵਾਲੇ ਅਤੇ ਲੈਣ ਵਾਲੇ – ਦੋਵਾਂ ਨੂੰ ਅਸੀਸ ਦਿੰਦਾ ਹੈ।',
  'William Shakespeare, The Merchant of Venice, Act IV Scene 1 (Portia)' => 'ਵਿਲੀਅਮ ਸ਼ੇਕਸਪੀਅਰ, ਦ ਮਰਚੈਂਟ ਆਫ਼ ਵੈਨਿਸ, ਅੰਕ 4 ਦ੍ਰਿਸ਼ 1 (ਪੋਰਸ਼ੀਆ)',
  'Sharing knowledge takes nothing from the giver – like lighting another candle from your own.' => 'ਗਿਆਨ ਵੰਡਣ ਨਾਲ ਦੇਣ ਵਾਲੇ ਦਾ ਕੁਝ ਨਹੀਂ ਘਟਦਾ – ਜਿਵੇਂ ਆਪਣੀ ਮੋਮਬੱਤੀ ਨਾਲ ਦੂਜੀ ਮੋਮਬੱਤੀ ਜਗਾਉਣਾ।',
  'Thomas Jefferson, letter to Isaac McPherson, 13 August 1813' => 'ਥਾਮਸ ਜੈਫਰਸਨ, ਆਈਜ਼ੈਕ ਮੈਕਫਰਸਨ ਨੂੰ ਪੱਤਰ, 13 ਅਗਸਤ 1813',
  'Never tire of learning, never weary of teaching others.' => 'ਸਿੱਖਣ ਤੋਂ ਕਦੇ ਨਾ ਅੱਕੋ, ਦੂਜਿਆਂ ਨੂੰ ਸਿਖਾਉਣ ਤੋਂ ਕਦੇ ਨਾ ਥੱਕੋ।',
  'Confucius, Analects (論語) 7.2 – Shu Er' => 'ਕਨਫ਼ਿਊਸ਼ੀਅਸ, ਲੁਨਯੂ (論語) 7.2 – ਸ਼ੂ ਅਰ',
  'Giving someone a fish is not as good as teaching them to fish.' => 'ਕਿਸੇ ਨੂੰ ਮੱਛੀ ਦੇਣ ਨਾਲੋਂ ਚੰਗਾ ਹੈ, ਉਸਨੂੰ ਮੱਛੀ ਫੜਨੀ ਸਿਖਾ ਦੇਣਾ।',
  'Traditional Chinese proverb' => 'ਰਵਾਇਤੀ ਚੀਨੀ ਕਹਾਵਤ',
  'Iqbal does not despair of his barren field – with a little moisture this soil is very fertile. (Give our youth a little guidance and they will flourish.)' => 'ਇਕਬਾਲ ਆਪਣੀ ਵੀਰਾਨ ਖੇਤੀ ਤੋਂ ਨਿਰਾਸ਼ ਨਹੀਂ ਹੈ – ਥੋੜ੍ਹੀ ਜਿਹੀ ਨਮੀ ਮਿਲੇ ਤਾਂ ਇਹ ਮਿੱਟੀ ਬਹੁਤ ਉਪਜਾਊ ਹੈ। (ਸਾਡੇ ਨੌਜਵਾਨਾਂ ਨੂੰ ਥੋੜ੍ਹਾ ਜਿਹਾ ਮਾਰਗਦਰਸ਼ਨ ਦਿਓ, ਉਹ ਖ਼ੂਬ ਤਰੱਕੀ ਕਰਨਗੇ।)',
  'Allama Iqbal' => 'ਅੱਲਾਮਾ ਇਕਬਾਲ',
  'When a person dies, their deeds end except three: a continuing charity, knowledge that others keep benefiting from, and a righteous child who prays for them.' => 'ਜਦੋਂ ਕੋਈ ਮਨੁੱਖ ਮਰ ਜਾਂਦਾ ਹੈ, ਤਾਂ ਉਸਦੇ ਕਰਮ ਖ਼ਤਮ ਹੋ ਜਾਂਦੇ ਹਨ, ਤਿੰਨ ਨੂੰ ਛੱਡ ਕੇ: ਲਗਾਤਾਰ ਚੱਲਣ ਵਾਲਾ ਦਾਨ, ਅਜਿਹਾ ਗਿਆਨ ਜਿਸ ਤੋਂ ਲੋਕ ਲਾਭ ਲੈਂਦੇ ਰਹਿਣ, ਅਤੇ ਨੇਕ ਔਲਾਦ ਜੋ ਉਸਦੇ ਲਈ ਦੁਆ ਕਰੇ।',
  'Hadith, Sahih Muslim 1631' => 'ਹਦੀਸ, ਸਹੀਹ ਮੁਸਲਿਮ 1631',
  'India' => 'ਭਾਰਤ',
  'Country of residence' => 'ਤੁਸੀਂ ਕਿਸ ਦੇਸ਼ ਵਿੱਚ ਰਹਿੰਦੇ ਹੋ',
  'Outside India: give your mobile with country code (e.g. +977) and pick your country instead of a state.' => 'ਭਾਰਤ ਤੋਂ ਬਾਹਰ: ਆਪਣਾ ਮੋਬਾਈਲ ਨੰਬਰ ਦੇਸ਼ ਕੋਡ ਸਮੇਤ ਦਿਓ (ਜਿਵੇਂ +977) ਅਤੇ ਰਾਜ ਦੀ ਥਾਂ ਆਪਣਾ ਦੇਸ਼ ਚੁਣੋ।',
  'Jobsence is only a platform. The candidate will double-check every job and employer abroad personally – with that country’s embassy / consulate in India, or directly with that country’s government / labour ministry, and on India’s eMigrate (emigrate.gov.in). Jobsence is not liable for any cheating or fraud.' => 'Jobsence ਸਿਰਫ਼ ਇੱਕ ਪਲੇਟਫ਼ਾਰਮ ਹੈ। ਉਮੀਦਵਾਰ ਵਿਦੇਸ਼ ਦੀ ਹਰ ਨੌਕਰੀ ਅਤੇ ਰੁਜ਼ਗਾਰਦਾਤਾ ਦੀ ਖ਼ੁਦ ਦੁਬਾਰਾ ਜਾਂਚ ਕਰੇਗਾ – ਉਸ ਦੇਸ਼ ਦੇ ਭਾਰਤ ਵਿੱਚ ਸਥਿਤ ਦੂਤਾਵਾਸ / ਕੌਂਸਲੇਟ ਤੋਂ, ਜਾਂ ਸਿੱਧਾ ਉਸ ਦੇਸ਼ ਦੀ ਸਰਕਾਰ / ਕਿਰਤ ਮੰਤਰਾਲੇ ਤੋਂ, ਅਤੇ ਭਾਰਤ ਦੇ eMigrate (emigrate.gov.in) ਉੱਤੇ। ਕਿਸੇ ਵੀ ਠੱਗੀ ਜਾਂ ਧੋਖਾਧੜੀ ਲਈ Jobsence ਜ਼ਿੰਮੇਵਾਰ ਨਹੀਂ ਹੈ।',
  'For a job in India, a foreign national must hold a valid Indian employment visa and the mandatory government clearance. The visa, work permit and clearances for any other country are solely the responsibility of the job seeker or the job giver – Jobsence has no role or responsibility in them.' => 'ਭਾਰਤ ਵਿੱਚ ਨੌਕਰੀ ਲਈ ਵਿਦੇਸ਼ੀ ਨਾਗਰਿਕ ਕੋਲ ਵੈਧ ਭਾਰਤੀ ਰੁਜ਼ਗਾਰ ਵੀਜ਼ਾ ਅਤੇ ਲਾਜ਼ਮੀ ਸਰਕਾਰੀ ਮਨਜ਼ੂਰੀ ਹੋਣੀ ਲਾਜ਼ਮੀ ਹੈ। ਕਿਸੇ ਵੀ ਹੋਰ ਦੇਸ਼ ਦਾ ਵੀਜ਼ਾ, ਵਰਕ ਪਰਮਿਟ ਅਤੇ ਮਨਜ਼ੂਰੀਆਂ ਪੂਰੀ ਤਰ੍ਹਾਂ ਨੌਕਰੀ ਲੱਭਣ ਵਾਲੇ ਜਾਂ ਨੌਕਰੀ ਦੇਣ ਵਾਲੇ ਦੀ ਜ਼ਿੰਮੇਵਾਰੀ ਹਨ – ਇਨ੍ਹਾਂ ਵਿੱਚ Jobsence ਦੀ ਕੋਈ ਭੂਮਿਕਾ ਜਾਂ ਜ਼ਿੰਮੇਵਾਰੀ ਨਹੀਂ ਹੈ।',
  'Jobs Abroad – Free Registration' => 'ਵਿਦੇਸ਼ ਵਿੱਚ ਨੌਕਰੀ – ਮੁਫ਼ਤ ਰਜਿਸਟ੍ਰੇਸ਼ਨ',
  'Looking for a job abroad? Register free' => 'ਵਿਦੇਸ਼ ਵਿੱਚ ਨੌਕਰੀ ਚਾਹੀਦੀ ਹੈ? ਮੁਫ਼ਤ ਰਜਿਸਟਰ ਕਰੋ',
  'Registration is free. For each country whose employers should see your profile, pay once: ₹1,000 + GST (₹1,180) or USD 10.' => 'ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਮੁਫ਼ਤ ਹੈ। ਜਿਸ ਵੀ ਦੇਸ਼ ਦੇ ਰੁਜ਼ਗਾਰਦਾਤਾਵਾਂ ਨੂੰ ਤੁਹਾਡੀ ਪ੍ਰੋਫ਼ਾਈਲ ਦਿਖਾਉਣੀ ਹੈ, ਉਸ ਹਰ ਦੇਸ਼ ਲਈ ਇੱਕ ਵਾਰ ਭੁਗਤਾਨ ਕਰੋ: ₹1,000 + GST (₹1,180) ਜਾਂ USD 10।',
  'Jobs you want – up to 5' => 'ਤੁਸੀਂ ਕਿਹੜੀਆਂ ਨੌਕਰੀਆਂ ਚਾਹੁੰਦੇ ਹੋ – ਵੱਧ ਤੋਂ ਵੱਧ 5',
  'Each country: one-time ₹1,180 (₹1,000 + 18% GST) or USD 10 – non-refundable in any condition.' => 'ਹਰ ਦੇਸ਼ ਲਈ: ਇੱਕ ਵਾਰ ₹1,180 (₹1,000 + 18% GST) ਜਾਂ USD 10 – ਕਿਸੇ ਵੀ ਹਾਲਤ ਵਿੱਚ ਵਾਪਸ ਨਹੀਂ ਹੋਵੇਗਾ।',
  'A valid passport is mandatory – enter its number and expiry date.' => 'ਵੈਧ ਪਾਸਪੋਰਟ ਲਾਜ਼ਮੀ ਹੈ – ਇਸਦਾ ਨੰਬਰ ਅਤੇ ਮਿਆਦ ਖ਼ਤਮ ਹੋਣ ਦੀ ਤਾਰੀਖ਼ ਭਰੋ।',
  'Jobsence is a platform, not a recruiting agent. ECR passport holders must emigrate only through agents registered on eMigrate (emigrate.gov.in), and should verify every employer there.' => 'Jobsence ਇੱਕ ਪਲੇਟਫ਼ਾਰਮ ਹੈ, ਭਰਤੀ ਏਜੰਟ ਨਹੀਂ। ECR ਪਾਸਪੋਰਟ ਵਾਲੇ ਸਿਰਫ਼ eMigrate (emigrate.gov.in) ਉੱਤੇ ਰਜਿਸਟਰਡ ਏਜੰਟਾਂ ਰਾਹੀਂ ਹੀ ਵਿਦੇਸ਼ ਜਾਣ, ਅਤੇ ਉੱਥੇ ਹਰ ਰੁਜ਼ਗਾਰਦਾਤਾ ਦੀ ਜਾਂਚ ਕਰਨ।',
  'Residence' => 'ਨਿਵਾਸ',
  'Full Name (as per passport)' => 'ਪੂਰਾ ਨਾਮ (ਪਾਸਪੋਰਟ ਅਨੁਸਾਰ)',
  'Job Abroad' => 'ਵਿਦੇਸ਼ ਵਿੱਚ ਨੌਕਰੀ',
  'Preferred countries (comma separated)' => 'ਪਸੰਦੀਦਾ ਦੇਸ਼ (ਕੌਮੇ ਨਾਲ ਵੱਖ ਕਰਕੇ)',
  'e.g. UAE, Saudi Arabia, Canada, Germany' => 'ਜਿਵੇਂ: UAE, Saudi Arabia, Canada, Germany',
  'Passport (mandatory)' => 'ਪਾਸਪੋਰਟ (ਲਾਜ਼ਮੀ)',
  'Valid passport – ECNR' => 'ਵੈਧ ਪਾਸਪੋਰਟ – ECNR',
  'Valid passport – ECR' => 'ਵੈਧ ਪਾਸਪੋਰਟ – ECR',
  'Passport number' => 'ਪਾਸਪੋਰਟ ਨੰਬਰ',
  'Stored encrypted for your safety.' => 'ਤੁਹਾਡੀ ਸੁਰੱਖਿਆ ਲਈ ਐਨਕ੍ਰਿਪਟ ਕਰਕੇ ਸੰਭਾਲਿਆ ਜਾਂਦਾ ਹੈ।',
  'Passport expiry date' => 'ਪਾਸਪੋਰਟ ਦੀ ਮਿਆਦ ਖ਼ਤਮ ਹੋਣ ਦੀ ਤਾਰੀਖ਼',
  'Expected salary (USD per month)' => 'ਉਮੀਦ ਕੀਤੀ ਤਨਖ਼ਾਹ (USD ਪ੍ਰਤੀ ਮਹੀਨਾ)',
  'Languages you know' => 'ਤੁਸੀਂ ਕਿਹੜੀਆਂ ਭਾਸ਼ਾਵਾਂ ਜਾਣਦੇ ਹੋ',
  'About you (skills, experience, certificates)' => 'ਤੁਹਾਡੇ ਬਾਰੇ (ਹੁਨਰ, ਤਜਰਬਾ, ਸਰਟੀਫ਼ਿਕੇਟ)',
  'Resume / CV (PDF/DOC, max 5MB)' => 'ਰਿਜ਼ਿਊਮੇ / CV (PDF/DOC, ਵੱਧ ਤੋਂ ਵੱਧ 5MB)',
  'Registration is free; the one-time fee of ₹1,180 or USD 10 per country is non-refundable in any condition.' => 'ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਮੁਫ਼ਤ ਹੈ; ਹਰ ਦੇਸ਼ ਲਈ ₹1,180 ਜਾਂ USD 10 ਦੀ ਇੱਕ ਵਾਰ ਦੀ ਫ਼ੀਸ ਕਿਸੇ ਵੀ ਹਾਲਤ ਵਿੱਚ ਵਾਪਸ ਨਹੀਂ ਹੋਵੇਗੀ।',
  'Jobsence is not a recruiting agent and does not guarantee any job or visa abroad. I will verify the employer and any agent on eMigrate before travelling.' => 'Jobsence ਭਰਤੀ ਏਜੰਟ ਨਹੀਂ ਹੈ ਅਤੇ ਵਿਦੇਸ਼ ਵਿੱਚ ਕਿਸੇ ਵੀ ਨੌਕਰੀ ਜਾਂ ਵੀਜ਼ੇ ਦੀ ਗਰੰਟੀ ਨਹੀਂ ਦਿੰਦਾ। ਮੈਂ ਯਾਤਰਾ ਤੋਂ ਪਹਿਲਾਂ ਰੁਜ਼ਗਾਰਦਾਤਾ ਅਤੇ ਕਿਸੇ ਵੀ ਏਜੰਟ ਦੀ ਜਾਂਚ eMigrate ਉੱਤੇ ਕਰਾਂਗਾ/ਕਰਾਂਗੀ।',
  'I will not pay anyone money for a job or visa and will report any such demand to Jobsence.' => 'ਮੈਂ ਨੌਕਰੀ ਜਾਂ ਵੀਜ਼ੇ ਲਈ ਕਿਸੇ ਨੂੰ ਵੀ ਪੈਸੇ ਨਹੀਂ ਦਿਆਂਗਾ/ਦਿਆਂਗੀ ਅਤੇ ਅਜਿਹੀ ਕਿਸੇ ਵੀ ਮੰਗ ਦੀ ਸੂਚਨਾ Jobsence ਨੂੰ ਦਿਆਂਗਾ/ਦਿਆਂਗੀ।',
  'Open “My dashboard” now and unlock the countries where your profile should be shown (₹1,180 or USD 10 each).' => 'ਹੁਣੇ “ਮੇਰਾ ਡੈਸ਼ਬੋਰਡ” ਖੋਲ੍ਹੋ ਅਤੇ ਉਹ ਦੇਸ਼ ਅਨਲੌਕ ਕਰੋ ਜਿੱਥੇ ਤੁਹਾਡੀ ਪ੍ਰੋਫ਼ਾਈਲ ਦਿਖਾਈ ਜਾਣੀ ਚਾਹੀਦੀ ਹੈ (ਹਰ ਦੇਸ਼ ₹1,180 ਜਾਂ USD 10)।',
  'Companies hiring in that country see your profile and send a tripartite agreement.' => 'ਉਸ ਦੇਸ਼ ਵਿੱਚ ਭਰਤੀ ਕਰਨ ਵਾਲੀਆਂ ਕੰਪਨੀਆਂ ਤੁਹਾਡੀ ਪ੍ਰੋਫ਼ਾਈਲ ਦੇਖਦੀਆਂ ਹਨ ਅਤੇ ਤਿੰਨ-ਧਿਰੀ ਸਮਝੌਤਾ ਭੇਜਦੀਆਂ ਹਨ।',
  'Country unlock – Jobs Abroad' => 'ਦੇਸ਼ ਅਨਲੌਕ – ਵਿਦੇਸ਼ ਵਿੱਚ ਨੌਕਰੀ',
  'Country unlock' => 'ਦੇਸ਼ ਅਨਲੌਕ',
  'Employers in this country can see your profile.' => 'ਇਸ ਦੇਸ਼ ਦੇ ਰੁਜ਼ਗਾਰਦਾਤਾ ਤੁਹਾਡੀ ਪ੍ਰੋਫ਼ਾਈਲ ਦੇਖ ਸਕਦੇ ਹਨ।',
  'Companies hiring in this country can now see your profile.' => 'ਇਸ ਦੇਸ਼ ਵਿੱਚ ਭਰਤੀ ਕਰਨ ਵਾਲੀਆਂ ਕੰਪਨੀਆਂ ਹੁਣ ਤੁਹਾਡੀ ਪ੍ਰੋਫ਼ਾਈਲ ਦੇਖ ਸਕਦੀਆਂ ਹਨ।',
  'Open your dashboard to add more countries.' => 'ਹੋਰ ਦੇਸ਼ ਜੋੜਨ ਲਈ ਆਪਣਾ ਡੈਸ਼ਬੋਰਡ ਖੋਲ੍ਹੋ।',
  'Hiring Plan' => 'ਭਰਤੀ ਪਲਾਨ',
  'Full profile, resume and agreement for 3 job seekers a day – 3 days (₹216) to 1 year (₹19,424); outside India from USD 12.' => 'ਰੋਜ਼ਾਨਾ 3 ਨੌਕਰੀ ਲੱਭਣ ਵਾਲਿਆਂ ਦੀ ਪੂਰੀ ਪ੍ਰੋਫ਼ਾਈਲ, ਰਿਜ਼ਿਊਮੇ ਅਤੇ ਸਮਝੌਤਾ – 3 ਦਿਨ (₹216) ਤੋਂ 1 ਸਾਲ (₹19,424) ਤੱਕ; ਭਾਰਤ ਤੋਂ ਬਾਹਰ USD 12 ਤੋਂ।',
  'Open candidate profiles from your dashboard and send agreements.' => 'ਆਪਣੇ ਡੈਸ਼ਬੋਰਡ ਤੋਂ ਉਮੀਦਵਾਰਾਂ ਦੀਆਂ ਪ੍ਰੋਫ਼ਾਈਲਾਂ ਖੋਲ੍ਹੋ ਅਤੇ ਸਮਝੌਤੇ ਭੇਜੋ।',
  'Mentor Plan – 30 days' => 'ਮੈਂਟਰ ਪਲਾਨ – 30 ਦਿਨ',
  'Internship Provider Plan – 10 days' => 'ਇੰਟਰਨਸ਼ਿਪ ਪ੍ਰਦਾਤਾ ਪਲਾਨ – 10 ਦਿਨ',
  'Mentor Plan' => 'ਮੈਂਟਰ ਪਲਾਨ',
  'Internship Plan' => 'ਇੰਟਰਨਸ਼ਿਪ ਪਲਾਨ',
  '₹155 (incl. GST; USD 5 outside India): full profile and agreement for 3 candidates a day for 30 days.' => '₹155 (GST ਸਮੇਤ; ਭਾਰਤ ਤੋਂ ਬਾਹਰ USD 5): 30 ਦਿਨਾਂ ਲਈ ਰੋਜ਼ਾਨਾ 3 ਉਮੀਦਵਾਰਾਂ ਦੀ ਪੂਰੀ ਪ੍ਰੋਫ਼ਾਈਲ ਅਤੇ ਸਮਝੌਤਾ।',
  '₹155 (incl. GST; USD 5 outside India): full profile for 3 candidates a day for 10 days, up to 20 in total.' => '₹155 (GST ਸਮੇਤ; ਭਾਰਤ ਤੋਂ ਬਾਹਰ USD 5): 10 ਦਿਨਾਂ ਲਈ ਰੋਜ਼ਾਨਾ 3 ਉਮੀਦਵਾਰਾਂ ਦੀ ਪੂਰੀ ਪ੍ਰੋਫ਼ਾਈਲ, ਕੁੱਲ ਵੱਧ ਤੋਂ ਵੱਧ 20।',
  'Open candidate profiles from your mentoring dashboard and send agreements.' => 'ਆਪਣੇ ਮੈਂਟਰਿੰਗ ਡੈਸ਼ਬੋਰਡ ਤੋਂ ਉਮੀਦਵਾਰਾਂ ਦੀਆਂ ਪ੍ਰੋਫ਼ਾਈਲਾਂ ਖੋਲ੍ਹੋ ਅਤੇ ਸਮਝੌਤੇ ਭੇਜੋ।',
  '5th–8th' => '5ਵੀਂ–8ਵੀਂ',
  'Graduate' => 'ਗ੍ਰੈਜੂਏਟ',
  'Post Graduate / Professional' => 'ਪੋਸਟ ਗ੍ਰੈਜੂਏਟ / ਪ੍ਰੋਫੈਸ਼ਨਲ',
  'Unemployed' => 'ਬੇਰੁਜ਼ਗਾਰ',
  'Student' => 'ਵਿਦਿਆਰਥੀ',
  'Daily wage worker' => 'ਦਿਹਾੜੀਦਾਰ ਮਜ਼ਦੂਰ',
  'Self-employed (low income)' => 'ਸਵੈ-ਰੁਜ਼ਗਾਰ (ਘੱਟ ਆਮਦਨ)',
  'Homemaker' => 'ਘਰੇਲੂ ਔਰਤ / ਗ੍ਰਹਿਣੀ',
  'Hindi' => 'ਹਿੰਦੀ',
  'English' => 'ਅੰਗਰੇਜ਼ੀ',
  'Local / Regional language' => 'ਸਥਾਨਕ / ਖੇਤਰੀ ਭਾਸ਼ਾ',
  'Mix (as per mentor availability)' => 'ਮਿਲੀ-ਜੁਲੀ (ਮੈਂਟਰ ਦੀ ਉਪਲਬਧਤਾ ਅਨੁਸਾਰ)',
  'Father’s / Mother’s / Guardian’s Name' => 'ਪਿਤਾ / ਮਾਤਾ / ਸਰਪ੍ਰਸਤ ਦਾ ਨਾਮ',
  'Date of Birth' => 'ਜਨਮ ਤਾਰੀਖ਼',
  'Gender' => 'ਲਿੰਗ',
  'Male' => 'ਪੁਰਸ਼',
  'Female' => 'ਮਹਿਲਾ',
  'Confirmation email will be sent here.' => 'ਪੁਸ਼ਟੀ ਈਮੇਲ ਇਸੇ ਪਤੇ ਉੱਤੇ ਭੇਜੀ ਜਾਵੇਗੀ।',
  'Personal Details' => 'ਨਿੱਜੀ ਵੇਰਵੇ',
  'House / Street / Landmark' => 'ਮਕਾਨ / ਗਲੀ / ਨਿਸ਼ਾਨੀ',
  'Village / Town / Locality' => 'ਪਿੰਡ / ਕਸਬਾ / ਇਲਾਕਾ',
  'Nearest Landmark / Police Station' => 'ਨੇੜਲੀ ਨਿਸ਼ਾਨੀ / ਥਾਣਾ',
  'Complete Address' => 'ਪੂਰਾ ਪਤਾ',
  'Highest Qualification' => 'ਸਭ ਤੋਂ ਉੱਚੀ ਯੋਗਤਾ',
  'Name of local language (e.g. Bhojpuri, Marathi, Tamil)' => 'ਸਥਾਨਕ ਭਾਸ਼ਾ ਦਾ ਨਾਮ (ਜਿਵੇਂ ਭੋਜਪੁਰੀ, ਮਰਾਠੀ, ਤਾਮਿਲ)',
  'Work Mode' => 'ਕੰਮ ਦਾ ਤਰੀਕਾ',
  'On-site / Office' => 'ਸਾਈਟ ਉੱਤੇ / ਦਫ਼ਤਰ',
  'Work from Home' => 'ਘਰ ਤੋਂ ਕੰਮ (ਵਰਕ ਫ੍ਰੌਮ ਹੋਮ)',
  'Preferred Working Hours' => 'ਪਸੰਦੀਦਾ ਕੰਮ ਦੇ ਘੰਟੇ',
  'Morning (6am–12pm)' => 'ਸਵੇਰ (6am–12pm)',
  'Afternoon (12–5pm)' => 'ਦੁਪਹਿਰ (12–5pm)',
  'Evening (5–10pm)' => 'ਸ਼ਾਮ (5–10pm)',
  'Night' => 'ਰਾਤ',
  'Jobsence is only a platform. We take utmost care to verify the credentials of candidates, but Jobsence will not take any responsibility for cheating, forgery or any mishappening between job seekers and job providers.' => 'Jobsence ਸਿਰਫ਼ ਇੱਕ ਪਲੇਟਫ਼ਾਰਮ ਹੈ। ਅਸੀਂ ਉਮੀਦਵਾਰਾਂ ਦੇ ਵੇਰਵਿਆਂ ਦੀ ਜਾਂਚ ਪੂਰੀ ਸਾਵਧਾਨੀ ਨਾਲ ਕਰਦੇ ਹਾਂ, ਪਰ ਨੌਕਰੀ ਲੱਭਣ ਵਾਲਿਆਂ ਅਤੇ ਨੌਕਰੀ ਦੇਣ ਵਾਲਿਆਂ ਵਿਚਕਾਰ ਕਿਸੇ ਵੀ ਠੱਗੀ, ਜਾਲਸਾਜ਼ੀ ਜਾਂ ਅਣਹੋਣੀ ਦੀ ਕੋਈ ਜ਼ਿੰਮੇਵਾਰੀ Jobsence ਨਹੀਂ ਲਵੇਗਾ।',
  'Jobsence will try to share my profile with suitable companies; matching may take time.' => 'Jobsence ਮੇਰੀ ਪ੍ਰੋਫ਼ਾਈਲ ਢੁਕਵੀਆਂ ਕੰਪਨੀਆਂ ਨਾਲ ਸਾਂਝੀ ਕਰਨ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰੇਗਾ; ਮੇਲ ਹੋਣ ਵਿੱਚ ਸਮਾਂ ਲੱਗ ਸਕਦਾ ਹੈ।',
  'I agree to be contacted by Jobsence or companies via call / WhatsApp / email.' => 'ਮੈਂ Jobsence ਜਾਂ ਕੰਪਨੀਆਂ ਵੱਲੋਂ ਕਾਲ / WhatsApp / ਈਮੇਲ ਰਾਹੀਂ ਸੰਪਰਕ ਕੀਤੇ ਜਾਣ ਲਈ ਸਹਿਮਤ ਹਾਂ।',
  'Our team will review your profile and try to share it with suitable companies.' => 'ਸਾਡੀ ਟੀਮ ਤੁਹਾਡੀ ਪ੍ਰੋਫ਼ਾਈਲ ਦੀ ਸਮੀਖਿਆ ਕਰੇਗੀ ਅਤੇ ਇਸਨੂੰ ਢੁਕਵੀਆਂ ਕੰਪਨੀਆਂ ਨਾਲ ਸਾਂਝਾ ਕਰਨ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰੇਗੀ।',
  'Skill seekers' => 'ਹੁਨਰ ਸਿੱਖਣ ਵਾਲੇ',
  'Mentors / institutes' => 'ਮੈਂਟਰ / ਸੰਸਥਾਵਾਂ',
  'Skill Mentoring' => 'ਸਕਿੱਲ ਮੈਂਟਰਿੰਗ',
  'Internship seekers' => 'ਇੰਟਰਨਸ਼ਿਪ ਲੱਭਣ ਵਾਲੇ',
  'Internship providers' => 'ਇੰਟਰਨਸ਼ਿਪ ਪ੍ਰਦਾਤਾ',
  'Internship' => 'ਇੰਟਰਨਸ਼ਿਪ',
  'Job seekers' => 'ਨੌਕਰੀ ਲੱਭਣ ਵਾਲੇ',
  'Hiring companies' => 'ਭਰਤੀ ਕਰਨ ਵਾਲੀਆਂ ਕੰਪਨੀਆਂ',
  'Job' => 'ਨੌਕਰੀ',
  'Service seekers' => 'ਸੇਵਾ ਲੱਭਣ ਵਾਲੇ',
  'Near Me providers' => 'Near Me ਸੇਵਾ ਪ੍ਰਦਾਤਾ',
  'Near Me service' => 'Near Me ਸੇਵਾ',
  'Only for Jobs Abroad registrations' => 'ਸਿਰਫ਼ ਵਿਦੇਸ਼ ਵਿੱਚ ਨੌਕਰੀ ਦੀਆਂ ਰਜਿਸਟ੍ਰੇਸ਼ਨਾਂ ਲਈ',
  'Enter a valid country other than your own country of residence' => 'ਆਪਣੇ ਰਿਹਾਇਸ਼ੀ ਦੇਸ਼ ਤੋਂ ਇਲਾਵਾ ਕੋਈ ਸਹੀ ਦੇਸ਼ ਭਰੋ',
  'This country is already unlocked' => 'ਇਹ ਦੇਸ਼ ਪਹਿਲਾਂ ਹੀ ਅਨਲੌਕ ਹੈ',
  'Server error, please retry' => 'ਸਰਵਰ ਗੜਬੜੀ, ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ',
  'This profile is not for your type of provider' => 'ਇਹ ਪ੍ਰੋਫ਼ਾਈਲ ਤੁਹਾਡੀ ਕਿਸਮ ਦੇ ਪ੍ਰਦਾਤਾ ਲਈ ਨਹੀਂ ਹੈ',
  'Your plan’s 20 profiles are used up. Get a new plan.' => 'ਤੁਹਾਡੇ ਪਲਾਨ ਦੀਆਂ 20 ਪ੍ਰੋਫ਼ਾਈਲਾਂ ਪੂਰੀਆਂ ਹੋ ਗਈਆਂ ਹਨ। ਨਵਾਂ ਪਲਾਨ ਲਓ।',
  'Today’s 3 profiles are used up – open more tomorrow.' => 'ਅੱਜ ਦੀਆਂ 3 ਪ੍ਰੋਫ਼ਾਈਲਾਂ ਪੂਰੀਆਂ ਹੋ ਗਈਆਂ ਹਨ – ਹੋਰ ਕੱਲ੍ਹ ਖੋਲ੍ਹੋ।',
  'Get a plan to open full profiles and sign agreements (mentors / internships ₹155 – USD 5 outside India, hiring from ₹216)' => 'ਪੂਰੀਆਂ ਪ੍ਰੋਫ਼ਾਈਲਾਂ ਖੋਲ੍ਹਣ ਅਤੇ ਸਮਝੌਤਿਆਂ ਉੱਤੇ ਦਸਤਖ਼ਤ ਕਰਨ ਲਈ ਪਲਾਨ ਲਓ (ਮੈਂਟਰ / ਇੰਟਰਨਸ਼ਿਪ ₹155 – ਭਾਰਤ ਤੋਂ ਬਾਹਰ USD 5, ਭਰਤੀ ₹216 ਤੋਂ)',
  'This invite is not possible' => 'ਇਹ ਸੱਦਾ ਸੰਭਵ ਨਹੀਂ ਹੈ',
  'Your verification by the Jobsence team is pending' => 'Jobsence ਟੀਮ ਵੱਲੋਂ ਤੁਹਾਡੀ ਤਸਦੀਕ ਬਾਕੀ ਹੈ',
  'You have already invited this candidate' => 'ਤੁਸੀਂ ਇਸ ਉਮੀਦਵਾਰ ਨੂੰ ਪਹਿਲਾਂ ਹੀ ਸੱਦਾ ਭੇਜ ਚੁੱਕੇ ਹੋ',
  'The candidate has been emailed to pay the form fee. Once paid, they appear in your list.' => 'ਉਮੀਦਵਾਰ ਨੂੰ ਫ਼ਾਰਮ ਫ਼ੀਸ ਭਰਨ ਲਈ ਈਮੇਲ ਭੇਜ ਦਿੱਤੀ ਗਈ ਹੈ। ਭੁਗਤਾਨ ਹੁੰਦੇ ਹੀ ਉਹ ਤੁਹਾਡੀ ਸੂਚੀ ਵਿੱਚ ਦਿਖਾਈ ਦੇਵੇਗਾ।',
  'This request is not possible' => 'ਇਹ ਬੇਨਤੀ ਸੰਭਵ ਨਹੀਂ ਹੈ',
  'Your registration is not open, or you already have a mentor' => 'ਤੁਹਾਡੀ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਖੁੱਲ੍ਹੀ ਨਹੀਂ ਹੈ, ਜਾਂ ਤੁਹਾਡੇ ਕੋਲ ਪਹਿਲਾਂ ਹੀ ਮੈਂਟਰ ਹੈ',
  'This candidate is no longer available' => 'ਇਹ ਉਮੀਦਵਾਰ ਹੁਣ ਉਪਲਬਧ ਨਹੀਂ ਹੈ',
  'This provider is not verified yet' => 'ਇਹ ਪ੍ਰਦਾਤਾ ਹਾਲੇ ਤਸਦੀਕਸ਼ੁਦਾ ਨਹੀਂ ਹੈ',
  'Customers request your service – you answer their requests' => 'ਗਾਹਕ ਤੁਹਾਡੀ ਸੇਵਾ ਲਈ ਬੇਨਤੀ ਕਰਦੇ ਹਨ – ਤੁਸੀਂ ਉਨ੍ਹਾਂ ਦੀਆਂ ਬੇਨਤੀਆਂ ਦਾ ਜਵਾਬ ਦਿੰਦੇ ਹੋ',
  'Open the candidate’s full profile first' => 'ਪਹਿਲਾਂ ਉਮੀਦਵਾਰ ਦੀ ਪੂਰੀ ਪ੍ਰੋਫ਼ਾਈਲ ਖੋਲ੍ਹੋ',
  'Agreement not available' => 'ਸਮਝੌਤਾ ਉਪਲਬਧ ਨਹੀਂ ਹੈ',
  'This agreement is no longer open' => 'ਇਹ ਸਮਝੌਤਾ ਹੁਣ ਖੁੱਲ੍ਹਾ ਨਹੀਂ ਹੈ',
  'This agreement request has expired' => 'ਇਸ ਸਮਝੌਤੇ ਦੀ ਬੇਨਤੀ ਦੀ ਮਿਆਦ ਖ਼ਤਮ ਹੋ ਗਈ ਹੈ',
  'The candidate’s registration is no longer open' => 'ਉਮੀਦਵਾਰ ਦੀ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਹੁਣ ਖੁੱਲ੍ਹੀ ਨਹੀਂ ਹੈ',
  'Your Near Me listing has expired – renew it first' => 'ਤੁਹਾਡੀ Near Me ਲਿਸਟਿੰਗ ਦੀ ਮਿਆਦ ਖ਼ਤਮ ਹੋ ਗਈ ਹੈ – ਪਹਿਲਾਂ ਇਸਨੂੰ ਰੀਨਿਊ ਕਰੋ',
  'Today’s 3 profiles are used up – sign tomorrow' => 'ਅੱਜ ਦੀਆਂ 3 ਪ੍ਰੋਫ਼ਾਈਲਾਂ ਪੂਰੀਆਂ ਹੋ ਗਈਆਂ ਹਨ – ਕੱਲ੍ਹ ਦਸਤਖ਼ਤ ਕਰੋ',
  'Agreement complete! You can now see each other’s phone and email.' => 'ਸਮਝੌਤਾ ਪੂਰਾ! ਹੁਣ ਤੁਸੀਂ ਇੱਕ-ਦੂਜੇ ਦਾ ਫ਼ੋਨ ਅਤੇ ਈਮੇਲ ਦੇਖ ਸਕਦੇ ਹੋ।',
  'You have signed. The other party has been emailed to sign.' => 'ਤੁਸੀਂ ਦਸਤਖ਼ਤ ਕਰ ਦਿੱਤੇ ਹਨ। ਦੂਜੀ ਧਿਰ ਨੂੰ ਦਸਤਖ਼ਤ ਕਰਨ ਲਈ ਈਮੇਲ ਭੇਜ ਦਿੱਤੀ ਗਈ ਹੈ।',
  'an internship' => 'ਇੱਕ ਇੰਟਰਨਸ਼ਿਪ',
  'a job / employment' => 'ਨੌਕਰੀ / ਰੁਜ਼ਗਾਰ',
  'a Near Me service' => 'ਇੱਕ Near Me ਸੇਵਾ',
  'skill training / mentoring' => 'ਹੁਨਰ ਸਿਖਲਾਈ / ਮੈਂਟਰਿੰਗ',
  '3. No guarantee – Jobsence does not guarantee any job, internship, placement, income, training result or quality of service.' => '3. ਕੋਈ ਗਰੰਟੀ ਨਹੀਂ – Jobsence ਕਿਸੇ ਵੀ ਨੌਕਰੀ, ਇੰਟਰਨਸ਼ਿਪ, ਪਲੇਸਮੈਂਟ, ਆਮਦਨ, ਸਿਖਲਾਈ ਦੇ ਨਤੀਜੇ ਜਾਂ ਸੇਵਾ ਦੀ ਗੁਣਵੱਤਾ ਦੀ ਗਰੰਟੀ ਨਹੀਂ ਦਿੰਦਾ।',
  '4. Verification – Jobsence makes reasonable efforts to check identity and documents but does not warrant their accuracy. Both parties will make their own checks before work or training starts.' => '4. ਤਸਦੀਕ – Jobsence ਪਛਾਣ ਅਤੇ ਦਸਤਾਵੇਜ਼ਾਂ ਦੀ ਜਾਂਚ ਲਈ ਵਾਜਬ ਯਤਨ ਕਰਦਾ ਹੈ, ਪਰ ਉਨ੍ਹਾਂ ਦੀ ਸ਼ੁੱਧਤਾ ਦੀ ਵਾਰੰਟੀ ਨਹੀਂ ਦਿੰਦਾ। ਕੰਮ ਜਾਂ ਸਿਖਲਾਈ ਸ਼ੁਰੂ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਦੋਵੇਂ ਧਿਰਾਂ ਆਪਣੀ ਜਾਂਚ ਖ਼ੁਦ ਕਰਨਗੀਆਂ।',
  '5. Jobsence fees – no refunds – Every amount paid to Jobsence (form fee, pass, plan, renewal or late fee) is a platform fee for access and matching only and is non-refundable in any condition – including if no match, job, internship or training results, if either party ends the agreement or rejects the provider, if a plan or pass is not used, or if access is suspended for a breach. Only a duplicate or failed payment caused by a technical error (amount debited twice, or debited without a registration being created) is returned to the original payment method. This fee is not the price of any job or training; any salary, stipend, fee or service charge between the parties is agreed between them in writing, and Jobsence is not responsible for it.' => '5. Jobsence ਦੀ ਫ਼ੀਸ – ਕੋਈ ਰਿਫ਼ੰਡ ਨਹੀਂ – Jobsence ਨੂੰ ਅਦਾ ਕੀਤੀ ਹਰ ਰਕਮ (ਫ਼ਾਰਮ ਫ਼ੀਸ, ਪਾਸ, ਪਲਾਨ, ਰੀਨਿਊਅਲ ਜਾਂ ਲੇਟ ਫ਼ੀਸ) ਸਿਰਫ਼ ਪਹੁੰਚ (ਐਕਸੈਸ) ਅਤੇ ਮੇਲ ਕਰਵਾਉਣ ਲਈ ਪਲੇਟਫ਼ਾਰਮ ਫ਼ੀਸ ਹੈ ਅਤੇ ਕਿਸੇ ਵੀ ਹਾਲਤ ਵਿੱਚ ਵਾਪਸ ਨਹੀਂ ਹੋਵੇਗੀ – ਇਸ ਵਿੱਚ ਇਹ ਹਾਲਤਾਂ ਵੀ ਸ਼ਾਮਲ ਹਨ: ਜੇ ਕੋਈ ਮੇਲ, ਨੌਕਰੀ, ਇੰਟਰਨਸ਼ਿਪ ਜਾਂ ਸਿਖਲਾਈ ਦਾ ਨਤੀਜਾ ਨਾ ਨਿਕਲੇ, ਜੇ ਕੋਈ ਵੀ ਧਿਰ ਸਮਝੌਤਾ ਖ਼ਤਮ ਕਰੇ ਜਾਂ ਪ੍ਰਦਾਤਾ ਨੂੰ ਰੱਦ ਕਰੇ, ਜੇ ਪਲਾਨ ਜਾਂ ਪਾਸ ਦੀ ਵਰਤੋਂ ਨਾ ਹੋਵੇ, ਜਾਂ ਜੇ ਉਲੰਘਣਾ ਕਾਰਨ ਪਹੁੰਚ ਮੁਅੱਤਲ ਕੀਤੀ ਜਾਵੇ। ਸਿਰਫ਼ ਤਕਨੀਕੀ ਗੜਬੜੀ ਕਾਰਨ ਹੋਇਆ ਦੋਹਰਾ ਜਾਂ ਅਸਫਲ ਭੁਗਤਾਨ (ਰਕਮ ਦੋ ਵਾਰ ਕੱਟੀ ਜਾਣੀ, ਜਾਂ ਰਕਮ ਕੱਟੀ ਜਾਣ ਦੇ ਬਾਵਜੂਦ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਨਾ ਬਣਨੀ) ਮੂਲ ਭੁਗਤਾਨ ਮਾਧਿਅਮ ਵਿੱਚ ਵਾਪਸ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। ਇਹ ਫ਼ੀਸ ਕਿਸੇ ਨੌਕਰੀ ਜਾਂ ਸਿਖਲਾਈ ਦੀ ਕੀਮਤ ਨਹੀਂ ਹੈ; ਧਿਰਾਂ ਵਿਚਕਾਰ ਕੋਈ ਵੀ ਤਨਖ਼ਾਹ, ਵਜ਼ੀਫ਼ਾ (ਸਟਾਈਪੈਂਡ), ਫ਼ੀਸ ਜਾਂ ਸੇਵਾ ਖ਼ਰਚਾ ਉਨ੍ਹਾਂ ਵਿਚਕਾਰ ਲਿਖਤੀ ਰੂਪ ਵਿੱਚ ਤੈਅ ਹੁੰਦਾ ਹੈ, ਅਤੇ ਇਸ ਲਈ Jobsence ਜ਼ਿੰਮੇਵਾਰ ਨਹੀਂ ਹੈ।',
  '6. No unlawful charges – The Provider will not ask the Candidate for any money, security deposit or original documents in return for a job or internship, and will not charge more than what is agreed in writing. Report any such demand to Jobsence at once.' => '6. ਕੋਈ ਗ਼ੈਰ-ਕਾਨੂੰਨੀ ਵਸੂਲੀ ਨਹੀਂ – ਪ੍ਰਦਾਤਾ ਨੌਕਰੀ ਜਾਂ ਇੰਟਰਨਸ਼ਿਪ ਦੇ ਬਦਲੇ ਉਮੀਦਵਾਰ ਤੋਂ ਕੋਈ ਪੈਸਾ, ਸਕਿਉਰਿਟੀ ਡਿਪਾਜ਼ਿਟ ਜਾਂ ਅਸਲ ਦਸਤਾਵੇਜ਼ ਨਹੀਂ ਮੰਗੇਗਾ, ਅਤੇ ਲਿਖਤੀ ਰੂਪ ਵਿੱਚ ਤੈਅ ਰਕਮ ਤੋਂ ਵੱਧ ਨਹੀਂ ਲਵੇਗਾ। ਅਜਿਹੀ ਕਿਸੇ ਵੀ ਮੰਗ ਦੀ ਸੂਚਨਾ ਤੁਰੰਤ Jobsence ਨੂੰ ਦਿਓ।',
  '7. Personal data – Each party will use the other’s details (phone, email, address, resume) only for this purpose, keep them confidential, never share or sell them, and delete them when no longer needed, in line with the Digital Personal Data Protection Act, 2023. Both parties consent to Jobsence processing their data to provide the service and to keep a record of this agreement.' => '7. ਨਿੱਜੀ ਡਾਟਾ – ਹਰ ਧਿਰ ਦੂਜੀ ਧਿਰ ਦੇ ਵੇਰਵਿਆਂ (ਫ਼ੋਨ, ਈਮੇਲ, ਪਤਾ, ਰਿਜ਼ਿਊਮੇ) ਦੀ ਵਰਤੋਂ ਸਿਰਫ਼ ਇਸੇ ਮਕਸਦ ਲਈ ਕਰੇਗੀ, ਉਨ੍ਹਾਂ ਨੂੰ ਗੁਪਤ ਰੱਖੇਗੀ, ਕਦੇ ਵੀ ਸਾਂਝਾ ਜਾਂ ਵੇਚੇਗੀ ਨਹੀਂ, ਅਤੇ ਲੋੜ ਨਾ ਰਹਿਣ ਉੱਤੇ ਉਨ੍ਹਾਂ ਨੂੰ ਮਿਟਾ ਦੇਵੇਗੀ, ਡਿਜੀਟਲ ਨਿੱਜੀ ਡਾਟਾ ਸੁਰੱਖਿਆ ਐਕਟ, 2023 ਦੇ ਅਨੁਸਾਰ। ਦੋਵੇਂ ਧਿਰਾਂ ਸੇਵਾ ਪ੍ਰਦਾਨ ਕਰਨ ਅਤੇ ਇਸ ਸਮਝੌਤੇ ਦਾ ਰਿਕਾਰਡ ਰੱਖਣ ਲਈ Jobsence ਵੱਲੋਂ ਆਪਣੇ ਡਾਟਾ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਲਈ ਸਹਿਮਤੀ ਦਿੰਦੀਆਂ ਹਨ।',
  '8. Fair use of the platform – The Provider will not copy, scrape, bulk-download or reuse candidate information from Jobsence for any other purpose, and will not share its login or links. Breach leads to suspension without refund and, where needed, a report to the authorities.' => '8. ਪਲੇਟਫ਼ਾਰਮ ਦੀ ਸਹੀ ਵਰਤੋਂ – ਪ੍ਰਦਾਤਾ Jobsence ਤੋਂ ਮਿਲੀ ਉਮੀਦਵਾਰਾਂ ਦੀ ਜਾਣਕਾਰੀ ਦੀ ਨਕਲ, ਸਕ੍ਰੈਪਿੰਗ, ਬਲਕ-ਡਾਊਨਲੋਡ ਜਾਂ ਕਿਸੇ ਹੋਰ ਮਕਸਦ ਲਈ ਮੁੜ-ਵਰਤੋਂ ਨਹੀਂ ਕਰੇਗਾ, ਅਤੇ ਆਪਣਾ ਲੌਗਇਨ ਜਾਂ ਲਿੰਕ ਸਾਂਝੇ ਨਹੀਂ ਕਰੇਗਾ। ਉਲੰਘਣਾ ਹੋਣ ਉੱਤੇ ਬਿਨਾਂ ਰਿਫ਼ੰਡ ਮੁਅੱਤਲੀ ਹੋਵੇਗੀ ਅਤੇ, ਜਿੱਥੇ ਲੋੜ ਹੋਵੇ, ਅਧਿਕਾਰੀਆਂ ਨੂੰ ਸੂਚਨਾ ਦਿੱਤੀ ਜਾਵੇਗੀ।',
  '9. Conduct and safety – Both parties will behave respectfully, lawfully and without discrimination; no harassment. Where applicable, the Sexual Harassment of Women at Workplace Act, 2013 will be followed. First meetings should be at official or public places. A candidate under 18 needs parent / guardian consent, and child labour laws will be followed.' => '9. ਵਿਹਾਰ ਅਤੇ ਸੁਰੱਖਿਆ – ਦੋਵੇਂ ਧਿਰਾਂ ਸਤਿਕਾਰ ਨਾਲ, ਕਾਨੂੰਨ ਅਨੁਸਾਰ ਅਤੇ ਬਿਨਾਂ ਭੇਦਭਾਵ ਦੇ ਵਿਹਾਰ ਕਰਨਗੀਆਂ; ਕੋਈ ਪਰੇਸ਼ਾਨੀ (ਉਤਪੀੜਨ) ਨਹੀਂ ਹੋਵੇਗੀ। ਜਿੱਥੇ ਲਾਗੂ ਹੋਵੇ, ਕੰਮ ਵਾਲੀ ਥਾਂ ਉੱਤੇ ਔਰਤਾਂ ਦਾ ਜਿਨਸੀ ਉਤਪੀੜਨ ਐਕਟ, 2013 ਦੀ ਪਾਲਣਾ ਕੀਤੀ ਜਾਵੇਗੀ। ਪਹਿਲੀਆਂ ਮੁਲਾਕਾਤਾਂ ਦਫ਼ਤਰੀ ਜਾਂ ਜਨਤਕ ਥਾਵਾਂ ਉੱਤੇ ਹੋਣੀਆਂ ਚਾਹੀਦੀਆਂ ਹਨ। 18 ਸਾਲ ਤੋਂ ਘੱਟ ਉਮਰ ਦੇ ਉਮੀਦਵਾਰ ਲਈ ਮਾਤਾ-ਪਿਤਾ / ਸਰਪ੍ਰਸਤ ਦੀ ਸਹਿਮਤੀ ਲੋੜੀਂਦੀ ਹੈ, ਅਤੇ ਬਾਲ ਮਜ਼ਦੂਰੀ ਕਾਨੂੰਨਾਂ ਦੀ ਪਾਲਣਾ ਕੀਤੀ ਜਾਵੇਗੀ।',
  '10. Provider’s legal duties – Compliance with all laws for this work, training or service (labour, minimum wages, stipend, tax, licences, professional registrations, safety) is solely the Provider’s responsibility.' => '10. ਪ੍ਰਦਾਤਾ ਦੀਆਂ ਕਾਨੂੰਨੀ ਜ਼ਿੰਮੇਵਾਰੀਆਂ – ਇਸ ਕੰਮ, ਸਿਖਲਾਈ ਜਾਂ ਸੇਵਾ ਲਈ ਸਾਰੇ ਕਾਨੂੰਨਾਂ (ਕਿਰਤ, ਘੱਟੋ-ਘੱਟ ਉਜਰਤ, ਸਟਾਈਪੈਂਡ, ਟੈਕਸ, ਲਾਇਸੰਸ, ਪੇਸ਼ੇਵਰ ਰਜਿਸਟ੍ਰੇਸ਼ਨਾਂ, ਸੁਰੱਖਿਆ) ਦੀ ਪਾਲਣਾ ਸਿਰਫ਼ ਪ੍ਰਦਾਤਾ ਦੀ ਜ਼ਿੰਮੇਵਾਰੀ ਹੈ।',
  '11. Candidate’s duties – The Candidate has given true information, will attend as agreed, will follow the Provider’s reasonable rules, and will inform the Provider and Jobsence before leaving.' => '11. ਉਮੀਦਵਾਰ ਦੀਆਂ ਜ਼ਿੰਮੇਵਾਰੀਆਂ – ਉਮੀਦਵਾਰ ਨੇ ਸੱਚੀ ਜਾਣਕਾਰੀ ਦਿੱਤੀ ਹੈ, ਤੈਅ ਅਨੁਸਾਰ ਹਾਜ਼ਰ ਰਹੇਗਾ, ਪ੍ਰਦਾਤਾ ਦੇ ਵਾਜਬ ਨਿਯਮਾਂ ਦੀ ਪਾਲਣਾ ਕਰੇਗਾ, ਅਤੇ ਛੱਡਣ ਤੋਂ ਪਹਿਲਾਂ ਪ੍ਰਦਾਤਾ ਅਤੇ Jobsence ਨੂੰ ਸੂਚਿਤ ਕਰੇਗਾ।',
  '12. Ending the agreement – Either party may end this agreement from the Jobsence dashboard. If the Candidate rejects the Provider after signing, the Candidate’s registration closes and a fresh form fee is payable; if the Provider ends it, the Candidate stays eligible. Jobsence may suspend or end any party’s access without refund for breach, fraud or serious complaints.' => '12. ਸਮਝੌਤਾ ਖ਼ਤਮ ਕਰਨਾ – ਕੋਈ ਵੀ ਧਿਰ Jobsence ਡੈਸ਼ਬੋਰਡ ਤੋਂ ਇਹ ਸਮਝੌਤਾ ਖ਼ਤਮ ਕਰ ਸਕਦੀ ਹੈ। ਜੇ ਉਮੀਦਵਾਰ ਦਸਤਖ਼ਤ ਕਰਨ ਤੋਂ ਬਾਅਦ ਪ੍ਰਦਾਤਾ ਨੂੰ ਰੱਦ ਕਰਦਾ ਹੈ, ਤਾਂ ਉਮੀਦਵਾਰ ਦੀ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਬੰਦ ਹੋ ਜਾਂਦੀ ਹੈ ਅਤੇ ਨਵੀਂ ਫ਼ਾਰਮ ਫ਼ੀਸ ਭਰਨੀ ਪਵੇਗੀ; ਜੇ ਪ੍ਰਦਾਤਾ ਇਸਨੂੰ ਖ਼ਤਮ ਕਰਦਾ ਹੈ, ਤਾਂ ਉਮੀਦਵਾਰ ਯੋਗ ਬਣਿਆ ਰਹਿੰਦਾ ਹੈ। ਉਲੰਘਣਾ, ਧੋਖਾਧੜੀ ਜਾਂ ਗੰਭੀਰ ਸ਼ਿਕਾਇਤਾਂ ਹੋਣ ਉੱਤੇ Jobsence ਕਿਸੇ ਵੀ ਧਿਰ ਦੀ ਪਹੁੰਚ ਬਿਨਾਂ ਰਿਫ਼ੰਡ ਮੁਅੱਤਲ ਜਾਂ ਖ਼ਤਮ ਕਰ ਸਕਦਾ ਹੈ।',
  '13. Limitation of liability – To the extent permitted by law, Jobsence is not liable for any act, omission, fraud, forgery, injury, loss or damage caused by either party. Jobsence’s total liability under this agreement will not exceed the platform fee the claiming party paid to Jobsence for this registration.' => '13. ਦੇਣਦਾਰੀ ਦੀ ਸੀਮਾ – ਕਾਨੂੰਨ ਵੱਲੋਂ ਮਨਜ਼ੂਰ ਹੱਦ ਤੱਕ, ਕਿਸੇ ਵੀ ਧਿਰ ਵੱਲੋਂ ਕੀਤੇ ਕਿਸੇ ਕੰਮ, ਭੁੱਲ-ਚੂਕ, ਧੋਖਾਧੜੀ, ਜਾਲਸਾਜ਼ੀ, ਸੱਟ, ਘਾਟੇ ਜਾਂ ਨੁਕਸਾਨ ਲਈ Jobsence ਜ਼ਿੰਮੇਵਾਰ ਨਹੀਂ ਹੈ। ਇਸ ਸਮਝੌਤੇ ਅਧੀਨ Jobsence ਦੀ ਕੁੱਲ ਦੇਣਦਾਰੀ ਉਸ ਪਲੇਟਫ਼ਾਰਮ ਫ਼ੀਸ ਤੋਂ ਵੱਧ ਨਹੀਂ ਹੋਵੇਗੀ ਜੋ ਦਾਅਵਾ ਕਰਨ ਵਾਲੀ ਧਿਰ ਨੇ ਇਸ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਲਈ Jobsence ਨੂੰ ਅਦਾ ਕੀਤੀ ਸੀ।',
  '14. Indemnity – The Candidate and the Provider will each make good any claim, loss or penalty against Jobsence arising from their own breach, unlawful act or false information.' => '14. ਹਰਜਾਨਾ ਭਰਪਾਈ – ਉਮੀਦਵਾਰ ਅਤੇ ਪ੍ਰਦਾਤਾ ਦੋਵੇਂ ਆਪਣੀ-ਆਪਣੀ ਉਲੰਘਣਾ, ਗ਼ੈਰ-ਕਾਨੂੰਨੀ ਕੰਮ ਜਾਂ ਗ਼ਲਤ ਜਾਣਕਾਰੀ ਕਾਰਨ Jobsence ਵਿਰੁੱਧ ਹੋਣ ਵਾਲੇ ਕਿਸੇ ਵੀ ਦਾਅਵੇ, ਘਾਟੇ ਜਾਂ ਜੁਰਮਾਨੇ ਦੀ ਭਰਪਾਈ ਕਰਨਗੇ।',
  '16. Disputes and law – This agreement is governed by Indian law. The parties will first try to settle any dispute through the Jobsence grievance process for 30 days. If unresolved, a dispute involving Jobsence will go to a sole arbitrator appointed by agreement of the parties or under the Arbitration and Conciliation Act, 1996; the seat of arbitration is New Delhi. Subject to this, courts at New Delhi have jurisdiction. Rights that cannot be excluded by law (such as consumer rights) are not affected.' => '16. ਵਿਵਾਦ ਅਤੇ ਕਾਨੂੰਨ – ਇਹ ਸਮਝੌਤਾ ਭਾਰਤੀ ਕਾਨੂੰਨ ਅਧੀਨ ਹੈ। ਧਿਰਾਂ ਪਹਿਲਾਂ 30 ਦਿਨਾਂ ਤੱਕ Jobsence ਦੀ ਸ਼ਿਕਾਇਤ ਨਿਵਾਰਨ ਪ੍ਰਕਿਰਿਆ ਰਾਹੀਂ ਕਿਸੇ ਵੀ ਵਿਵਾਦ ਨੂੰ ਸੁਲਝਾਉਣ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰਨਗੀਆਂ। ਜੇ ਹੱਲ ਨਾ ਹੋਵੇ, ਤਾਂ Jobsence ਨਾਲ ਸਬੰਧਤ ਵਿਵਾਦ ਇੱਕ ਇਕੱਲੇ ਸਾਲਸ (ਆਰਬਿਟਰੇਟਰ) ਕੋਲ ਜਾਵੇਗਾ, ਜੋ ਧਿਰਾਂ ਦੀ ਸਹਿਮਤੀ ਨਾਲ ਜਾਂ ਸਾਲਸੀ ਅਤੇ ਸੁਲ੍ਹਾ ਐਕਟ, 1996 ਅਧੀਨ ਨਿਯੁਕਤ ਕੀਤਾ ਜਾਵੇਗਾ; ਸਾਲਸੀ ਦਾ ਸਥਾਨ ਨਵੀਂ ਦਿੱਲੀ ਹੈ। ਇਸਦੇ ਅਧੀਨ ਰਹਿੰਦਿਆਂ, ਨਵੀਂ ਦਿੱਲੀ ਦੀਆਂ ਅਦਾਲਤਾਂ ਨੂੰ ਅਧਿਕਾਰ-ਖੇਤਰ ਹੈ। ਜਿਹੜੇ ਅਧਿਕਾਰ ਕਾਨੂੰਨ ਅਨੁਸਾਰ ਬਾਹਰ ਨਹੀਂ ਕੀਤੇ ਜਾ ਸਕਦੇ (ਜਿਵੇਂ ਖਪਤਕਾਰ ਅਧਿਕਾਰ), ਉਹ ਪ੍ਰਭਾਵਿਤ ਨਹੀਂ ਹੁੰਦੇ।',
  '17. Electronic signature – This agreement, signed with an email OTP, is a valid electronic contract under Section 10A of the Information Technology Act, 2000. Jobsence countersigns automatically once both have signed and keeps the signing time, IP address and version as evidence.' => '17. ਇਲੈਕਟ੍ਰਾਨਿਕ ਦਸਤਖ਼ਤ – ਈਮੇਲ OTP ਨਾਲ ਦਸਤਖ਼ਤ ਕੀਤਾ ਇਹ ਸਮਝੌਤਾ ਸੂਚਨਾ ਤਕਨਾਲੋਜੀ ਐਕਟ, 2000 ਦੀ ਧਾਰਾ 10A ਅਧੀਨ ਇੱਕ ਵੈਧ ਇਲੈਕਟ੍ਰਾਨਿਕ ਇਕਰਾਰਨਾਮਾ ਹੈ। ਦੋਵਾਂ ਦੇ ਦਸਤਖ਼ਤ ਹੋਣ ਉੱਤੇ Jobsence ਆਪਣੇ-ਆਪ ਜਵਾਬੀ ਦਸਤਖ਼ਤ ਕਰਦਾ ਹੈ ਅਤੇ ਦਸਤਖ਼ਤ ਦਾ ਸਮਾਂ, IP ਪਤਾ ਅਤੇ ਸੰਸਕਰਣ ਸਬੂਤ ਵਜੋਂ ਸੰਭਾਲ ਕੇ ਰੱਖਦਾ ਹੈ।',
  '18. Entire agreement – This agreement, the Jobsence Terms of Use and the Privacy Policy together form the whole agreement for this connection. Jobsence may change the terms for future agreements; the version you signed applies to you. This is not a Government of India scheme.' => '18. ਸੰਪੂਰਨ ਸਮਝੌਤਾ – ਇਹ ਸਮਝੌਤਾ, Jobsence ਦੀਆਂ ਵਰਤੋਂ ਦੀਆਂ ਸ਼ਰਤਾਂ ਅਤੇ ਪਰਦੇਦਾਰੀ ਨੀਤੀ ਮਿਲ ਕੇ ਇਸ ਸੰਪਰਕ ਲਈ ਪੂਰਾ ਸਮਝੌਤਾ ਬਣਾਉਂਦੇ ਹਨ। Jobsence ਭਵਿੱਖ ਦੇ ਸਮਝੌਤਿਆਂ ਲਈ ਸ਼ਰਤਾਂ ਬਦਲ ਸਕਦਾ ਹੈ; ਤੁਹਾਡੇ ਉੱਤੇ ਉਹੀ ਸੰਸਕਰਣ ਲਾਗੂ ਹੁੰਦਾ ਹੈ ਜਿਸ ਉੱਤੇ ਤੁਸੀਂ ਦਸਤਖ਼ਤ ਕੀਤੇ ਹਨ। ਇਹ ਭਾਰਤ ਸਰਕਾਰ ਦੀ ਯੋਜਨਾ ਨਹੀਂ ਹੈ।',
  '19. Training content – Training material belongs to the Provider / Jobsence; the Candidate will not record or share sessions without permission. Demo videos submitted by mentors are Jobsence property. Mentor emolument is per the Jobsence mentor terms, after successful training.' => '19. ਸਿਖਲਾਈ ਸਮੱਗਰੀ – ਸਿਖਲਾਈ ਸਮੱਗਰੀ ਪ੍ਰਦਾਤਾ / Jobsence ਦੀ ਹੈ; ਉਮੀਦਵਾਰ ਇਜਾਜ਼ਤ ਤੋਂ ਬਿਨਾਂ ਸੈਸ਼ਨ ਰਿਕਾਰਡ ਜਾਂ ਸਾਂਝੇ ਨਹੀਂ ਕਰੇਗਾ। ਮੈਂਟਰਾਂ ਵੱਲੋਂ ਜਮ੍ਹਾਂ ਕਰਵਾਈਆਂ ਡੈਮੋ ਵੀਡੀਓਜ਼ Jobsence ਦੀ ਸੰਪਤੀ ਹਨ। ਮੈਂਟਰ ਦਾ ਮਾਣ-ਭੱਤਾ ਸਫਲ ਸਿਖਲਾਈ ਤੋਂ ਬਾਅਦ, Jobsence ਦੀਆਂ ਮੈਂਟਰ ਸ਼ਰਤਾਂ ਅਨੁਸਾਰ ਹੋਵੇਗਾ।',
  '19. Internship – A paid internship’s stipend will be between ₹8,000 and ₹5,00,000 a month as declared; work, duration and certificate will be agreed in writing. No fee will be taken from the intern for the internship.' => '19. ਇੰਟਰਨਸ਼ਿਪ – ਪੇਡ ਇੰਟਰਨਸ਼ਿਪ ਦਾ ਸਟਾਈਪੈਂਡ, ਜਿਵੇਂ ਐਲਾਨਿਆ ਗਿਆ ਹੈ, ₹8,000 ਤੋਂ ₹5,00,000 ਪ੍ਰਤੀ ਮਹੀਨਾ ਦੇ ਵਿਚਕਾਰ ਹੋਵੇਗਾ; ਕੰਮ, ਮਿਆਦ ਅਤੇ ਸਰਟੀਫ਼ਿਕੇਟ ਲਿਖਤੀ ਰੂਪ ਵਿੱਚ ਤੈਅ ਕੀਤੇ ਜਾਣਗੇ। ਇੰਟਰਨਸ਼ਿਪ ਲਈ ਇੰਟਰਨ ਤੋਂ ਕੋਈ ਫ਼ੀਸ ਨਹੀਂ ਲਈ ਜਾਵੇਗੀ।',
  '19. Job – The Provider confirms the vacancy is genuine and lawful, the pay is not below the applicable minimum wage, and the appointment letter / terms will be given in writing.' => '19. ਨੌਕਰੀ – ਪ੍ਰਦਾਤਾ ਪੁਸ਼ਟੀ ਕਰਦਾ ਹੈ ਕਿ ਅਸਾਮੀ ਅਸਲੀ ਅਤੇ ਕਾਨੂੰਨੀ ਹੈ, ਤਨਖ਼ਾਹ ਲਾਗੂ ਘੱਟੋ-ਘੱਟ ਉਜਰਤ ਤੋਂ ਘੱਟ ਨਹੀਂ ਹੈ, ਅਤੇ ਨਿਯੁਕਤੀ ਪੱਤਰ / ਸ਼ਰਤਾਂ ਲਿਖਤੀ ਰੂਪ ਵਿੱਚ ਦਿੱਤੀਆਂ ਜਾਣਗੀਆਂ।',
  '19. Service – Scope, price, materials and timing are agreed before work starts; the Customer pays the Provider directly; workmanship and safety are the Provider’s responsibility. Jobsence is not a party to the service contract itself.' => '19. ਸੇਵਾ – ਕੰਮ ਦਾ ਦਾਇਰਾ, ਕੀਮਤ, ਸਮਾਨ ਅਤੇ ਸਮਾਂ ਕੰਮ ਸ਼ੁਰੂ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਤੈਅ ਕੀਤੇ ਜਾਂਦੇ ਹਨ; ਗਾਹਕ ਪ੍ਰਦਾਤਾ ਨੂੰ ਸਿੱਧਾ ਭੁਗਤਾਨ ਕਰਦਾ ਹੈ; ਕਾਰੀਗਰੀ ਅਤੇ ਸੁਰੱਖਿਆ ਪ੍ਰਦਾਤਾ ਦੀ ਜ਼ਿੰਮੇਵਾਰੀ ਹੈ। Jobsence ਸੇਵਾ ਇਕਰਾਰਨਾਮੇ ਦੀ ਆਪਣੇ-ਆਪ ਵਿੱਚ ਧਿਰ ਨਹੀਂ ਹੈ।',
  'Jobsence is only a platform and facilitator; Jobsence does not guarantee any job, placement or outcome.' => 'Jobsence ਸਿਰਫ਼ ਇੱਕ ਪਲੇਟਫ਼ਾਰਮ ਅਤੇ ਸਹੂਲਤ ਦੇਣ ਵਾਲਾ ਹੈ; Jobsence ਕਿਸੇ ਵੀ ਨੌਕਰੀ, ਪਲੇਸਮੈਂਟ ਜਾਂ ਨਤੀਜੇ ਦੀ ਗਰੰਟੀ ਨਹੀਂ ਦਿੰਦਾ।',
  'Both parties will use each other’s phone number and email only for this purpose and will not share them with anyone else.' => 'ਦੋਵੇਂ ਧਿਰਾਂ ਇੱਕ-ਦੂਜੇ ਦਾ ਫ਼ੋਨ ਨੰਬਰ ਅਤੇ ਈਮੇਲ ਸਿਰਫ਼ ਇਸੇ ਮਕਸਦ ਲਈ ਵਰਤਣਗੀਆਂ ਅਤੇ ਕਿਸੇ ਹੋਰ ਨਾਲ ਸਾਂਝੇ ਨਹੀਂ ਕਰਨਗੀਆਂ।',
  'The provider will not ask the candidate for any extra fee without Jobsence’s knowledge; all fees and payments will be agreed in writing.' => 'ਪ੍ਰਦਾਤਾ Jobsence ਦੀ ਜਾਣਕਾਰੀ ਤੋਂ ਬਿਨਾਂ ਉਮੀਦਵਾਰ ਤੋਂ ਕੋਈ ਵਾਧੂ ਫ਼ੀਸ ਨਹੀਂ ਮੰਗੇਗਾ; ਸਾਰੀਆਂ ਫ਼ੀਸਾਂ ਅਤੇ ਭੁਗਤਾਨ ਲਿਖਤੀ ਰੂਪ ਵਿੱਚ ਤੈਅ ਕੀਤੇ ਜਾਣਗੇ।',
  'Both parties will behave respectfully and safely; any complaint can be sent to gm@jobsence.com.' => 'ਦੋਵੇਂ ਧਿਰਾਂ ਸਤਿਕਾਰ ਅਤੇ ਸੁਰੱਖਿਆ ਨਾਲ ਵਿਹਾਰ ਕਰਨਗੀਆਂ; ਕੋਈ ਵੀ ਸ਼ਿਕਾਇਤ gm@jobsence.com ਉੱਤੇ ਭੇਜੀ ਜਾ ਸਕਦੀ ਹੈ।',
  'If the candidate rejects the provider after this agreement, the candidate’s registration closes and a new form fee is payable. If the provider ends the agreement, the candidate’s registration stays open.' => 'ਜੇ ਉਮੀਦਵਾਰ ਇਸ ਸਮਝੌਤੇ ਤੋਂ ਬਾਅਦ ਪ੍ਰਦਾਤਾ ਨੂੰ ਰੱਦ ਕਰਦਾ ਹੈ, ਤਾਂ ਉਮੀਦਵਾਰ ਦੀ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਬੰਦ ਹੋ ਜਾਂਦੀ ਹੈ ਅਤੇ ਨਵੀਂ ਫ਼ਾਰਮ ਫ਼ੀਸ ਭਰਨੀ ਪਵੇਗੀ। ਜੇ ਪ੍ਰਦਾਤਾ ਸਮਝੌਤਾ ਖ਼ਤਮ ਕਰਦਾ ਹੈ, ਤਾਂ ਉਮੀਦਵਾਰ ਦੀ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਖੁੱਲ੍ਹੀ ਰਹਿੰਦੀ ਹੈ।',
  'All fees are non-refundable. This is not a Government of India scheme.' => 'ਸਾਰੀਆਂ ਫ਼ੀਸਾਂ ਵਾਪਸ ਨਹੀਂ ਹੋਣਗੀਆਂ। ਇਹ ਭਾਰਤ ਸਰਕਾਰ ਦੀ ਯੋਜਨਾ ਨਹੀਂ ਹੈ।',
  'The candidate and the provider sign with an OTP sent to their email; Jobsence countersigns automatically when both have signed. Signing time and IP are recorded.' => 'ਉਮੀਦਵਾਰ ਅਤੇ ਪ੍ਰਦਾਤਾ ਆਪਣੀ ਈਮੇਲ ਉੱਤੇ ਭੇਜੇ OTP ਨਾਲ ਦਸਤਖ਼ਤ ਕਰਦੇ ਹਨ; ਦੋਵਾਂ ਦੇ ਦਸਤਖ਼ਤ ਹੋਣ ਉੱਤੇ Jobsence ਆਪਣੇ-ਆਪ ਜਵਾਬੀ ਦਸਤਖ਼ਤ ਕਰਦਾ ਹੈ। ਦਸਤਖ਼ਤ ਦਾ ਸਮਾਂ ਅਤੇ IP ਰਿਕਾਰਡ ਕੀਤੇ ਜਾਂਦੇ ਹਨ।',
  'Skill mentoring' => 'ਸਕਿੱਲ ਮੈਂਟਰਿੰਗ',
  ' (incl. GST)' => ' (GST ਸਮੇਤ)',
  'The mentor we requested is not available right now.' => 'ਜਿਸ ਮੈਂਟਰ ਲਈ ਅਸੀਂ ਬੇਨਤੀ ਕੀਤੀ ਸੀ, ਉਹ ਇਸ ਵੇਲੇ ਉਪਲਬਧ ਨਹੀਂ ਹੈ।',
  'The mentor we requested did not reply in time.' => 'ਜਿਸ ਮੈਂਟਰ ਲਈ ਅਸੀਂ ਬੇਨਤੀ ਕੀਤੀ ਸੀ, ਉਸਨੇ ਸਮੇਂ ਸਿਰ ਜਵਾਬ ਨਹੀਂ ਦਿੱਤਾ।',
  'We could not automatically match a mentor for your chosen skills yet.' => 'ਅਸੀਂ ਹਾਲੇ ਤੁਹਾਡੇ ਚੁਣੇ ਹੁਨਰਾਂ ਲਈ ਆਪਣੇ-ਆਪ ਕੋਈ ਮੈਂਟਰ ਨਹੀਂ ਲੱਭ ਸਕੇ।',
  'Your organisation is verified ✓' => 'ਤੁਹਾਡੀ ਸੰਸਥਾ ਦੀ ਤਸਦੀਕ ਹੋ ਗਈ ਹੈ ✓',
  'You can now connect with social service people on Jobsence.' => 'ਹੁਣ ਤੁਸੀਂ Jobsence ਉੱਤੇ ਸਮਾਜ ਸੇਵਾ ਵਾਲੇ ਲੋਕਾਂ ਨਾਲ ਜੁੜ ਸਕਦੇ ਹੋ।',
  'You have been added to the Jobsence Mentor Team ✓' => 'ਤੁਹਾਨੂੰ Jobsence ਮੈਂਟਰ ਟੀਮ ਵਿੱਚ ਸ਼ਾਮਲ ਕਰ ਲਿਆ ਗਿਆ ਹੈ ✓',
  'When a candidate needs you, you will get an email to accept or decline.' => 'ਜਦੋਂ ਕਿਸੇ ਉਮੀਦਵਾਰ ਨੂੰ ਤੁਹਾਡੀ ਲੋੜ ਹੋਵੇਗੀ, ਤੁਹਾਨੂੰ ਸਵੀਕਾਰ ਜਾਂ ਇਨਕਾਰ ਕਰਨ ਲਈ ਈਮੇਲ ਮਿਲੇਗੀ।',
  'You have been selected ✓' => 'ਤੁਹਾਡੀ ਚੋਣ ਹੋ ਗਈ ਹੈ ✓',
  'We are now matching you with a mentor for your chosen skills.' => 'ਅਸੀਂ ਹੁਣ ਤੁਹਾਡੇ ਚੁਣੇ ਹੁਨਰਾਂ ਲਈ ਤੁਹਾਡਾ ਮੇਲ ਕਿਸੇ ਮੈਂਟਰ ਨਾਲ ਕਰ ਰਹੇ ਹਾਂ।',
  'This Email is already registered with another company' => 'ਇਹ ਈਮੇਲ ਪਹਿਲਾਂ ਹੀ ਕਿਸੇ ਹੋਰ ਕੰਪਨੀ ਨਾਲ ਰਜਿਸਟਰਡ ਹੈ',
  'This Mobile number is already registered' => 'ਇਹ ਮੋਬਾਈਲ ਨੰਬਰ ਪਹਿਲਾਂ ਹੀ ਰਜਿਸਟਰਡ ਹੈ',
  'This GST number is already registered' => 'ਇਹ GST ਨੰਬਰ ਪਹਿਲਾਂ ਹੀ ਰਜਿਸਟਰਡ ਹੈ',
  'This field is required' => 'ਇਹ ਖ਼ਾਨਾ ਭਰਨਾ ਲਾਜ਼ਮੀ ਹੈ',
  'Enter a valid email' => 'ਸਹੀ ਈਮੇਲ ਭਰੋ',
  'Email is required' => 'ਈਮੇਲ ਲਾਜ਼ਮੀ ਹੈ',
  'Enter a valid 10-digit mobile number' => 'ਸਹੀ 10 ਅੰਕਾਂ ਦਾ ਮੋਬਾਈਲ ਨੰਬਰ ਭਰੋ',
  'Mobile number is required' => 'ਮੋਬਾਈਲ ਨੰਬਰ ਲਾਜ਼ਮੀ ਹੈ',
  'Enter a valid 12-digit Aadhaar number' => 'ਸਹੀ 12 ਅੰਕਾਂ ਦਾ ਆਧਾਰ ਨੰਬਰ ਭਰੋ',
  'Aadhaar number is required' => 'ਆਧਾਰ ਨੰਬਰ ਲਾਜ਼ਮੀ ਹੈ',
  'Enter a valid, not-expired date' => 'ਸਹੀ ਤਾਰੀਖ਼ ਭਰੋ ਜਿਸਦੀ ਮਿਆਦ ਖ਼ਤਮ ਨਾ ਹੋਈ ਹੋਵੇ',
  'Enter a date between today and one year ahead' => 'ਅੱਜ ਤੋਂ ਲੈ ਕੇ ਇੱਕ ਸਾਲ ਅੱਗੇ ਤੱਕ ਦੀ ਤਾਰੀਖ਼ ਭਰੋ',
  'Enter a valid date of birth (minimum age 14)' => 'ਸਹੀ ਜਨਮ ਤਾਰੀਖ਼ ਭਰੋ (ਘੱਟੋ-ਘੱਟ ਉਮਰ 14 ਸਾਲ)',
  'Enter an amount between ₹' => 'ਇਸ ਵਿਚਕਾਰ ਰਕਮ ਭਰੋ: ₹',
  'Enter a valid number' => 'ਸਹੀ ਨੰਬਰ ਭਰੋ',
  'Enter a valid 6-digit PIN code' => 'ਸਹੀ 6 ਅੰਕਾਂ ਦਾ PIN ਕੋਡ ਭਰੋ',
  'Select State / UT' => 'ਰਾਜ / ਕੇਂਦਰ ਸ਼ਾਸਿਤ ਪ੍ਰਦੇਸ਼ ਚੁਣੋ',
  'Select an option' => 'ਇੱਕ ਵਿਕਲਪ ਚੁਣੋ',
  'Select at least one option' => 'ਘੱਟੋ-ਘੱਟ ਇੱਕ ਵਿਕਲਪ ਚੁਣੋ',
  'Select or type at least one' => 'ਘੱਟੋ-ਘੱਟ ਇੱਕ ਚੁਣੋ ਜਾਂ ਲਿਖੋ',
  'Please take a live selfie' => 'ਕਿਰਪਾ ਕਰਕੇ ਲਾਈਵ ਸੈਲਫ਼ੀ ਲਓ',
  'Please upload a photo' => 'ਕਿਰਪਾ ਕਰਕੇ ਫ਼ੋਟੋ ਅੱਪਲੋਡ ਕਰੋ',
  'Enter a valid video link (https://…)' => 'ਸਹੀ ਵੀਡੀਓ ਲਿੰਕ ਭਰੋ (https://…)',
  'Upload a demo video or give a video link' => 'ਡੈਮੋ ਵੀਡੀਓ ਅੱਪਲੋਡ ਕਰੋ ਜਾਂ ਵੀਡੀਓ ਲਿੰਕ ਦਿਓ',
  'Enter GST number or tick “I don’t have GST”' => 'GST ਨੰਬਰ ਭਰੋ ਜਾਂ “ਮੇਰੇ ਕੋਲ GST ਨਹੀਂ ਹੈ” ਉੱਤੇ ਟਿੱਕ ਕਰੋ',
  'Enter a valid 15-character GST number' => 'ਸਹੀ 15 ਅੱਖਰਾਂ ਦਾ GST ਨੰਬਰ ਭਰੋ',
  'Enter your passport number' => 'ਆਪਣਾ ਪਾਸਪੋਰਟ ਨੰਬਰ ਭਰੋ',
  'Enter a valid passport number (e.g. K1234567)' => 'ਸਹੀ ਪਾਸਪੋਰਟ ਨੰਬਰ ਭਰੋ (ਜਿਵੇਂ K1234567)',
  'Enter bank account number' => 'ਬੈਂਕ ਖਾਤਾ ਨੰਬਰ ਭਰੋ',
  'Enter a valid account number / IBAN' => 'ਸਹੀ ਖਾਤਾ ਨੰਬਰ / IBAN ਭਰੋ',
  'Enter a valid account number (9–18 digits)' => 'ਸਹੀ ਖਾਤਾ ਨੰਬਰ ਭਰੋ (9–18 ਅੰਕ)',
  'Enter IFSC code' => 'IFSC ਕੋਡ ਭਰੋ',
  'Enter a valid SWIFT / BIC code' => 'ਸਹੀ SWIFT / BIC ਕੋਡ ਭਰੋ',
  'Enter a valid IFSC code (e.g. SBIN0001234)' => 'ਸਹੀ IFSC ਕੋਡ ਭਰੋ (ਜਿਵੇਂ SBIN0001234)',
  'Enter the expected stipend for a paid internship (₹8,000 – ₹5,00,000)' => 'ਪੇਡ ਇੰਟਰਨਸ਼ਿਪ ਲਈ ਉਮੀਦ ਕੀਤਾ ਸਟਾਈਪੈਂਡ ਭਰੋ (₹8,000 – ₹5,00,000)',
  'Please accept all terms & conditions' => 'ਕਿਰਪਾ ਕਰਕੇ ਸਾਰੇ ਨਿਯਮ ਅਤੇ ਸ਼ਰਤਾਂ ਸਵੀਕਾਰ ਕਰੋ',
  'File could not be uploaded' => 'ਫ਼ਾਈਲ ਅੱਪਲੋਡ ਨਹੀਂ ਹੋ ਸਕੀ',
  'File is larger than 5MB' => 'ਫ਼ਾਈਲ 5MB ਤੋਂ ਵੱਡੀ ਹੈ',
  'Only PDF, DOC, DOCX, JPG or PNG files' => 'ਸਿਰਫ਼ PDF, DOC, DOCX, JPG ਜਾਂ PNG ਫ਼ਾਈਲਾਂ',
  'Only PDF, DOC or DOCX files' => 'ਸਿਰਫ਼ PDF, DOC ਜਾਂ DOCX ਫ਼ਾਈਲਾਂ',
  'Photo could not be uploaded' => 'ਫ਼ੋਟੋ ਅੱਪਲੋਡ ਨਹੀਂ ਹੋ ਸਕੀ',
  'Photo is larger than 5MB' => 'ਫ਼ੋਟੋ 5MB ਤੋਂ ਵੱਡੀ ਹੈ',
  'Only a clear JPG, PNG or WEBP photo (at least 100×100)' => 'ਸਿਰਫ਼ ਸਾਫ਼ JPG, PNG ਜਾਂ WEBP ਫ਼ੋਟੋ (ਘੱਟੋ-ਘੱਟ 100×100)',
  'Video is larger than 200MB – please give a link instead' => 'ਵੀਡੀਓ 200MB ਤੋਂ ਵੱਡੀ ਹੈ – ਕਿਰਪਾ ਕਰਕੇ ਇਸਦੀ ਥਾਂ ਲਿੰਕ ਦਿਓ',
  'Video could not be uploaded – retry or give a link' => 'ਵੀਡੀਓ ਅੱਪਲੋਡ ਨਹੀਂ ਹੋ ਸਕੀ – ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ ਜਾਂ ਲਿੰਕ ਦਿਓ',
  'Only video files (MP4, MOV, WEBM, MKV, 3GP)' => 'ਸਿਰਫ਼ ਵੀਡੀਓ ਫ਼ਾਈਲਾਂ (MP4, MOV, WEBM, MKV, 3GP)',
  'Apply on Jobsence – Skill Development, Internship, Full-time, Part-time and Work from Home registration. 3000+ categories, Hindi + English forms, one-time fee ₹155 incl. GST. भारत को कुशल बनाने की Jobsence पहल.' => 'Jobsence ਉੱਤੇ ਅਪਲਾਈ ਕਰੋ – ਸਕਿੱਲ ਡਿਵੈਲਪਮੈਂਟ, ਇੰਟਰਨਸ਼ਿਪ, ਫੁੱਲ-ਟਾਈਮ, ਪਾਰਟ-ਟਾਈਮ ਅਤੇ ਘਰ ਤੋਂ ਕੰਮ ਲਈ ਰਜਿਸਟ੍ਰੇਸ਼ਨ। 3000+ ਸ਼੍ਰੇਣੀਆਂ, ਹਿੰਦੀ + ਅੰਗਰੇਜ਼ੀ ਫ਼ਾਰਮ, ਇੱਕ ਵਾਰ ਦੀ ਫ਼ੀਸ ₹155 GST ਸਮੇਤ। ਭਾਰਤ ਨੂੰ ਹੁਨਰਮੰਦ ਬਣਾਉਣ ਦੀ Jobsence ਪਹਿਲਕਦਮੀ।',
  'Enter the correct answer to the security question' => 'ਸੁਰੱਖਿਆ ਸਵਾਲ ਦਾ ਸਹੀ ਜਵਾਬ ਭਰੋ',
  'Write your profession' => 'ਆਪਣਾ ਪੇਸ਼ਾ ਲਿਖੋ',
  'Please verify your email with OTP before continuing' => 'ਅੱਗੇ ਵਧਣ ਤੋਂ ਪਹਿਲਾਂ ਕਿਰਪਾ ਕਰਕੇ OTP ਨਾਲ ਆਪਣੀ ਈਮੇਲ ਦੀ ਤਸਦੀਕ ਕਰੋ',
  'File could not be saved, please retry' => 'ਫ਼ਾਈਲ ਸੇਵ ਨਹੀਂ ਹੋ ਸਕੀ, ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ',
  'Photo could not be saved, please retry' => 'ਫ਼ੋਟੋ ਸੇਵ ਨਹੀਂ ਹੋ ਸਕੀ, ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ',
  'Server error, please try again' => 'ਸਰਵਰ ਗੜਬੜੀ, ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ',
  'employer' => 'ਰੁਜ਼ਗਾਰਦਾਤਾ',
  'candidate' => 'ਉਮੀਦਵਾਰ',
  'The two PINs do not match' => 'ਦੋਵੇਂ PIN ਮੇਲ ਨਹੀਂ ਖਾਂਦੇ',
  'changed' => 'ਬਦਲਿਆ ਗਿਆ',
  'removed' => 'ਹਟਾਇਆ ਗਿਆ',
  'Skill Development – All Skills' => 'ਸਕਿੱਲ ਡਿਵੈਲਪਮੈਂਟ – ਸਾਰੇ ਹੁਨਰ',
  'Looking for skill development in this?' => 'ਕੀ ਤੁਸੀਂ ਇਸ ਵਿੱਚ ਹੁਨਰ ਸਿੱਖਣਾ ਚਾਹੁੰਦੇ ਹੋ?',
  'Can you provide skill in this?' => 'ਕੀ ਤੁਸੀਂ ਇਸ ਵਿੱਚ ਹੁਨਰ ਸਿਖਾ ਸਕਦੇ ਹੋ?',
  'mentors' => 'ਮੈਂਟਰ',
  'skills' => 'ਹੁਨਰ',
  'Internships – All Domains' => 'ਇੰਟਰਨਸ਼ਿਪ – ਸਾਰੇ ਖੇਤਰ',
  'Looking for an internship in this?' => 'ਕੀ ਤੁਸੀਂ ਇਸ ਵਿੱਚ ਇੰਟਰਨਸ਼ਿਪ ਲੱਭ ਰਹੇ ਹੋ?',
  'Can you offer internships in this?' => 'ਕੀ ਤੁਸੀਂ ਇਸ ਵਿੱਚ ਇੰਟਰਨਸ਼ਿਪ ਦੇ ਸਕਦੇ ਹੋ?',
  'seekers' => 'ਲੱਭਣ ਵਾਲੇ',
  'providers' => 'ਪ੍ਰਦਾਤਾ',
  'domains' => 'ਖੇਤਰ',
  'Jobs – All Categories' => 'ਨੌਕਰੀਆਂ – ਸਾਰੀਆਂ ਸ਼੍ਰੇਣੀਆਂ',
  'Looking for a job in this?' => 'ਕੀ ਤੁਸੀਂ ਇਸ ਵਿੱਚ ਨੌਕਰੀ ਲੱਭ ਰਹੇ ਹੋ?',
  'Hiring for this?' => 'ਕੀ ਤੁਸੀਂ ਇਸ ਲਈ ਭਰਤੀ ਕਰ ਰਹੇ ਹੋ?',
  'job seekers' => 'ਨੌਕਰੀ ਲੱਭਣ ਵਾਲੇ',
  'open jobs' => 'ਖੁੱਲ੍ਹੀਆਂ ਨੌਕਰੀਆਂ',
  'Near Me – All Services' => 'Near Me – ਸਾਰੀਆਂ ਸੇਵਾਵਾਂ',
  'Need this service near you?' => 'ਕੀ ਤੁਹਾਨੂੰ ਇਹ ਸੇਵਾ ਆਪਣੇ ਨੇੜੇ ਚਾਹੀਦੀ ਹੈ?',
  'Do you provide this service?' => 'ਕੀ ਤੁਸੀਂ ਇਹ ਸੇਵਾ ਦਿੰਦੇ ਹੋ?',
  'verified providers' => 'ਤਸਦੀਕਸ਼ੁਦਾ ਪ੍ਰਦਾਤਾ',
  'services' => 'ਸੇਵਾਵਾਂ',
  'Apprenticeships' => 'ਅਪ੍ਰੈਂਟਿਸਸ਼ਿਪ',
  'Skill development' => 'ਸਕਿੱਲ ਡਿਵੈਲਪਮੈਂਟ',
  'This link is not valid or payment is pending' => 'ਇਹ ਲਿੰਕ ਵੈਧ ਨਹੀਂ ਹੈ ਜਾਂ ਭੁਗਤਾਨ ਬਾਕੀ ਹੈ',
  'Choose a plan' => 'ਪਲਾਨ ਚੁਣੋ',
  'Could not start the plan, please try again' => 'ਪਲਾਨ ਸ਼ੁਰੂ ਨਹੀਂ ਹੋ ਸਕਿਆ, ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ',
  'Use “Full profile” in the list to open this profile' => 'ਇਹ ਪ੍ਰੋਫ਼ਾਈਲ ਖੋਲ੍ਹਣ ਲਈ ਸੂਚੀ ਵਿੱਚ “ਪੂਰੀ ਪ੍ਰੋਫ਼ਾਈਲ” ਵਰਤੋ',
  'First open your dashboard from the link in your email / receipt' => 'ਪਹਿਲਾਂ ਆਪਣੀ ਈਮੇਲ / ਰਸੀਦ ਵਿਚਲੇ ਲਿੰਕ ਤੋਂ ਆਪਣਾ ਡੈਸ਼ਬੋਰਡ ਖੋਲ੍ਹੋ',
  'OTP sent to your email (valid for 10 minutes)' => 'OTP ਤੁਹਾਡੀ ਈਮੇਲ ਉੱਤੇ ਭੇਜਿਆ ਗਿਆ ਹੈ (10 ਮਿੰਟ ਲਈ ਵੈਧ)',
  'Accept the agreement terms before signing' => 'ਦਸਤਖ਼ਤ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਸਮਝੌਤੇ ਦੀਆਂ ਸ਼ਰਤਾਂ ਸਵੀਕਾਰ ਕਰੋ',
  'Request declined' => 'ਬੇਨਤੀ ਨਾਮਨਜ਼ੂਰ ਕੀਤੀ ਗਈ',
  'Tick the box to confirm' => 'ਪੁਸ਼ਟੀ ਕਰਨ ਲਈ ਡੱਬੇ ਉੱਤੇ ਟਿੱਕ ਕਰੋ',
  'Agreement ended. Your registration is closed – fill a new form for a new mentor / internship.' => 'ਸਮਝੌਤਾ ਖ਼ਤਮ ਹੋ ਗਿਆ। ਤੁਹਾਡੀ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਬੰਦ ਹੋ ਗਈ ਹੈ – ਨਵੇਂ ਮੈਂਟਰ / ਇੰਟਰਨਸ਼ਿਪ ਲਈ ਨਵਾਂ ਫ਼ਾਰਮ ਭਰੋ।',
  'Agreement ended. The candidate’s registration stays open.' => 'ਸਮਝੌਤਾ ਖ਼ਤਮ ਹੋ ਗਿਆ। ਉਮੀਦਵਾਰ ਦੀ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਖੁੱਲ੍ਹੀ ਰਹੇਗੀ।',
  'An active Near Me pass is needed to rate' => 'ਰੇਟਿੰਗ ਦੇਣ ਲਈ ਸਰਗਰਮ Near Me ਪਾਸ ਲੋੜੀਂਦਾ ਹੈ',
  'Choose 1 to 5 stars' => '1 ਤੋਂ 5 ਸਟਾਰ ਚੁਣੋ',
  'Thank you! Your rating has been saved.' => 'ਧੰਨਵਾਦ! ਤੁਹਾਡੀ ਰੇਟਿੰਗ ਸੇਵ ਹੋ ਗਈ ਹੈ।',
  'No. This is Jobsence’s own initiative to make India skilled. It is NOT a Government of India scheme or programme.' => 'ਨਹੀਂ। ਇਹ ਭਾਰਤ ਨੂੰ ਹੁਨਰਮੰਦ ਬਣਾਉਣ ਲਈ Jobsence ਦੀ ਆਪਣੀ ਪਹਿਲਕਦਮੀ ਹੈ। ਇਹ ਭਾਰਤ ਸਰਕਾਰ ਦੀ ਕੋਈ ਯੋਜਨਾ ਜਾਂ ਪ੍ਰੋਗਰਾਮ ਨਹੀਂ ਹੈ।',
  'What is the registration fee? Is it refundable?' => 'ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਫ਼ੀਸ ਕਿੰਨੀ ਹੈ? ਕੀ ਇਹ ਵਾਪਸ ਹੁੰਦੀ ਹੈ?',
  'What is the course fee after selection?' => 'ਚੋਣ ਤੋਂ ਬਾਅਦ ਕੋਰਸ ਫ਼ੀਸ ਕਿੰਨੀ ਹੈ?',
  'Is a job guaranteed?' => 'ਕੀ ਨੌਕਰੀ ਦੀ ਗਰੰਟੀ ਹੈ?',
  'No. Jobsence does not guarantee any job or placement. We try to push your resume to interested companies, make you job-ready, or guide you towards self-employment.' => 'ਨਹੀਂ। Jobsence ਕਿਸੇ ਵੀ ਨੌਕਰੀ ਜਾਂ ਪਲੇਸਮੈਂਟ ਦੀ ਗਰੰਟੀ ਨਹੀਂ ਦਿੰਦਾ। ਅਸੀਂ ਤੁਹਾਡਾ ਰਿਜ਼ਿਊਮੇ ਦਿਲਚਸਪੀ ਰੱਖਣ ਵਾਲੀਆਂ ਕੰਪਨੀਆਂ ਤੱਕ ਪਹੁੰਚਾਉਣ, ਤੁਹਾਨੂੰ ਨੌਕਰੀ ਲਈ ਤਿਆਰ ਕਰਨ, ਜਾਂ ਸਵੈ-ਰੁਜ਼ਗਾਰ ਵੱਲ ਮਾਰਗਦਰਸ਼ਨ ਦੇਣ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰਦੇ ਹਾਂ।',
  'When and how will classes happen?' => 'ਕਲਾਸਾਂ ਕਦੋਂ ਅਤੇ ਕਿਵੇਂ ਹੋਣਗੀਆਂ?',
  'Classes are 2 hours per day, 3 days a week, including practical training. Online video classes are available Pan-India; offline classes only in Delhi-NCR.' => 'ਕਲਾਸਾਂ ਹਫ਼ਤੇ ਵਿੱਚ 3 ਦਿਨ, ਰੋਜ਼ਾਨਾ 2 ਘੰਟੇ ਹੁੰਦੀਆਂ ਹਨ, ਜਿਸ ਵਿੱਚ ਪ੍ਰੈਕਟੀਕਲ ਸਿਖਲਾਈ ਸ਼ਾਮਲ ਹੈ। ਔਨਲਾਈਨ ਵੀਡੀਓ ਕਲਾਸਾਂ ਪੂਰੇ ਭਾਰਤ ਵਿੱਚ ਉਪਲਬਧ ਹਨ; ਆਫ਼ਲਾਈਨ ਕਲਾਸਾਂ ਸਿਰਫ਼ ਦਿੱਲੀ-NCR ਵਿੱਚ।',
  'How long after submitting the form?' => 'ਫ਼ਾਰਮ ਜਮ੍ਹਾਂ ਕਰਨ ਤੋਂ ਬਾਅਦ ਕਿੰਨਾ ਸਮਾਂ ਲੱਗੇਗਾ?',
  'Scrutiny of forms and resumes takes a minimum of 3 to 6 months.' => 'ਫ਼ਾਰਮਾਂ ਅਤੇ ਰਿਜ਼ਿਊਮਿਆਂ ਦੀ ਪੜਤਾਲ ਵਿੱਚ ਘੱਟੋ-ਘੱਟ 3 ਤੋਂ 6 ਮਹੀਨੇ ਲੱਗਦੇ ਹਨ।',
  'Who can apply?' => 'ਕੌਣ ਅਪਲਾਈ ਕਰ ਸਕਦਾ ਹੈ?',
  'Anyone unemployed – uneducated, 10th/12th pass, ITI, graduates, engineers, doctors, drivers, homemakers – from any village, district, city or capital in India.' => 'ਕੋਈ ਵੀ ਬੇਰੁਜ਼ਗਾਰ – ਅਨਪੜ੍ਹ, 10ਵੀਂ/12ਵੀਂ ਪਾਸ, ITI, ਗ੍ਰੈਜੂਏਟ, ਇੰਜੀਨੀਅਰ, ਡਾਕਟਰ, ਡਰਾਈਵਰ, ਘਰੇਲੂ ਔਰਤਾਂ – ਭਾਰਤ ਦੇ ਕਿਸੇ ਵੀ ਪਿੰਡ, ਜ਼ਿਲ੍ਹੇ, ਸ਼ਹਿਰ ਜਾਂ ਰਾਜਧਾਨੀ ਤੋਂ।',
  'In which language is training given?' => 'ਸਿਖਲਾਈ ਕਿਸ ਭਾਸ਼ਾ ਵਿੱਚ ਦਿੱਤੀ ਜਾਂਦੀ ਹੈ?',
  'In Hindi, English or a local/regional language, depending on mentor availability.' => 'ਮੈਂਟਰ ਦੀ ਉਪਲਬਧਤਾ ਅਨੁਸਾਰ ਹਿੰਦੀ, ਅੰਗਰੇਜ਼ੀ ਜਾਂ ਸਥਾਨਕ/ਖੇਤਰੀ ਭਾਸ਼ਾ ਵਿੱਚ।',
  'Who conducts the training?' => 'ਸਿਖਲਾਈ ਕੌਣ ਦਿੰਦਾ ਹੈ?',
  'Training is conducted through third-party skill development partners and registered mentors.' => 'ਸਿਖਲਾਈ ਥਰਡ-ਪਾਰਟੀ ਸਕਿੱਲ ਡਿਵੈਲਪਮੈਂਟ ਭਾਈਵਾਲਾਂ ਅਤੇ ਰਜਿਸਟਰਡ ਮੈਂਟਰਾਂ ਰਾਹੀਂ ਦਿੱਤੀ ਜਾਂਦੀ ਹੈ।',
  'Can I join as a mentor / trainer?' => 'ਕੀ ਮੈਂ ਮੈਂਟਰ / ਟ੍ਰੇਨਰ ਵਜੋਂ ਜੁੜ ਸਕਦਾ/ਸਕਦੀ ਹਾਂ?',
);
